INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C1','soc',5,2,'u2',1,'조선의 건국 — 고려 말 외적의 잦은 침입, 일부 지배층의 횡포, 불교의 부패로 백성의 삶이 힘들어지자 고려 사회의 문제를 바로잡으려던 이성계가 일부 신진 사대부(유교를 공부한 새 세력)와 함께 고려를 무너뜨리고 조선을 세움 · 한양(오늘날 서울의 한강 북쪽)을 새 수도로 정함 · 고려는 불교, 조선은 유교를 나라의 바탕으로 삼음(생각은 한꺼번에 바뀌지 않아 불교를 믿는 사람도 많았음)',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C2','soc',5,2,'u2',1,'한양의 건축물에 담긴 유교 덕목 — 도성의 문과 건물 이름에 인·의·예·지 같은 유교 덕목을 담음(흥인지문의 인, 돈의문의 의, 숭례문의 예 등) · 백성이 오가며 유교의 가르침을 늘 보고 익히게 하려는 뜻 · 경복궁 근정전 앞마당의 박석·임금과 신하가 다니는 길의 구분에도 질서가 담김',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C3','soc',5,2,'u2',1,'유교의 기본 정신과 교육 기관 — 유교는 충성·효도·질서·믿음을 강조하고 저마다 자신의 역할에 맞게 사는 것을 중요하게 여김(오늘날에도 어른 공경·효도 등으로 이어짐) · 한양에 최고 교육 기관 성균관(오늘날 대학교처럼), 지방 곳곳에 향교(오늘날 중·고등학교처럼)를 두고, 유학자들은 서원·서당을 세움 → 유교의 가르침을 배운 백성이 점차 늘어남',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C4','soc',5,2,'u2',2,'유교를 퍼뜨리고 질서를 세운 노력 — 『삼강행실도』: 유교의 가르침을 모범으로 실천한 충신·효자·열녀 이야기를 모으고 글을 모르는 백성도 알 수 있게 그림을 넣은 책 · 『경국대전』: 유교 중심으로 나라를 다스리는 기본 법전(정치·사회·경제의 기본, 땅과 집을 사고팔면 관청에 알리기 등)으로 백성의 일상생활에 큰 영향',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C5','soc',5,2,'u2',2,'관혼상제와 유교 예절 — 나라의 행사뿐 아니라 백성의 집안 행사도 유교 예절을 따름 · 관례(어른이 되는 의식)·혼례(결혼)·상례(장례)·제례(제사)를 가장 중요하게 여겨 따르게 함 · 오늘날 결혼식·제사·성년의 날 등으로 이어짐',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C6','soc',5,2,'u2',2,'조선의 신분제와 여성의 지위 — 법으로는 양인과 천인이지만 실제로는 양반(공부하고 관리가 됨)·중인(통역·의술 같은 전문적인 일)·상민(농사·장사·물건 만들기, 세금)·천민(노비 등)으로 나뉘어 신분에 맞게 살아야 했음 · 조선 전기에는 고려처럼 아들딸이 재산을 똑같이 받고 제사를 돌아가며 지냈지만, 후기로 갈수록 삼종지도를 따르며 여성의 지위가 낮아짐',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C7','soc',5,2,'u2',3,'세종 시기 농업과 과학의 발전 — 백성이 농사를 잘 지어야 생활이 안정된다고 여김 · 중국 농사책이 조선 환경과 맞지 않아 지방 농부들의 경험을 모아 『농사직설』을 펴냄 · 혼천의(하늘의 움직임)와 측우기(비의 양 — 농사와 알맞은 세금)는 농사에, 앙부일구(그림자로 시각과 계절, 그림을 새기고 거리에 둠)와 자격루(물로 움직이며 저절로 종을 쳐 시각을 알림)는 일상생활에 도움',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C8','soc',5,2,'u2',3,'훈민정음 — 그때 쓰던 한자는 글자 수가 많고 우리말과 달라 배우기 어려움 · 세종이 백성이 쉽게 읽고 쓸 수 있는 글자 훈민정음을 만듦(반대도 있었음) · 백성에게 유교의 가르침을 알리고 문화가 발전하는 데 도움 · 오늘날 한글로 이어지고 한글날에 그 뜻을 기림',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C9','soc',5,2,'u2',4,'조선 전기 주변 나라와의 관계 — 명과는 대체로 좋은 관계를 이어 가며 사신을 보내고 필요한 문물을 받아들임 · 일본·여진과는 무역으로 교류하면서 국경을 넘어와 빼앗으면 무력도 씀(왜구의 소굴 쓰시마섬 공격, 북쪽 여진을 몰아내고 압록강 쪽에 4군·두만강 쪽에 6진을 두어 영토를 넓힘)',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C10','soc',5,2,'u2',4,'임진왜란 — 일본이 많은 군사로 쳐들어온 전쟁 · 조총을 앞세운 일본군에 잇달아 졌지만 이순신이 이끄는 수군, 백성이 스스로 만든 군대인 의병(나라와 임금에 대한 충성이라는 유교 정신), 명군의 도움으로 위기를 이겨 냄 · 땅이 황폐해지는 등 피해가 큼',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C11','soc',5,2,'u2',4,'병자호란 — 여진이 나라를 세워 이름을 청으로 바꾼 뒤 조선에 임금과 신하의 관계를 맺자고 함 · 조선이 거절하자 청이 쳐들어옴 · 인조가 남한산성으로 피했지만 둘러싸였고, 싸우자는 신하와 화해하자는 신하가 맞섬 · 추위와 배고픔 끝에 청에 항복해 임금과 신하의 관계를 맺고 많은 백성이 끌려감',ARRAY['[6사05-01] 조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C12','soc',5,2,'u2',5,'조선 후기 농업의 변화 — 두 번의 전쟁으로 땅이 거칠어지자 농업 생산량을 늘리려 애씀 · 어린 모를 논에 옮겨 심는 모내기법이 전국으로 퍼져 잡초 뽑기가 쉬워지고 일손이 줄며 쌀 생산량이 늘고, 벼를 거둔 땅에 보리를 심어 한 번 더 거둠 → 넓은 땅을 농사지어 잘사는 농민이 나타남 · 외국에서 들어온 고구마·감자(거친 땅에서도 잘 자라 배고픔을 덜어 줌), 고추·인삼·담배(시장에 팔아 이익)',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C13','soc',5,2,'u2',5,'조선 후기 상업의 발달 — 농작물 등을 사고파는 일이 많아지자 사람이 많이 모이는 곳마다 장시가 들어서고 여러 장시를 돌아다니며 장사하는 보부상이 많아짐 · 쌀·옷감은 무겁고 상하기 쉬워 작고 썩지 않는 돈 상평통보가 만들어져 전국에서 쓰임 · 장시는 오늘날 오일장으로 이어짐',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C14','soc',5,2,'u2',6,'조선 후기 신분제의 동요 — 농업과 상업의 발달로 잘살게 된 사람 가운데 돈을 주고 양반 신분을 사는 사람이 나타남(양반은 세금을 거의 내지 않음) · 양반은 늘고 상민과 천민은 줄어 신분제가 흔들림 · 세금을 낼 상민이 줄어 남은 상민의 짐이 무거워짐',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C15','soc',5,2,'u2',6,'서양 문물과 실학 — 중국에 다녀온 사신들이 자명종·천리경·세계지도·과학 기술 책 같은 서양 문물을 들여와 중국을 세계의 중심으로 여기던 생각이 점차 달라짐 · 이론에 치우친 유학이 백성의 어려움을 풀지 못하자 현실의 사회 문제를 풀려는 학문 실학이 나타나 농업·상업·수공업·우리 역사와 지리 등을 연구함',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C16','soc',5,2,'u2',6,'천주교와 동학 — 천주교는 처음에 서양 학문의 하나로 들어왔다가 믿음으로 받아들여짐 · 우리 것을 지킨다는 뜻을 담은 동학(사람이 곧 하늘)도 나타남 · 두 종교는 모든 사람이 평등하다는 생각을 전했고 동학은 새로운 세상이 열린다고 함 · 나라는 두 종교를 탄압했지만 동학은 백성 사이에 더욱 퍼져 사회 변화를 요구함',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C17','soc',5,2,'u2',7,'서민 문화의 발달과 한글 소설 — 농사가 잘되고 장사가 활발해져 살림에 여유가 생긴 서민이 문화와 예술에 관심을 두며 서민 문화가 발달 · 한글 소설에는 여러 신분의 인물이 나와 서민의 감정과 소망을 나타내고 사회의 문제점을 꼬집음 · 인기가 높아지자 책을 빌려주는 곳과 돈을 받고 실감 나게 읽어 주는 전기수가 나타남(글을 몰라도 즐김)',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C18','soc',5,2,'u2',7,'풍속화·민화·판소리·탈놀이 — 풍속화: 화가가 양반·농민·여성·아이 등 백성의 생활 모습을 그린 그림 · 민화: 주로 이름이 알려지지 않은 화가가 그려 생활 공간을 꾸미는 데 쓴 그림으로 장수·복·성공 같은 소망을 담음(호랑이와 까치, 책가도) · 판소리: 소리꾼이 북 치는 사람의 장단에 맞추어 노래·말·몸짓으로 이야기를 풀어 가는 공연 · 탈놀이: 탈을 쓰고 춤추며 양반을 비꼬고 사회의 잘못을 꼬집음 — 구경꾼이 함께 어울려 인기',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C19','soc',5,2,'u2',8,'조선의 개항 — 조선 후기 서양 여러 나라의 배가 해안에 나타나 통상(외국과 서로 물건을 사고팖)을 요구했고 조선은 처음에 거부함 · 점차 외국과 교류하며 새 문물을 받아들이자는 의견이 늘어남(찬성과 반대가 맞섬) · 일본이 무력을 앞세워 조약을 요구하자 강화도에서 조약을 맺고 항구를 엶(강화도 조약 — 외국과 맺은 첫 근대적 조약이지만 불평등 조약) · 이후 서양 여러 나라와도 조약을 맺고 교류를 시작',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C20','soc',5,2,'u2',8,'근대 문물과 달라진 생활 — 서양식 옷(양복)·음식(커피·짜장면 등)·건물이 도시를 중심으로 들어섬 · 외국어 학교·소학교(오늘날 초등학교)·기술 학교가 세워져 외국어·지리·미술·체육 등을 배움 · 전등으로 활동할 수 있는 시간이 늘고, 전신·전화로 소식을 빠르게 주고받음(전화 교환수라는 새 직업) · 전차가 다니며 길이 넓어지고 생활 범위가 넓어졌으며, 자리를 신분이 아니라 비용으로 나누고 남녀가 함께 타 유교 질서에도 변화 · 신문으로 나라 안팎의 소식과 다양한 생각을 접하고 광고로 외국 물건을 알게 됨',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u2-C21','soc',5,2,'u2',9,'역사 만화 그리기 — 단원에서 공부한 생활 모습 가운데 그리고 싶은 주제를 고름 → 어떤 내용을 만화로 나타낼지 정리 → 역사적 상황이 잘 드러나게 그리고 내용에 어울리는 제목을 씀 → 친구들과 감상 · 표현은 자유롭게 해도 핵심 내용은 역사적 사실에서 벗어나면 안 되고, 그때 사람들의 생각과 생활이 드러나야 함',ARRAY['[6사05-02] 조선 후기 사회·문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X01','soc',5,'u2',ARRAY['SO5-2-u2-C1']::text[],'조선을 세운 사람·세력과 건국 배경을 헷갈린다(왕건이 세웠다고, 고려가 너무 잘살아서 바꿨다고)','고려 말 혼란 · 이성계와 신진 사대부') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X02','soc',5,'u2',ARRAY['SO5-2-u2-C1','SO5-2-u2-C3']::text[],'고려와 조선이 바탕으로 삼은 생각을 바꾸어 안다(고려는 유교, 조선은 불교)','고려 불교 · 조선 유교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X03','soc',5,'u2',ARRAY['SO5-2-u2-C2']::text[],'한양의 문·건물 이름을 그냥 멋으로 붙였다고 여겨 유교 덕목을 알리려던 뜻을 놓친다','인·의·예·지 → 늘 보고 익히게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X04','soc',5,'u2',ARRAY['SO5-2-u2-C3']::text[],'유교가 강조한 것을 잘못 안다(누구나 마음대로 하는 자유, 신분 없는 평등, 부처를 믿는 것이라고)','충성·효도·질서·믿음 · 역할에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X05','soc',5,'u2',ARRAY['SO5-2-u2-C3']::text[],'조선의 교육 기관을 바꾸어 안다(성균관이 지방 곳곳에, 서당이 최고 교육 기관이라고)','한양 성균관 · 지방 향교 · 서원·서당') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X06','soc',5,'u2',ARRAY['SO5-2-u2-C4','SO5-2-u2-C7']::text[],'조선이 펴낸 책을 바꾸어 안다(『경국대전』이 효자 이야기책, 『삼강행실도』가 법전, 『농사직설』이 예절 책이라고)','삼강행실도 가르침 · 경국대전 법 · 농사직설 농사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X07','soc',5,'u2',ARRAY['SO5-2-u2-C4']::text[],'『삼강행실도』에 그림을 넣은 까닭을 놓친다(꾸미려고만, 양반만 보라고)','글을 모르는 백성도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X08','soc',5,'u2',ARRAY['SO5-2-u2-C5']::text[],'관혼상제의 뜻을 잘못 알거나 나라 행사만이라고 여겨 집안 행사도 유교 예절을 따랐다는 것을 놓친다','관례·혼례·상례·제례 · 집안 행사까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X09','soc',5,'u2',ARRAY['SO5-2-u2-C6']::text[],'조선의 신분 구분을 잘못 안다(법으로도 실제로도 넷이었다고, 고려처럼 귀족·평민이라고, 신분 없이 살았다고)','법은 양인·천인 · 실제는 양반·중인·상민·천민') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X10','soc',5,'u2',ARRAY['SO5-2-u2-C6']::text[],'신분과 하는 일을 바꾸어 짝짓는다(양반이 통역·의술, 중인이 관리, 상민이 세금을 안 냄)','양반 공부·관리 · 중인 전문 · 상민 농사·장사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X11','soc',5,'u2',ARRAY['SO5-2-u2-C6']::text[],'조선 여성의 지위 변화를 놓친다(처음부터 끝까지 낮았다고, 또는 끝까지 고려와 같았다고)','전기엔 고려처럼 · 후기로 갈수록 낮아짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X12','soc',5,'u2',ARRAY['SO5-2-u2-C7']::text[],'『농사직설』을 만든 까닭을 놓친다(중국 책을 그대로 옮겼다고, 양반의 취미 책이라고)','조선 환경 · 농부들의 경험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X13','soc',5,'u2',ARRAY['SO5-2-u2-C7']::text[],'과학 기구의 쓰임을 바꾸어 안다(측우기로 시각을, 앙부일구로 비의 양을 잰다고)','측우기 비 · 앙부일구 그림자 시각 · 자격루 종') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X14','soc',5,'u2',ARRAY['SO5-2-u2-C7','SO5-2-u2-C8']::text[],'세종 때 만든 것들이 누구를 위한 것인지 놓친다(임금과 양반만을 위한 것이라고)','거리에 둔 해시계 · 쉬운 글자 → 백성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X15','soc',5,'u2',ARRAY['SO5-2-u2-C8']::text[],'훈민정음을 만든 까닭과 영향을 잘못 안다(한자를 더 어렵게 하려고, 양반만 쓰게 하려고, 오늘날과 관계없다고)','백성이 쉽게 · 오늘의 한글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X16','soc',5,'u2',ARRAY['SO5-2-u2-C9']::text[],'조선 전기 주변 나라와의 관계를 바꾸어 안다(명과 늘 전쟁, 일본·여진에게서 문물을 받아들였다고)','명 사신·문물 · 일본·여진 무역 + 필요할 때 무력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X17','soc',5,'u2',ARRAY['SO5-2-u2-C9']::text[],'쓰시마섬 공격과 4군 6진의 대상·까닭을 헷갈린다','쓰시마 왜구 · 4군 6진 여진') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X18','soc',5,'u2',ARRAY['SO5-2-u2-C10']::text[],'임진왜란을 이겨 낸 힘을 하나로만 보거나 의병을 나라 군대로 안다','수군·의병·명군 · 의병은 백성이 스스로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X19','soc',5,'u2',ARRAY['SO5-2-u2-C10','SO5-2-u2-C11']::text[],'임진왜란과 병자호란을 바꾸어 안다(청이 쳐들어온 것을 임진왜란으로)','일본 → 임진왜란 · 청 → 병자호란') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X20','soc',5,'u2',ARRAY['SO5-2-u2-C11']::text[],'병자호란의 까닭과 결과를 잘못 안다(조선이 이겼다고, 조선이 먼저 쳐들어갔다고)','관계 요구 거절 → 침입 → 남한산성 → 항복') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X21','soc',5,'u2',ARRAY['SO5-2-u2-C12']::text[],'모내기법의 효과를 거꾸로 안다(일손이 더 들었다고, 쌀이 줄었다고, 한 해에 한 번만 거둔다고)','잡초 쉽게 · 일손 줄고 · 벼 다음 보리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X22','soc',5,'u2',ARRAY['SO5-2-u2-C12']::text[],'새로 들어온 작물의 쓰임을 바꾸어 안다(고추·담배로 배고픔을 덜었다고, 고구마·감자는 팔기만 했다고)','고구마·감자 배고픔 · 고추·인삼·담배 이익') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X23','soc',5,'u2',ARRAY['SO5-2-u2-C13']::text[],'장시·보부상·상평통보를 헷갈리거나 돈이 필요해진 까닭을 놓친다','장 · 돌아다니는 상인 · 작고 썩지 않는 돈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X24','soc',5,'u2',ARRAY['SO5-2-u2-C14']::text[],'조선 후기 신분 변화를 거꾸로 안다(양반이 줄고 상민이 늘었다고, 신분이 더 굳어졌다고)','양반 늘고 상민·천민 줄어 흔들림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X25','soc',5,'u2',ARRAY['SO5-2-u2-C14']::text[],'양반이 늘어난 것이 나라 살림과 남은 상민에게 준 영향을 놓친다','세금 낼 사람이 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X26','soc',5,'u2',ARRAY['SO5-2-u2-C15']::text[],'서양 문물이 사람들의 생각을 바꾼 것을 놓친다(중국이 세계의 중심이라는 생각이 그대로였다고, 문물이 일본에서 처음 왔다고)','사신이 들여온 세계지도 → 생각이 달라짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X27','soc',5,'u2',ARRAY['SO5-2-u2-C15']::text[],'실학의 뜻을 잘못 안다(이론만 따지는 학문, 서양 종교, 과거 시험 과목이라고)','현실의 사회 문제를 푸는 학문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X28','soc',5,'u2',ARRAY['SO5-2-u2-C16']::text[],'천주교와 동학을 바꾸어 알거나 두 종교가 전한 평등의 생각을 놓친다','서양에서 온 천주교 · 우리 것을 지킨 동학 · 모두 평등') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X29','soc',5,'u2',ARRAY['SO5-2-u2-C17','SO5-2-u2-C18']::text[],'서민 문화가 발달한 까닭을 놓친다(양반만 즐겼다고, 서민은 여유가 전혀 없었다고)','농사·장사로 생긴 여유') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X30','soc',5,'u2',ARRAY['SO5-2-u2-C17']::text[],'한글 소설과 전기수의 역할을 잘못 안다(전기수를 소리꾼으로, 한글 소설은 양반 이야기만이라고)','돈 받고 읽어 주는 사람 · 서민의 감정과 소망') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X31','soc',5,'u2',ARRAY['SO5-2-u2-C18']::text[],'풍속화와 민화를 바꾸어 알거나 민화에 담긴 소망을 놓친다','풍속화 생활 모습 · 민화 소망과 꾸밈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X32','soc',5,'u2',ARRAY['SO5-2-u2-C18']::text[],'판소리와 탈놀이를 바꾸어 알거나 탈놀이가 양반을 비꼰 까닭을 놓친다','판소리 북 장단 · 탈놀이 탈 쓰고 비꼼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X33','soc',5,'u2',ARRAY['SO5-2-u2-C19']::text[],'개항 과정을 잘못 안다(조선이 처음부터 통상을 원했다고, 서양과 먼저 조약을 맺었다고, 찬반 없이 모두 찬성했다고)','처음엔 거부 · 일본과 강화도 조약 · 뒤에 서양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X34','soc',5,'u2',ARRAY['SO5-2-u2-C19']::text[],'강화도 조약을 두 나라에 똑같이 공평한 조약이었다고 여긴다','첫 근대적 조약 · 그러나 불평등') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X35','soc',5,'u2',ARRAY['SO5-2-u2-C20']::text[],'근대 문물과 달라진 생활을 바꾸어 짝짓는다(전등으로 소식을, 전화로 밤을 밝혔다고)','전등 시간 · 전신·전화 소식 · 전차 거리 · 신문 소식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X36','soc',5,'u2',ARRAY['SO5-2-u2-C20']::text[],'근대 문물이 생각(유교 질서)까지 바꾼 것을 놓친다(전차 자리를 신분으로 나눴다고)','비용으로 자리 · 남녀가 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X37','soc',5,'u2',ARRAY['SO5-2-u2-C20']::text[],'개항 이후 생활 변화를 한쪽으로만 본다(모두가 곧바로 서양식으로만 살았다고, 아무것도 달라지지 않았다고)','한복과 양복이 함께 · 도시부터 조금씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X38','soc',5,'u2',ARRAY['SO5-2-u2-C21']::text[],'역사 만화를 그릴 때 사실과 어긋난 내용이나 다른 시대의 물건을 넣는다','표현은 자유 · 내용은 역사적 사실') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X39','soc',5,'u2',ARRAY['SO5-2-u2-C7','SO5-2-u2-C13','SO5-2-u2-C20']::text[],'조선 전기·후기·개항 이후의 일을 섞는다(세종 때 상평통보, 임진왜란 때 전차를 썼다고)','전기 → 후기 → 개항 차례') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u2-X40','soc',5,'u2',ARRAY['SO5-2-u2-C3','SO5-2-u2-C14','SO5-2-u2-C20']::text[],'이름과 연도를 외우는 것만 역사 공부로 여겨 유교·사회 변화가 생활에 준 영향을 놓친다','외우기보다 생활과 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#1','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C1',1,'sa','auto','고려를 무너뜨리고 조선을 세운 사람은 누구인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C1","difficulty":1,"kind":"sa","stem":"고려를 무너뜨리고 조선을 세운 사람은 누구인가요? 세 글자로 쓰세요.","answer":["이성계"],"explanation":["고려 말 장수였어요.","신진 사대부와 함께했어요.","이성계예요."],"mis":"SO5-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#2','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C1',1,'mc','auto','조선이 새 수도로 정한 곳은 어디인가요?',ARRAY['SO5-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C1","difficulty":1,"kind":"mc","stem":"조선이 새 수도로 정한 곳은 어디인가요?","options":[{"t":"한양","correct":true},{"t":"개경","mis":"SO5-2-u2-X01"},{"t":"경주","mis":"SO5-2-u2-X01"},{"t":"평양","mis":"SO5-2-u2-X01"}],"explanation":["오늘날 서울이에요.","한강 북쪽이에요.","한양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#3','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C3',1,'mc','auto','조선이 나라의 바탕으로 삼은 생각은 어느 것인가요?',ARRAY['SO5-2-u2-X02','SO5-2-u2-X28']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C3","difficulty":1,"kind":"mc","stem":"조선이 나라의 바탕으로 삼은 생각은 어느 것인가요?","options":[{"t":"유교","correct":true},{"t":"불교","mis":"SO5-2-u2-X02"},{"t":"천주교","mis":"SO5-2-u2-X28"},{"t":"동학","mis":"SO5-2-u2-X28"}],"explanation":["고려는 불교였어요.","조선은 바꾸었어요.","유교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#4','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C3',1,'ox','auto','성균관은 한양에 있던 조선의 최고 교육 기관이에요.',ARRAY['SO5-2-u2-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C3","difficulty":1,"kind":"ox","stem":"성균관은 한양에 있던 조선의 최고 교육 기관이에요.","answer":"O","reason_options":[{"t":"한양에 두어 유교를 가르친 가장 높은 교육 기관이기 때문에","correct":true},{"t":"성균관은 마을마다 있던 작은 글방이기 때문에","mis":"SO5-2-u2-X05"}],"mis":"SO5-2-u2-X05","explanation":["한양에 있었어요.","가장 높은 교육 기관이에요.","오늘날 대학교 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#5','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C1',2,'mc','auto','고려 말 기록 메모로 보아 조선이 세워진 배경으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X01','SO5-2-u2-X39']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C1","difficulty":2,"kind":"mc","stem":"고려 말 기록 메모로 보아 조선이 세워진 배경으로 알맞은 것은 어느 것인가요?","options":[{"t":"외적의 침입, 지배층의 횡포, 불교의 부패로 백성의 삶이 힘들었다","correct":true},{"t":"고려가 너무 평화로워 바꿀 필요가 생겼다","mis":"SO5-2-u2-X01"},{"t":"서양 배가 나타나 통상을 요구했다","mis":"SO5-2-u2-X39"},{"t":"청이 쳐들어와 임금이 항복했다","mis":"SO5-2-u2-X39"}],"explanation":["외적이 쳐들어왔어요.","지배층과 절이 백성을 힘들게 했어요.","나라를 바로 세우려 했어요."],"asset":{"type":"passage","lines":["① 바다 건너 외적이 자주 쳐들어와 마을이 불탔다.","② 일부 지배층이 백성의 땅을 빼앗았다.","③ 큰 절 몇 곳은 땅과 재물을 쌓아 두고 백성을 돕지 않았다.","④ 유교를 공부한 새 세력이 나라를 바로 세우자고 했다."],"title":"고려 말 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#6','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C2',2,'mc','auto','한양 도성의 문과 건물에 유교 덕목을 담은 이름을 붙인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X03','SO5-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"mc","stem":"한양 도성의 문과 건물에 유교 덕목을 담은 이름을 붙인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"백성이 오가며 유교의 가르침을 늘 보고 익히게 하려고","correct":true},{"t":"외국 사람이 못 들어오게 하려고","mis":"SO5-2-u2-X03"},{"t":"이름이 길면 멋있어 보여서","mis":"SO5-2-u2-X03"},{"t":"불교를 널리 퍼뜨리려고","mis":"SO5-2-u2-X02"}],"explanation":["문은 날마다 지나다녀요.","이름에 덕목이 있어요.","가르침을 알리려 했어요."],"asset":{"type":"passage","lines":["흥인지문 — 「인」 · 어진 마음","돈의문 — 「의」 · 옳은 일을 하는 마음","숭례문 — 「예」 · 예절을 지키는 마음","보신각 — 「신」 · 믿음을 지키는 마음"],"title":"한양 도성의 문·건물과 덕목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#7','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C3',2,'mc','auto','유교가 강조한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X04','SO5-2-u2-X02','SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C3","difficulty":2,"kind":"mc","stem":"유교가 강조한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"충성·효도·질서·믿음과 저마다의 역할에 맞게 사는 것","correct":true},{"t":"신분 없이 누구나 마음대로 사는 것","mis":"SO5-2-u2-X04"},{"t":"부처를 믿고 절을 짓는 것","mis":"SO5-2-u2-X02"},{"t":"서양 문물을 받아들이는 것","mis":"SO5-2-u2-X39"}],"explanation":["효도와 충성이에요.","질서와 믿음도요.","역할에 맞게 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#8','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C3',2,'mc','auto','조선의 교육 기관 카드 나에 해당하는 곳은 어느 것인가요?',ARRAY['SO5-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C3","difficulty":2,"kind":"mc","stem":"조선의 교육 기관 카드 나에 해당하는 곳은 어느 것인가요?","options":[{"t":"향교","correct":true},{"t":"성균관","mis":"SO5-2-u2-X05"},{"t":"서당","mis":"SO5-2-u2-X05"},{"t":"서원","mis":"SO5-2-u2-X05"}],"explanation":["나라가 세웠어요.","지방 곳곳에 있었어요.","향교예요."],"asset":{"type":"passage","lines":["가 — 한양에 있던 나라의 최고 교육 기관","나 — 지방 곳곳에 나라가 세운 교육 기관","다 — 유학자들이 세워 공부하고 훌륭한 학자를 기린 곳","라 — 마을 아이들이 처음 글을 배우던 곳"],"title":"조선의 교육 기관 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#9','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C2',2,'ox','auto','숭례문의 「예」는 예절을 지키는 마음을 뜻하는 유교 덕목이에요.',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"ox","stem":"숭례문의 「예」는 예절을 지키는 마음을 뜻하는 유교 덕목이에요.","answer":"O","reason_options":[{"t":"도성의 남쪽 큰 문에 예를 담아 예절을 지키라는 뜻을 알렸기 때문에","correct":true},{"t":"「예」는 부처님을 뜻하는 말이기 때문에","mis":"SO5-2-u2-X03"}],"mis":"SO5-2-u2-X03","explanation":["숭례문은 남쪽 큰 문이에요.","「예」가 들어 있어요.","예절을 뜻해요."],"asset":{"type":"passage","lines":["흥인지문 — 「인」 · 어진 마음","돈의문 — 「의」 · 옳은 일을 하는 마음","숭례문 — 「예」 · 예절을 지키는 마음","보신각 — 「신」 · 믿음을 지키는 마음"],"title":"한양 도성의 문·건물과 덕목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_basic#10','soc',5,2,'u2','L01','g5_2_soc_u2_L01_basic','lesson_basic','SO5-2-u2-C3',3,'error','auto','조선의 교육을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X05','SO5-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C3","difficulty":3,"kind":"error","stem":"조선의 교육을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「서당은 한양에 하나뿐인 나라의 최고 교육 기관이었어.」","correct":true,"mis_target":"SO5-2-u2-X05"},{"t":"지수 — 「유학자들은 서원을 세워 공부했어.」","mis":"SO5-2-u2-X05"},{"t":"도윤 — 「배운 백성이 늘면서 유교의 가르침도 퍼졌어.」","mis":"SO5-2-u2-X04"}],"explanation":["최고 교육 기관은 성균관이에요.","서당은 마을 글방이에요.","하랑의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#1','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C3',2,'match','auto','조선의 교육 기관 카드와 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C3","difficulty":2,"kind":"match","stem":"조선의 교육 기관 카드와 이름을 알맞게 이으세요.","pairs":[{"l":"가 최고 교육 기관","r":"성균관"},{"l":"나 지방 곳곳","r":"향교"},{"l":"다 학자를 기림","r":"서원"},{"l":"라 마을 아이들","r":"서당"}],"mis":"SO5-2-u2-X05","explanation":["한양은 성균관이에요.","지방은 향교예요.","서원은 유학자, 서당은 마을이에요."],"asset":{"type":"passage","lines":["가 — 한양에 있던 나라의 최고 교육 기관","나 — 지방 곳곳에 나라가 세운 교육 기관","다 — 유학자들이 세워 공부하고 훌륭한 학자를 기린 곳","라 — 마을 아이들이 처음 글을 배우던 곳"],"title":"조선의 교육 기관 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#2','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C2',2,'mc','auto','한양 도성의 문·건물과 덕목에서 「어진 마음」을 담은 문은 어느 것인가요?',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"mc","stem":"한양 도성의 문·건물과 덕목에서 「어진 마음」을 담은 문은 어느 것인가요?","options":[{"t":"흥인지문","correct":true},{"t":"돈의문","mis":"SO5-2-u2-X03"},{"t":"숭례문","mis":"SO5-2-u2-X03"},{"t":"보신각","mis":"SO5-2-u2-X03"}],"explanation":["어진 마음은 「인」이에요.","「인」이 든 이름을 찾아요.","흥인지문이에요."],"asset":{"type":"passage","lines":["흥인지문 — 「인」 · 어진 마음","돈의문 — 「의」 · 옳은 일을 하는 마음","숭례문 — 「예」 · 예절을 지키는 마음","보신각 — 「신」 · 믿음을 지키는 마음"],"title":"한양 도성의 문·건물과 덕목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#3','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C1',3,'mc','auto','고려 말 기록 메모 ④의 「새 세력」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X02','SO5-2-u2-X01','SO5-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C1","difficulty":3,"kind":"mc","stem":"고려 말 기록 메모 ④의 「새 세력」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유교를 공부해 고려 사회의 문제를 바로잡으려 한 신진 사대부","correct":true},{"t":"불교를 더 크게 일으키려던 승려들","mis":"SO5-2-u2-X02"},{"t":"바다를 건너온 외적","mis":"SO5-2-u2-X01"},{"t":"통상을 요구한 서양 상인","mis":"SO5-2-u2-X39"}],"explanation":["유교를 공부했어요.","나라를 바로 세우려 했어요.","신진 사대부예요."],"asset":{"type":"passage","lines":["① 바다 건너 외적이 자주 쳐들어와 마을이 불탔다.","② 일부 지배층이 백성의 땅을 빼앗았다.","③ 큰 절 몇 곳은 땅과 재물을 쌓아 두고 백성을 돕지 않았다.","④ 유교를 공부한 새 세력이 나라를 바로 세우자고 했다."],"title":"고려 말 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#4','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C1',3,'mc','auto','조선이 세워진 뒤에도 불교를 믿는 사람이 많았던 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X02','SO5-2-u2-X04','SO5-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C1","difficulty":3,"kind":"mc","stem":"조선이 세워진 뒤에도 불교를 믿는 사람이 많았던 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"나라의 바탕이 바뀌어도 사람들의 생각은 한꺼번에 바뀌지 않는다","correct":true},{"t":"조선은 불교를 나라의 바탕으로 삼았다","mis":"SO5-2-u2-X02"},{"t":"유교는 조선에 전혀 퍼지지 않았다","mis":"SO5-2-u2-X04"},{"t":"고려와 조선은 같은 나라다","mis":"SO5-2-u2-X01"}],"explanation":["나라는 유교를 택했어요.","사람들의 믿음은 남았어요.","생각은 천천히 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#5','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C3',3,'ox','auto','오늘날 웃어른을 공경하고 부모님께 효도하는 모습에도 유교 정신이 이어져 있어요.',ARRAY['SO5-2-u2-X40']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C3","difficulty":3,"kind":"ox","stem":"오늘날 웃어른을 공경하고 부모님께 효도하는 모습에도 유교 정신이 이어져 있어요.","answer":"O","reason_options":[{"t":"유교가 강조한 효도와 질서가 오늘날 생활에도 남아 있기 때문에","correct":true},{"t":"유교 정신은 조선이 끝나며 모두 사라졌기 때문에","mis":"SO5-2-u2-X40"}],"mis":"SO5-2-u2-X40","explanation":["효도는 유교의 가르침이에요.","오늘도 이어져요.","생활 속에 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#6','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C2',3,'error','auto','한양의 이름들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C2","difficulty":3,"kind":"error","stem":"한양의 이름들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「문 이름은 그냥 부르기 좋게 아무렇게나 지었어.」","correct":true,"mis_target":"SO5-2-u2-X03"},{"t":"태오 — 「돈의문에는 옳은 일을 하는 마음이 담겼어.」","mis":"SO5-2-u2-X03"},{"t":"나린 — 「보신각의 「신」은 믿음이야.」","mis":"SO5-2-u2-X03"}],"explanation":["이름마다 덕목이 담겼어요.","가르침을 알리려 했어요.","윤서의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["흥인지문 — 「인」 · 어진 마음","돈의문 — 「의」 · 옳은 일을 하는 마음","숭례문 — 「예」 · 예절을 지키는 마음","보신각 — 「신」 · 믿음을 지키는 마음"],"title":"한양 도성의 문·건물과 덕목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#7','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C3',3,'mc','auto','조선이 성균관·향교를 세우고 유학자들이 서원·서당을 만든 결과로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X05','SO5-2-u2-X02','SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C3","difficulty":3,"kind":"mc","stem":"조선이 성균관·향교를 세우고 유학자들이 서원·서당을 만든 결과로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유교의 가르침을 배운 백성이 점차 늘어났다","correct":true},{"t":"백성은 글을 배울 수 없게 되었다","mis":"SO5-2-u2-X05"},{"t":"불교 공부가 크게 늘었다","mis":"SO5-2-u2-X02"},{"t":"서양 학문이 널리 퍼졌다","mis":"SO5-2-u2-X39"}],"explanation":["배우는 곳이 늘었어요.","유교를 가르쳤어요.","배운 백성이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#8','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C2',4,'mc','auto','경복궁 근정전 앞마당에 임금과 신하가 다니는 길을 따로 둔 것으로 알 수 있는 조선의 생각은 어느 것인가요?',ARRAY['SO5-2-u2-X04','SO5-2-u2-X03','SO5-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C2","difficulty":4,"kind":"mc","stem":"경복궁 근정전 앞마당에 임금과 신하가 다니는 길을 따로 둔 것으로 알 수 있는 조선의 생각은 어느 것인가요?","options":[{"t":"자리마다 지켜야 할 질서가 있다는 유교의 생각","correct":true},{"t":"모든 사람이 같은 길로 다녀야 한다는 생각","mis":"SO5-2-u2-X04"},{"t":"궁궐 마당은 아무도 쓰지 않는다는 생각","mis":"SO5-2-u2-X03"},{"t":"불교 행사를 크게 열려는 생각","mis":"SO5-2-u2-X02"}],"explanation":["임금의 길과 신하의 길이 달라요.","자리마다 질서가 있어요.","유교의 질서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#9','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C1',4,'mc','auto','조선의 건국을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X01','SO5-2-u2-X02','SO5-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C1","difficulty":4,"kind":"mc","stem":"조선의 건국을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"고려 말 혼란 속에서 이성계와 신진 사대부가 조선을 세우고, 한양을 수도로 삼아 유교를 나라의 바탕으로 했다","correct":true},{"t":"왕건이 고구려를 이어 조선을 세웠다","mis":"SO5-2-u2-X01"},{"t":"조선은 불교를 바탕으로 세운 나라다","mis":"SO5-2-u2-X02"},{"t":"조선은 개항 이후에 세워졌다","mis":"SO5-2-u2-X39"}],"explanation":["고려 말이 혼란했어요.","이성계와 신진 사대부예요.","유교가 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L01_challenge#10','soc',5,2,'u2','L01','g5_2_soc_u2_L01_challenge','lesson_challenge','SO5-2-u2-C2',4,'essay','teacher','한양 도성의 문·건물과 덕목을 보고, 조선이 이런 이름을 붙인 까닭을 쓰고 오늘날 우리 생활에서 볼 수 있는 유교 정신의 모습을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C2","difficulty":4,"kind":"essay","stem":"한양 도성의 문·건물과 덕목을 보고, 조선이 이런 이름을 붙인 까닭을 쓰고 오늘날 우리 생활에서 볼 수 있는 유교 정신의 모습을 하나 쓰세요.","answer_guide":{"answer":"예: 조선은 흥인지문·돈의문·숭례문처럼 문과 건물 이름에 인·의·예·신 같은 유교 덕목을 담아, 백성이 오가며 유교의 가르침을 늘 보고 익히게 하려 했다. 오늘날에도 웃어른께 인사하고 부모님께 효도하는 모습에서 유교 정신을 볼 수 있다.","scoring_points":["이름에 덕목이 담겼다고 썼는가","가르침을 알리려는 까닭을 썼는가","오늘날의 유교 정신 모습을 썼는가"]},"explanation":["이름에 덕목이 있어요.","백성이 익히게 했어요.","오늘의 효도도 그 정신이에요."],"asset":{"type":"passage","lines":["흥인지문 — 「인」 · 어진 마음","돈의문 — 「의」 · 옳은 일을 하는 마음","숭례문 — 「예」 · 예절을 지키는 마음","보신각 — 「신」 · 믿음을 지키는 마음"],"title":"한양 도성의 문·건물과 덕목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#1','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C4',1,'mc','auto','유교의 가르침을 실천한 충신·효자·열녀 이야기를 그림과 함께 실은 책은 어느 것인가요?',ARRAY['SO5-2-u2-X06']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C4","difficulty":1,"kind":"mc","stem":"유교의 가르침을 실천한 충신·효자·열녀 이야기를 그림과 함께 실은 책은 어느 것인가요?","options":[{"t":"『삼강행실도』","correct":true},{"t":"『경국대전』","mis":"SO5-2-u2-X06"},{"t":"『농사직설』","mis":"SO5-2-u2-X06"},{"t":"『직지』","mis":"SO5-2-u2-X06"}],"explanation":["그림이 많아요.","모범 이야기를 실었어요.","『삼강행실도』예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#2','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C4',1,'mc','auto','유교 중심으로 나라를 다스리려고 만든 조선의 기본 법전은 어느 것인가요?',ARRAY['SO5-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C4","difficulty":1,"kind":"mc","stem":"유교 중심으로 나라를 다스리려고 만든 조선의 기본 법전은 어느 것인가요?","options":[{"t":"『경국대전』","correct":true},{"t":"『삼강행실도』","mis":"SO5-2-u2-X06"},{"t":"『농사직설』","mis":"SO5-2-u2-X06"},{"t":"훈민정음","mis":"SO5-2-u2-X06"}],"explanation":["법을 모았어요.","나라를 다스리는 기본이에요.","『경국대전』이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#3','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C6',1,'sa','auto','조선에서 통역이나 의술 같은 전문적인 일을 맡은 신분은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u2-C6","difficulty":1,"kind":"sa","stem":"조선에서 통역이나 의술 같은 전문적인 일을 맡은 신분은 무엇인가요? 두 글자로 쓰세요.","answer":["중인"],"explanation":["양반과 상민 사이예요.","전문적인 일을 했어요.","중인이에요."],"mis":"SO5-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#4','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C5',1,'ox','auto','관혼상제는 어른이 되는 의식·결혼·장례·제사를 함께 이르는 말이에요.',ARRAY['SO5-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C5","difficulty":1,"kind":"ox","stem":"관혼상제는 어른이 되는 의식·결혼·장례·제사를 함께 이르는 말이에요.","answer":"O","reason_options":[{"t":"관례·혼례·상례·제례를 묶어 부르는 말이기 때문에","correct":true},{"t":"관혼상제는 나라의 전쟁 이름이기 때문에","mis":"SO5-2-u2-X08"}],"mis":"SO5-2-u2-X08","explanation":["관은 어른이 되는 의식이에요.","혼은 결혼, 상은 장례예요.","제는 제사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#5','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C4',2,'mc','auto','『삼강행실도』에 그림을 많이 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X07','SO5-2-u2-X06']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C4","difficulty":2,"kind":"mc","stem":"『삼강행실도』에 그림을 많이 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 모르는 백성도 유교의 가르침을 알 수 있게 하려고","correct":true},{"t":"양반만 보게 하려고","mis":"SO5-2-u2-X07"},{"t":"책을 비싸게 팔려고","mis":"SO5-2-u2-X07"},{"t":"법을 숨기려고","mis":"SO5-2-u2-X06"}],"explanation":["글을 모르는 백성이 많았어요.","그림은 누구나 봐요.","가르침을 널리 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#6','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C6',2,'mc','auto','조선 사람 네 명의 하는 일 ㉢에 해당하는 신분은 어느 것인가요?',ARRAY['SO5-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"mc","stem":"조선 사람 네 명의 하는 일 ㉢에 해당하는 신분은 어느 것인가요?","options":[{"t":"상민","correct":true},{"t":"양반","mis":"SO5-2-u2-X10"},{"t":"중인","mis":"SO5-2-u2-X10"},{"t":"천민","mis":"SO5-2-u2-X10"}],"explanation":["농사와 장사를 했어요.","세금을 냈어요.","상민이에요."],"asset":{"type":"passage","lines":["㉠ 공부해서 과거를 보고 관리가 되었다.","㉡ 통역이나 의술 같은 전문적인 일을 맡았다.","㉢ 농사를 짓고 장사를 하며 세금을 냈다.","㉣ 주인집이나 관청의 일을 했다."],"title":"조선 사람 네 명의 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#7','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C6',2,'mc','auto','조선의 신분에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X09']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"mc","stem":"조선의 신분에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"법으로는 양인과 천인이었지만 실제로는 양반·중인·상민·천민으로 나뉘었다","correct":true},{"t":"법으로도 실제로도 귀족·평민·천민이었다","mis":"SO5-2-u2-X09"},{"t":"신분 없이 모두 같은 일을 했다","mis":"SO5-2-u2-X09"},{"t":"법으로는 넷, 실제로는 둘이었다","mis":"SO5-2-u2-X09"}],"explanation":["법은 둘로 나눴어요.","실제로는 넷이었어요.","신분에 맞게 살았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#8','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C5',2,'mc','auto','조선 때 백성의 집안 행사에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X08','SO5-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C5","difficulty":2,"kind":"mc","stem":"조선 때 백성의 집안 행사에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"결혼·장례·제사 같은 집안 행사도 유교 예절을 따랐다","correct":true},{"t":"집안 행사는 아무 예절 없이 했다","mis":"SO5-2-u2-X08"},{"t":"나라 행사만 유교를 따랐다","mis":"SO5-2-u2-X08"},{"t":"집안 행사는 불교 예절만 따랐다","mis":"SO5-2-u2-X02"}],"explanation":["나라가 관혼상제를 중히 여겼어요.","백성에게도 따르게 했어요.","집안 행사도 유교였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#9','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C6',2,'ox','auto','조선 전기에는 고려처럼 아들과 딸이 재산을 똑같이 물려받았어요.',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"ox","stem":"조선 전기에는 고려처럼 아들과 딸이 재산을 똑같이 물려받았어요.","answer":"O","reason_options":[{"t":"여성의 지위는 후기로 갈수록 낮아졌고 전기에는 고려의 풍습이 남아 있었기 때문에","correct":true},{"t":"조선은 처음부터 딸에게 재산을 주지 않았기 때문에","mis":"SO5-2-u2-X11"}],"mis":"SO5-2-u2-X11","explanation":["전기엔 고려처럼 했어요.","후기에 달라졌어요.","변화를 함께 봐요."],"asset":{"type":"passage","lines":["조선 전기 — 아들과 딸이 재산을 똑같이 나누어 받았다.","조선 전기 — 아들딸이 돌아가며 제사를 지냈다.","조선 후기 — 맏아들이 재산과 제사를 주로 맡았다.","조선 후기 — 여성은 아버지·남편·아들의 뜻을 따르게 되었다."],"title":"조선 여성의 생활 변화 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_basic#10','soc',5,2,'u2','L02','g5_2_soc_u2_L02_basic','lesson_basic','SO5-2-u2-C4',3,'error','auto','조선이 펴낸 책을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X06','SO5-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C4","difficulty":3,"kind":"error","stem":"조선이 펴낸 책을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「『경국대전』에는 효자 이야기가 그림으로 실려 있어.」","correct":true,"mis_target":"SO5-2-u2-X06"},{"t":"예나 — 「『삼강행실도』는 그림으로 가르침을 알렸어.」","mis":"SO5-2-u2-X07"},{"t":"준혁 — 「『경국대전』은 나라를 다스리는 법전이야.」","mis":"SO5-2-u2-X06"}],"explanation":["효자 이야기는 『삼강행실도』예요.","『경국대전』은 법전이에요.","시우가 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#1','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',2,'match','auto','조선 사람 네 명의 하는 일과 신분을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"match","stem":"조선 사람 네 명의 하는 일과 신분을 알맞게 이으세요.","pairs":[{"l":"㉠ 과거를 보고 관리","r":"양반"},{"l":"㉡ 통역·의술","r":"중인"},{"l":"㉢ 농사·장사·세금","r":"상민"},{"l":"㉣ 주인집·관청 일","r":"천민"}],"mis":"SO5-2-u2-X10","explanation":["관리는 양반이에요.","전문 일은 중인이에요.","농사는 상민, 노비는 천민이에요."],"asset":{"type":"passage","lines":["㉠ 공부해서 과거를 보고 관리가 되었다.","㉡ 통역이나 의술 같은 전문적인 일을 맡았다.","㉢ 농사를 짓고 장사를 하며 세금을 냈다.","㉣ 주인집이나 관청의 일을 했다."],"title":"조선 사람 네 명의 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#2','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C4',2,'mc','auto','조선이 펴낸 책 세 권 가운데 유교 질서를 법으로 세운 책은 어느 것인가요?',ARRAY['SO5-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C4","difficulty":2,"kind":"mc","stem":"조선이 펴낸 책 세 권 가운데 유교 질서를 법으로 세운 책은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"SO5-2-u2-X06"},{"t":"다","mis":"SO5-2-u2-X06"},{"t":"가와 다","mis":"SO5-2-u2-X06"}],"explanation":["가는 이야기책이에요.","다는 농사책이에요.","나가 법전이에요."],"asset":{"type":"passage","lines":["가 — 효자·충신·열녀 이야기를 그림과 함께 실은 책","나 — 나라를 다스리는 기본 법을 모은 책","다 — 우리 땅에 맞는 농사법을 모은 책"],"title":"조선이 펴낸 책 세 권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#3','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',3,'mc','auto','조선 여성의 생활 변화 메모를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C6","difficulty":3,"kind":"mc","stem":"조선 여성의 생활 변화 메모를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 후기로 갈수록 유교 질서가 깊어지며 여성의 지위가 낮아졌다","correct":true},{"t":"조선 여성의 지위는 처음부터 끝까지 같았다","mis":"SO5-2-u2-X11"},{"t":"조선 후기 여성이 집안의 모든 재산을 가졌다","mis":"SO5-2-u2-X11"},{"t":"조선 전기 여성은 재산을 받지 못했다","mis":"SO5-2-u2-X11"}],"explanation":["전기는 똑같이 받았어요.","후기는 맏아들이 맡았어요.","지위가 낮아졌어요."],"asset":{"type":"passage","lines":["조선 전기 — 아들과 딸이 재산을 똑같이 나누어 받았다.","조선 전기 — 아들딸이 돌아가며 제사를 지냈다.","조선 후기 — 맏아들이 재산과 제사를 주로 맡았다.","조선 후기 — 여성은 아버지·남편·아들의 뜻을 따르게 되었다."],"title":"조선 여성의 생활 변화 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#4','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C4',3,'mc','auto','『경국대전』에 「땅과 집을 사고팔면 관청에 알려야 한다」는 내용을 둔 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X06','SO5-2-u2-X07']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C4","difficulty":3,"kind":"mc","stem":"『경국대전』에 「땅과 집을 사고팔면 관청에 알려야 한다」는 내용을 둔 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누구 것인지 분명히 해 다툼을 줄이고 세금을 제대로 걷으려고","correct":true},{"t":"땅을 사고팔지 못하게 하려고","mis":"SO5-2-u2-X06"},{"t":"관청이 땅을 모두 빼앗으려고","mis":"SO5-2-u2-X06"},{"t":"효자를 찾으려고","mis":"SO5-2-u2-X07"}],"explanation":["주인이 분명해져요.","다툼이 줄어요.","세금도 제대로 걷어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#5','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',3,'ox','auto','조선 사람들은 유교 질서에 따라 저마다 신분에 맞게 살아야 했어요.',ARRAY['SO5-2-u2-X09']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C6","difficulty":3,"kind":"ox","stem":"조선 사람들은 유교 질서에 따라 저마다 신분에 맞게 살아야 했어요.","answer":"O","reason_options":[{"t":"유교는 저마다 자기 역할과 자리를 지키는 질서를 중히 여겼기 때문에","correct":true},{"t":"조선에서는 누구나 하고 싶은 일을 마음대로 했기 때문에","mis":"SO5-2-u2-X09"}],"mis":"SO5-2-u2-X09","explanation":["유교는 역할을 강조해요.","신분이 정해져 있었어요.","신분에 맞게 살았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#6','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',3,'error','auto','조선의 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C6","difficulty":3,"kind":"error","stem":"조선의 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「상민은 세금을 내지 않고 관리가 되어 나라 일을 했어.」","correct":true,"mis_target":"SO5-2-u2-X10"},{"t":"은호 — 「양반은 공부해서 과거를 보았어.」","mis":"SO5-2-u2-X10"},{"t":"태민 — 「천민은 주인집이나 관청 일을 했어.」","mis":"SO5-2-u2-X10"}],"explanation":["상민은 세금을 냈어요.","관리는 주로 양반이에요.","라희의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 공부해서 과거를 보고 관리가 되었다.","㉡ 통역이나 의술 같은 전문적인 일을 맡았다.","㉢ 농사를 짓고 장사를 하며 세금을 냈다.","㉣ 주인집이나 관청의 일을 했다."],"title":"조선 사람 네 명의 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#7','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C5',3,'mc','auto','오늘날 결혼식이나 제사를 지내는 모습에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X40','SO5-2-u2-X39','SO5-2-u2-X08']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C5","difficulty":3,"kind":"mc","stem":"오늘날 결혼식이나 제사를 지내는 모습에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 때 중히 여긴 유교 예절이 오늘날 생활에도 이어져 있다","correct":true},{"t":"유교 예절은 조선이 끝나며 모두 사라졌다","mis":"SO5-2-u2-X40"},{"t":"결혼식과 제사는 개항 이후 처음 생겼다","mis":"SO5-2-u2-X39"},{"t":"관혼상제는 불교 행사다","mis":"SO5-2-u2-X08"}],"explanation":["혼례와 제례예요.","관혼상제의 일부예요.","오늘도 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#8','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C4',4,'mc','auto','조선이 『삼강행실도』를 펴내고 『경국대전』을 만든 것을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u2-X07','SO5-2-u2-X06','SO5-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C4","difficulty":4,"kind":"mc","stem":"조선이 『삼강행실도』를 펴내고 『경국대전』을 만든 것을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"가르침으로 백성의 마음을, 법으로 나라의 질서를 유교에 맞게 세우려 했다","correct":true},{"t":"조선은 백성에게 관심이 없었다","mis":"SO5-2-u2-X07"},{"t":"두 책 모두 농사를 돕는 책이다","mis":"SO5-2-u2-X06"},{"t":"조선은 불교 질서를 세우려 했다","mis":"SO5-2-u2-X02"}],"explanation":["『삼강행실도』는 가르침이에요.","『경국대전』은 법이에요.","둘 다 유교 질서를 세웠어요."],"asset":{"type":"passage","lines":["가 — 효자·충신·열녀 이야기를 그림과 함께 실은 책","나 — 나라를 다스리는 기본 법을 모은 책","다 — 우리 땅에 맞는 농사법을 모은 책"],"title":"조선이 펴낸 책 세 권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#9','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',4,'mc','auto','조선 시대 인물이 되어 가상 일기를 쓸 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X10','SO5-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C6","difficulty":4,"kind":"mc","stem":"조선 시대 인물이 되어 가상 일기를 쓸 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상민 — 「오늘도 논에서 일하고, 거둔 곡식 일부를 세금으로 냈다.」","correct":true},{"t":"천민 — 「과거에 붙어 관리가 되었다.」","mis":"SO5-2-u2-X10"},{"t":"양반 — 「주인 어른 댁 마당을 쓸었다.」","mis":"SO5-2-u2-X10"},{"t":"중인 — 「전차를 타고 통역하러 갔다.」","mis":"SO5-2-u2-X39"}],"explanation":["신분에 맞는 일을 써요.","상민은 농사와 세금이에요.","시대에 맞는 물건만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L02_challenge#10','soc',5,2,'u2','L02','g5_2_soc_u2_L02_challenge','lesson_challenge','SO5-2-u2-C6',4,'essay','teacher','조선 사람 네 명의 하는 일을 보고 조선의 신분이 어떻게 나뉘었는지 쓰고, 신분에 맞게 살아야 했던 까닭을 유교와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C6","difficulty":4,"kind":"essay","stem":"조선 사람 네 명의 하는 일을 보고 조선의 신분이 어떻게 나뉘었는지 쓰고, 신분에 맞게 살아야 했던 까닭을 유교와 이어 쓰세요.","answer_guide":{"answer":"예: 조선은 법으로는 양인과 천인으로 나뉘었지만 실제로는 공부해서 관리가 된 양반, 통역·의술 같은 전문적인 일을 한 중인, 농사·장사를 하며 세금을 낸 상민, 주인집이나 관청 일을 한 천민으로 나뉘었다. 유교는 저마다 자기 역할에 맞게 사는 질서를 중히 여겼기 때문에 사람들은 신분에 맞게 살아야 했다.","scoring_points":["네 신분과 하는 일을 썼는가","법과 실제의 구분을 썼는가","유교의 질서와 이었는가"]},"explanation":["양반·중인·상민·천민이에요.","법은 양인·천인이에요.","유교는 역할을 중히 여겨요."],"asset":{"type":"passage","lines":["㉠ 공부해서 과거를 보고 관리가 되었다.","㉡ 통역이나 의술 같은 전문적인 일을 맡았다.","㉢ 농사를 짓고 장사를 하며 세금을 냈다.","㉣ 주인집이나 관청의 일을 했다."],"title":"조선 사람 네 명의 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#1','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',1,'mc','auto','세종이 우리 땅에 맞는 농사법을 모아 펴낸 책은 어느 것인가요?',ARRAY['SO5-2-u2-X06']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"mc","stem":"세종이 우리 땅에 맞는 농사법을 모아 펴낸 책은 어느 것인가요?","options":[{"t":"『농사직설』","correct":true},{"t":"『삼강행실도』","mis":"SO5-2-u2-X06"},{"t":"『경국대전』","mis":"SO5-2-u2-X06"},{"t":"『직지』","mis":"SO5-2-u2-X06"}],"explanation":["농부들의 경험을 모았어요.","우리 땅에 맞아요.","『농사직설』이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#2','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C8',1,'sa','auto','세종이 백성이 쉽게 읽고 쓸 수 있게 만든 글자는 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C8","difficulty":1,"kind":"sa","stem":"세종이 백성이 쉽게 읽고 쓸 수 있게 만든 글자는 무엇인가요? 네 글자로 쓰세요.","answer":["훈민정음"],"explanation":["백성을 가르치는 바른 소리예요.","오늘의 한글이에요.","훈민정음이에요."],"mis":"SO5-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#3','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',1,'mc','auto','비가 온 양을 재는 기구는 어느 것인가요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"mc","stem":"비가 온 양을 재는 기구는 어느 것인가요?","options":[{"t":"측우기","correct":true},{"t":"앙부일구","mis":"SO5-2-u2-X13"},{"t":"자격루","mis":"SO5-2-u2-X13"},{"t":"혼천의","mis":"SO5-2-u2-X13"}],"explanation":["비를 받아요.","양을 재요.","측우기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#4','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',1,'ox','auto','앙부일구는 그림자로 시각을 알려 주는 해시계예요.',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"ox","stem":"앙부일구는 그림자로 시각을 알려 주는 해시계예요.","answer":"O","reason_options":[{"t":"바늘의 그림자가 가리키는 곳으로 시각과 계절을 알았기 때문에","correct":true},{"t":"앙부일구는 비의 양을 재는 그릇이기 때문에","mis":"SO5-2-u2-X13"}],"mis":"SO5-2-u2-X13","explanation":["솥 모양이에요.","바늘 그림자를 봐요.","해시계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#5','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',2,'mc','auto','세종 때 만든 과학 기구 카드 ㉰는 무엇인가요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C7","difficulty":2,"kind":"mc","stem":"세종 때 만든 과학 기구 카드 ㉰는 무엇인가요?","options":[{"t":"자격루","correct":true},{"t":"측우기","mis":"SO5-2-u2-X13"},{"t":"앙부일구","mis":"SO5-2-u2-X13"},{"t":"혼천의","mis":"SO5-2-u2-X13"}],"explanation":["물로 움직여요.","저절로 종을 쳐요.","자격루예요."],"asset":{"type":"passage","lines":["㉮ 비가 온 양을 재는 그릇","㉯ 그림자로 시각과 계절을 알려 주는 솥 모양 해시계","㉰ 물로 움직여 저절로 종을 치는 시계","㉱ 하늘의 움직임을 살피는 기구"],"title":"세종 때 만든 과학 기구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#6','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',2,'mc','auto','세종이 『농사직설』을 펴낸 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X12']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C7","difficulty":2,"kind":"mc","stem":"세종이 『농사직설』을 펴낸 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"중국 농사책이 조선의 환경과 맞지 않아서","correct":true},{"t":"양반이 취미로 읽게 하려고","mis":"SO5-2-u2-X12"},{"t":"농사를 그만두게 하려고","mis":"SO5-2-u2-X12"},{"t":"중국 농사책을 그대로 옮기려고","mis":"SO5-2-u2-X12"}],"explanation":["땅과 기후가 달라요.","농부들의 경험을 모았어요.","우리에게 맞는 책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#7','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C8',2,'mc','auto','훈민정음 탐구 메모 ①·②로 보아 새 글자가 필요했던 까닭은 어느 것인가요?',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C8","difficulty":2,"kind":"mc","stem":"훈민정음 탐구 메모 ①·②로 보아 새 글자가 필요했던 까닭은 어느 것인가요?","options":[{"t":"한자는 글자 수가 많고 우리말과 달라 백성이 배우기 어려웠다","correct":true},{"t":"한자가 너무 쉬워서","mis":"SO5-2-u2-X15"},{"t":"양반만 글을 쓰게 하려고","mis":"SO5-2-u2-X15"},{"t":"서양 글자를 따라 하려고","mis":"SO5-2-u2-X15"}],"explanation":["한자는 많아요.","우리말과 달라요.","백성이 배우기 어려웠어요."],"asset":{"type":"passage","lines":["① 한자는 글자 수가 아주 많았다.","② 한자는 우리말과 달라 소리 나는 대로 적기 어려웠다.","③ 새 글자가 생기자 백성도 편지를 쓰고 책을 읽게 되었다.","④ 유교의 가르침을 담은 책도 새 글자로 풀어 펴냈다."],"title":"훈민정음 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#8','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C14',2,'mc','auto','앙부일구에 그림을 새기고 한양 거리에 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X14','SO5-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C14","difficulty":2,"kind":"mc","stem":"앙부일구에 그림을 새기고 한양 거리에 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 모르는 백성도 누구나 시각을 알게 하려고","correct":true},{"t":"임금만 보게 하려고","mis":"SO5-2-u2-X14"},{"t":"비를 모으려고","mis":"SO5-2-u2-X13"},{"t":"외국 사람에게 팔려고","mis":"SO5-2-u2-X14"}],"explanation":["거리에 두었어요.","그림을 새겼어요.","백성 누구나 봤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#9','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C8',2,'ox','auto','세종이 만든 훈민정음은 오늘날 우리가 쓰는 한글이 되었어요.',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C8","difficulty":2,"kind":"ox","stem":"세종이 만든 훈민정음은 오늘날 우리가 쓰는 한글이 되었어요.","answer":"O","reason_options":[{"t":"훈민정음이 이어져 오늘날 한글로 쓰이기 때문에","correct":true},{"t":"훈민정음은 조선 때 사라졌기 때문에","mis":"SO5-2-u2-X15"}],"mis":"SO5-2-u2-X15","explanation":["세종이 만들었어요.","이어져 왔어요.","오늘의 한글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_basic#10','soc',5,2,'u2','L03','g5_2_soc_u2_L03_basic','lesson_basic','SO5-2-u2-C7',3,'error','auto','세종 때 과학 기구를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"error","stem":"세종 때 과학 기구를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「측우기로 시각을 알고, 앙부일구로 비의 양을 쟀어.」","correct":true,"mis_target":"SO5-2-u2-X13"},{"t":"도겸 — 「자격루는 날씨와 상관없이 시각을 알렸어.」","mis":"SO5-2-u2-X13"},{"t":"나연 — 「측우기는 농사에 도움이 되었어.」","mis":"SO5-2-u2-X13"}],"explanation":["비는 측우기예요.","시각은 앙부일구예요.","하윤이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#1','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C7',2,'match','auto','세종 때 만든 과학 기구 카드와 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C7","difficulty":2,"kind":"match","stem":"세종 때 만든 과학 기구 카드와 이름을 알맞게 이으세요.","pairs":[{"l":"㉮ 비의 양","r":"측우기"},{"l":"㉯ 그림자 해시계","r":"앙부일구"},{"l":"㉰ 저절로 치는 종","r":"자격루"},{"l":"㉱ 하늘의 움직임","r":"혼천의"}],"mis":"SO5-2-u2-X13","explanation":["비는 측우기예요.","그림자는 앙부일구예요.","종은 자격루, 하늘은 혼천의예요."],"asset":{"type":"passage","lines":["㉮ 비가 온 양을 재는 그릇","㉯ 그림자로 시각과 계절을 알려 주는 솥 모양 해시계","㉰ 물로 움직여 저절로 종을 치는 시계","㉱ 하늘의 움직임을 살피는 기구"],"title":"세종 때 만든 과학 기구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#2','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C7',2,'mc','auto','측우기로 잰 비의 양을 어디에 썼을까요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C7","difficulty":2,"kind":"mc","stem":"측우기로 잰 비의 양을 어디에 썼을까요?","options":[{"t":"농사를 짐작하고 세금을 알맞게 걷는 데","correct":true},{"t":"시각을 알리는 데","mis":"SO5-2-u2-X13"},{"t":"전쟁을 하는 데","mis":"SO5-2-u2-X13"},{"t":"책을 찍는 데","mis":"SO5-2-u2-X13"}],"explanation":["비는 농사와 이어져요.","농사가 세금과 이어져요.","알맞은 세금을 걷었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#3','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C8',3,'mc','auto','훈민정음 탐구 메모 ③·④로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C8","difficulty":3,"kind":"mc","stem":"훈민정음 탐구 메모 ③·④로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"새 글자로 백성의 생활이 편해지고 유교의 가르침도 널리 퍼졌다","correct":true},{"t":"새 글자는 양반만 썼다","mis":"SO5-2-u2-X15"},{"t":"새 글자로 유교 책은 만들 수 없었다","mis":"SO5-2-u2-X15"},{"t":"새 글자로 백성이 더 불편해졌다","mis":"SO5-2-u2-X15"}],"explanation":["백성도 편지를 썼어요.","유교 책도 펴냈어요.","생활과 문화가 달라졌어요."],"asset":{"type":"passage","lines":["① 한자는 글자 수가 아주 많았다.","② 한자는 우리말과 달라 소리 나는 대로 적기 어려웠다.","③ 새 글자가 생기자 백성도 편지를 쓰고 책을 읽게 되었다.","④ 유교의 가르침을 담은 책도 새 글자로 풀어 펴냈다."],"title":"훈민정음 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#4','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C14',3,'mc','auto','세종 시기의 발전을 백성의 생활과 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X14','SO5-2-u2-X39']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C14","difficulty":3,"kind":"mc","stem":"세종 시기의 발전을 백성의 생활과 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"농사책·과학 기구·새 글자로 백성이 농사짓고 시각을 알고 글을 쓰기 쉬워졌다","correct":true},{"t":"세종 시기의 발명은 임금과 양반만 썼다","mis":"SO5-2-u2-X14"},{"t":"세종 시기에는 백성의 생활이 달라지지 않았다","mis":"SO5-2-u2-X14"},{"t":"세종 시기에 서양 문물을 받아들였다","mis":"SO5-2-u2-X39"}],"explanation":["농사가 쉬워졌어요.","시각을 알게 됐어요.","글을 쓰기 쉬워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#5','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C7',3,'ox','auto','조선의 임금들은 백성이 농사를 잘 지어야 생활이 안정되고 나라가 발전한다고 여겼어요.',ARRAY['SO5-2-u2-X12']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"ox","stem":"조선의 임금들은 백성이 농사를 잘 지어야 생활이 안정되고 나라가 발전한다고 여겼어요.","answer":"O","reason_options":[{"t":"농사가 백성의 생활과 나라 살림의 바탕이었기 때문에","correct":true},{"t":"조선 임금은 농사에 관심이 없었기 때문에","mis":"SO5-2-u2-X12"}],"mis":"SO5-2-u2-X12","explanation":["대부분 농사를 지었어요.","농사가 생활의 바탕이에요.","그래서 농사를 도왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#6','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C8',3,'error','auto','훈민정음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C8","difficulty":3,"kind":"error","stem":"훈민정음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은채 — 「훈민정음은 양반만 쓰게 하려고 일부러 어렵게 만들었어.」","correct":true,"mis_target":"SO5-2-u2-X15"},{"t":"주안 — 「한자를 모르는 백성을 중심으로 퍼졌어.」","mis":"SO5-2-u2-X15"},{"t":"시아 — 「만들 때 반대하는 사람도 있었어.」","mis":"SO5-2-u2-X15"}],"explanation":["백성을 위해 쉽게 만들었어요.","양반만을 위한 게 아니에요.","은채의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#7','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C7',3,'mc','auto','자격루가 해시계인 앙부일구와 견주어 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"mc","stem":"자격루가 해시계인 앙부일구와 견주어 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"해가 없는 흐린 날이나 밤에도 시각을 알릴 수 있다","correct":true},{"t":"비의 양을 잴 수 있다","mis":"SO5-2-u2-X13"},{"t":"그림자로만 시각을 알 수 있다","mis":"SO5-2-u2-X13"},{"t":"하늘의 별을 볼 수 있다","mis":"SO5-2-u2-X13"}],"explanation":["해시계는 해가 있어야 해요.","자격루는 물로 움직여요.","날씨와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#8','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C8',4,'mc','auto','휴대 전화 메시지, 거리 간판, 교과서에 모두 한글이 쓰이는 오늘날의 모습으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X15']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C8","difficulty":4,"kind":"mc","stem":"휴대 전화 메시지, 거리 간판, 교과서에 모두 한글이 쓰이는 오늘날의 모습으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"세종이 백성을 위해 만든 글자가 오늘 우리 생활의 바탕이 되었다","correct":true},{"t":"한글은 개항 이후 서양에서 들어왔다","mis":"SO5-2-u2-X39"},{"t":"훈민정음은 오늘날과 관계없다","mis":"SO5-2-u2-X15"},{"t":"한글은 양반만 쓰는 글자다","mis":"SO5-2-u2-X15"}],"explanation":["어디서나 한글을 써요.","세종이 만들었어요.","오늘의 바탕이 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#9','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C14',4,'mc','auto','세종 시기에 만든 것들을 함께 볼 때 그 바탕에 있던 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X14','SO5-2-u2-X39','SO5-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C14","difficulty":4,"kind":"mc","stem":"세종 시기에 만든 것들을 함께 볼 때 그 바탕에 있던 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"백성의 생활을 안정시키는 것이 나라를 다스리는 중요한 일이라는 생각","correct":true},{"t":"임금의 힘을 자랑하려는 생각만","mis":"SO5-2-u2-X14"},{"t":"서양 기술을 따라 하려는 생각","mis":"SO5-2-u2-X39"},{"t":"백성은 글을 몰라도 된다는 생각","mis":"SO5-2-u2-X15"}],"explanation":["농사를 도왔어요.","시각과 글을 주었어요.","백성의 생활을 먼저 생각했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L03_challenge#10','soc',5,2,'u2','L03','g5_2_soc_u2_L03_challenge','lesson_challenge','SO5-2-u2-C7',4,'essay','teacher','세종 때 만든 것 가운데 농업·과학·문화에서 하나씩 고르고, 각각 백성의 생활에 어떤 도움을 주었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C7","difficulty":4,"kind":"essay","stem":"세종 때 만든 것 가운데 농업·과학·문화에서 하나씩 고르고, 각각 백성의 생활에 어떤 도움을 주었는지 쓰세요.","answer_guide":{"answer":"예: 농업 — 『농사직설』은 우리 땅에 맞는 농사법을 알려 주어 농사를 더 잘 짓게 했다. 과학 — 앙부일구는 그림을 새겨 거리에 두어 글을 모르는 백성도 시각을 알 수 있게 했다. 문화 — 훈민정음은 백성이 쉽게 읽고 써서 편지를 쓰고 책을 읽게 했다.","scoring_points":["농업에서 하나를 골랐는가","과학에서 하나를 골랐는가","문화에서 하나를 골라 셋 모두 도움을 썼는가"]},"explanation":["농업은 농사책이에요.","과학은 기구예요.","문화는 훈민정음이에요."],"asset":{"type":"passage","lines":["㉮ 비가 온 양을 재는 그릇","㉯ 그림자로 시각과 계절을 알려 주는 솥 모양 해시계","㉰ 물로 움직여 저절로 종을 치는 시계","㉱ 하늘의 움직임을 살피는 기구"],"title":"세종 때 만든 과학 기구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#1','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C10',1,'mc','auto','일본이 많은 군사로 조선에 쳐들어온 전쟁은 어느 것인가요?',ARRAY['SO5-2-u2-X19']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C10","difficulty":1,"kind":"mc","stem":"일본이 많은 군사로 조선에 쳐들어온 전쟁은 어느 것인가요?","options":[{"t":"임진왜란","correct":true},{"t":"병자호란","mis":"SO5-2-u2-X19"},{"t":"귀주 대첩","mis":"SO5-2-u2-X19"},{"t":"강화도 조약","mis":"SO5-2-u2-X19"}],"explanation":["일본이 쳐들어왔어요.","수군과 의병이 싸웠어요.","임진왜란이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#2','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C11',1,'mc','auto','병자호란 때 인조가 피한 곳은 어디인가요?',ARRAY['SO5-2-u2-X20','SO5-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C11","difficulty":1,"kind":"mc","stem":"병자호란 때 인조가 피한 곳은 어디인가요?","options":[{"t":"남한산성","correct":true},{"t":"강화도","mis":"SO5-2-u2-X20"},{"t":"경복궁","mis":"SO5-2-u2-X20"},{"t":"쓰시마섬","mis":"SO5-2-u2-X17"}],"explanation":["경기도 광주에 있어요.","청군에게 둘러싸였어요.","남한산성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#3','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C10',1,'sa','auto','나라를 지키려고 백성이 스스로 만든 군대를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u2-C10","difficulty":1,"kind":"sa","stem":"나라를 지키려고 백성이 스스로 만든 군대를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["의병"],"explanation":["백성이 스스로 나섰어요.","나라 군대가 아니에요.","의병이에요."],"mis":"SO5-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#4','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C9',1,'ox','auto','조선은 명과 대체로 좋은 관계를 이어 가며 사신을 보냈어요.',ARRAY['SO5-2-u2-X16']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C9","difficulty":1,"kind":"ox","stem":"조선은 명과 대체로 좋은 관계를 이어 가며 사신을 보냈어요.","answer":"O","reason_options":[{"t":"명으로부터 필요한 문물을 받아들여 나라를 발전시키려 했기 때문에","correct":true},{"t":"조선은 명과 늘 전쟁만 했기 때문에","mis":"SO5-2-u2-X16"}],"mis":"SO5-2-u2-X16","explanation":["사신을 보냈어요.","문물을 받아들였어요.","좋은 관계였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#5','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C9',2,'mc','auto','조선 전기 주변 나라와의 일 카드 ㉯의 「섬」은 어디인가요?',ARRAY['SO5-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"mc","stem":"조선 전기 주변 나라와의 일 카드 ㉯의 「섬」은 어디인가요?","options":[{"t":"쓰시마섬","correct":true},{"t":"강화도","mis":"SO5-2-u2-X17"},{"t":"제주도","mis":"SO5-2-u2-X17"},{"t":"남한산성","mis":"SO5-2-u2-X17"}],"explanation":["해적의 소굴이었어요.","왜구가 머물렀어요.","쓰시마섬이에요."],"asset":{"type":"passage","lines":["㉮ 사신을 보내 책과 물건 같은 필요한 문물을 받아들였다.","㉯ 무역을 하다가 해적이 노략질하자 그 소굴인 섬을 공격했다.","㉰ 무역을 하다가 국경을 넘어오자 몰아내고 압록강·두만강 쪽에 군과 진을 두었다."],"title":"조선 전기 주변 나라와의 일 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#6','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C9',2,'mc','auto','조선 전기 주변 나라와의 일 카드 ㉰의 상대 나라는 어디인가요?',ARRAY['SO5-2-u2-X16','SO5-2-u2-X17']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"mc","stem":"조선 전기 주변 나라와의 일 카드 ㉰의 상대 나라는 어디인가요?","options":[{"t":"여진","correct":true},{"t":"명","mis":"SO5-2-u2-X16"},{"t":"일본","mis":"SO5-2-u2-X17"},{"t":"송","mis":"SO5-2-u2-X16"}],"explanation":["북쪽에서 국경을 넘어왔어요.","4군과 6진을 두었어요.","여진이에요."],"asset":{"type":"passage","lines":["㉮ 사신을 보내 책과 물건 같은 필요한 문물을 받아들였다.","㉯ 무역을 하다가 해적이 노략질하자 그 소굴인 섬을 공격했다.","㉰ 무역을 하다가 국경을 넘어오자 몰아내고 압록강·두만강 쪽에 군과 진을 두었다."],"title":"조선 전기 주변 나라와의 일 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#7','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C10',2,'mc','auto','어느 전쟁 기록 메모가 설명하는 전쟁은 어느 것인가요?',ARRAY['SO5-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C10","difficulty":2,"kind":"mc","stem":"어느 전쟁 기록 메모가 설명하는 전쟁은 어느 것인가요?","options":[{"t":"임진왜란","correct":true},{"t":"병자호란","mis":"SO5-2-u2-X19"},{"t":"몽골의 침입","mis":"SO5-2-u2-X19"},{"t":"거란의 침입","mis":"SO5-2-u2-X19"}],"explanation":["조총을 앞세웠어요.","수군·의병·명군이 싸웠어요.","임진왜란이에요."],"asset":{"type":"passage","lines":["① 조총을 앞세운 적군에게 잇달아 졌다.","② 바다에서는 수군이 거북선 등으로 적의 배를 물리쳤다.","③ 양반·농민·승려가 스스로 군대를 만들어 싸웠다.","④ 명에서 보낸 군대가 함께 싸웠다."],"title":"어느 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#8','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C11',2,'mc','auto','병자호란이 일어난 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X20','SO5-2-u2-X19','SO5-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C11","difficulty":2,"kind":"mc","stem":"병자호란이 일어난 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"청이 임금과 신하의 관계를 맺자고 했는데 조선이 거절해서","correct":true},{"t":"조선이 먼저 청에 쳐들어가서","mis":"SO5-2-u2-X20"},{"t":"일본이 조총을 앞세워 와서","mis":"SO5-2-u2-X19"},{"t":"서양 배가 통상을 요구해서","mis":"SO5-2-u2-X39"}],"explanation":["여진이 청이 되었어요.","관계를 요구했어요.","거절하자 쳐들어왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#9','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C11',2,'ox','auto','병자호란에서 조선은 청을 크게 물리치고 이겼어요.',ARRAY['SO5-2-u2-X20']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C11","difficulty":2,"kind":"ox","stem":"병자호란에서 조선은 청을 크게 물리치고 이겼어요.","answer":"X","reason_options":[{"t":"남한산성에서 추위와 배고픔 끝에 청에 항복했기 때문에","correct":true},{"t":"인조가 청을 쫓아 북쪽까지 갔기 때문에","mis":"SO5-2-u2-X20"}],"mis":"SO5-2-u2-X20","explanation":["남한산성이 둘러싸였어요.","버티기 어려웠어요.","청에 항복했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_basic#10','soc',5,2,'u2','L04','g5_2_soc_u2_L04_basic','lesson_basic','SO5-2-u2-C10',3,'error','auto','두 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X19','SO5-2-u2-X18','SO5-2-u2-X20']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C10","difficulty":3,"kind":"error","stem":"두 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤재 — 「청이 쳐들어와 인조가 남한산성으로 피한 전쟁은 임진왜란이야.」","correct":true,"mis_target":"SO5-2-u2-X19"},{"t":"수아 — 「임진왜란 때 이순신이 이끄는 수군이 활약했어.」","mis":"SO5-2-u2-X18"},{"t":"건우 — 「병자호란 뒤 많은 백성이 청에 끌려갔어.」","mis":"SO5-2-u2-X20"}],"explanation":["청이 쳐들어온 건 병자호란이에요.","임진왜란은 일본이에요.","윤재가 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#1','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C9',2,'match','auto','조선 전기 주변 나라와의 일 카드와 나라를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"match","stem":"조선 전기 주변 나라와의 일 카드와 나라를 알맞게 이으세요.","pairs":[{"l":"㉮ 사신·문물","r":"명"},{"l":"㉯ 해적의 소굴 공격","r":"일본(왜구)"},{"l":"㉰ 4군과 6진","r":"여진"}],"mis":"SO5-2-u2-X16","explanation":["문물은 명이에요.","왜구는 일본 쪽 해적이에요.","4군 6진은 여진이에요."],"asset":{"type":"passage","lines":["㉮ 사신을 보내 책과 물건 같은 필요한 문물을 받아들였다.","㉯ 무역을 하다가 해적이 노략질하자 그 소굴인 섬을 공격했다.","㉰ 무역을 하다가 국경을 넘어오자 몰아내고 압록강·두만강 쪽에 군과 진을 두었다."],"title":"조선 전기 주변 나라와의 일 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#2','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C10',2,'mc','auto','어느 전쟁 기록 메모 ③의 사람들이 스스로 싸운 마음과 이어지는 유교 정신은 어느 것인가요?',ARRAY['SO5-2-u2-X18','SO5-2-u2-X02']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C10","difficulty":2,"kind":"mc","stem":"어느 전쟁 기록 메모 ③의 사람들이 스스로 싸운 마음과 이어지는 유교 정신은 어느 것인가요?","options":[{"t":"나라와 임금에 대한 충성","correct":true},{"t":"신분에 맞게 장사하는 마음","mis":"SO5-2-u2-X18"},{"t":"불교를 믿는 마음","mis":"SO5-2-u2-X02"},{"t":"외국 문물을 좋아하는 마음","mis":"SO5-2-u2-X18"}],"explanation":["스스로 군대를 만들었어요.","나라를 지키려 했어요.","충성의 정신이에요."],"asset":{"type":"passage","lines":["① 조총을 앞세운 적군에게 잇달아 졌다.","② 바다에서는 수군이 거북선 등으로 적의 배를 물리쳤다.","③ 양반·농민·승려가 스스로 군대를 만들어 싸웠다.","④ 명에서 보낸 군대가 함께 싸웠다."],"title":"어느 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#3','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C10',3,'mc','auto','어느 전쟁 기록 메모 ①~④를 함께 볼 때 조선이 위기를 이겨 낸 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C10","difficulty":3,"kind":"mc","stem":"어느 전쟁 기록 메모 ①~④를 함께 볼 때 조선이 위기를 이겨 낸 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수군, 백성이 만든 의병, 명군의 도움이 함께 힘이 되었다","correct":true},{"t":"처음부터 조총으로 적을 물리쳤다","mis":"SO5-2-u2-X18"},{"t":"명군 혼자 모든 싸움을 이겼다","mis":"SO5-2-u2-X18"},{"t":"적이 스스로 물러갔다","mis":"SO5-2-u2-X18"}],"explanation":["②는 수군이에요.","③은 의병, ④는 명군이에요.","여러 힘이 모였어요."],"asset":{"type":"passage","lines":["① 조총을 앞세운 적군에게 잇달아 졌다.","② 바다에서는 수군이 거북선 등으로 적의 배를 물리쳤다.","③ 양반·농민·승려가 스스로 군대를 만들어 싸웠다.","④ 명에서 보낸 군대가 함께 싸웠다."],"title":"어느 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#4','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C11',3,'mc','auto','남한산성 안의 논쟁에서 신하 나의 주장을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X20','SO5-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C11","difficulty":3,"kind":"mc","stem":"남한산성 안의 논쟁에서 신하 나의 주장을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"백성이 더 죽기 전에 화해해 나라를 지키자","correct":true},{"t":"끝까지 싸우다 죽더라도 무릎 꿇지 말자","mis":"SO5-2-u2-X20"},{"t":"성을 버리고 일본으로 가자","mis":"SO5-2-u2-X19"},{"t":"청에 먼저 쳐들어가자","mis":"SO5-2-u2-X20"}],"explanation":["백성이 다 죽게 생겼대요.","화해를 말했어요.","나라를 지키자는 주장이에요."],"asset":{"type":"passage","lines":["신하 가 — 「싸우다 죽더라도 오랑캐에게 무릎 꿇을 수 없습니다.」","신하 나 — 「백성이 다 죽게 생겼습니다. 화해하고 나라를 지켜야 합니다.」","성 밖 — 청군이 둘러쌌고 추위와 배고픔이 이어졌다."],"title":"남한산성 안의 논쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#5','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C9',3,'ox','auto','조선은 일본·여진과 무역으로 교류하면서도 국경을 넘어와 빼앗으면 무력을 썼어요.',ARRAY['SO5-2-u2-X16']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C9","difficulty":3,"kind":"ox","stem":"조선은 일본·여진과 무역으로 교류하면서도 국경을 넘어와 빼앗으면 무력을 썼어요.","answer":"O","reason_options":[{"t":"교류와 함께 나라를 지키려는 대응도 했기 때문에","correct":true},{"t":"조선은 일본·여진과 전혀 교류하지 않았기 때문에","mis":"SO5-2-u2-X16"}],"mis":"SO5-2-u2-X16","explanation":["무역을 했어요.","빼앗으면 맞섰어요.","두 가지를 함께했어요."],"asset":{"type":"passage","lines":["㉮ 사신을 보내 책과 물건 같은 필요한 문물을 받아들였다.","㉯ 무역을 하다가 해적이 노략질하자 그 소굴인 섬을 공격했다.","㉰ 무역을 하다가 국경을 넘어오자 몰아내고 압록강·두만강 쪽에 군과 진을 두었다."],"title":"조선 전기 주변 나라와의 일 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#6','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C9',3,'error','auto','조선 전기 주변 나라와의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X16','SO5-2-u2-X17']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C9","difficulty":3,"kind":"error","stem":"조선 전기 주변 나라와의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「조선은 여진에게 사신을 보내 필요한 책과 문물을 받아들였어.」","correct":true,"mis_target":"SO5-2-u2-X16"},{"t":"나연 — 「명과는 대체로 좋은 관계를 이었어.」","mis":"SO5-2-u2-X16"},{"t":"은결 — 「여진을 몰아내고 4군과 6진을 두었어.」","mis":"SO5-2-u2-X17"}],"explanation":["문물은 명에서 받아들였어요.","여진과는 무역과 무력이에요.","지환의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#7','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C11',3,'mc','auto','병자호란 뒤 조선에 생긴 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C11","difficulty":3,"kind":"mc","stem":"병자호란 뒤 조선에 생긴 일로 알맞은 것은 어느 것인가요?","options":[{"t":"청과 임금과 신하의 관계를 맺고 많은 백성이 끌려갔다","correct":true},{"t":"조선이 청을 다스리게 되었다","mis":"SO5-2-u2-X20"},{"t":"명과 함께 청을 무너뜨렸다","mis":"SO5-2-u2-X20"},{"t":"전쟁이 없어 피해도 없었다","mis":"SO5-2-u2-X20"}],"explanation":["조선이 항복했어요.","관계를 맺었어요.","백성이 끌려갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#8','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C11',4,'mc','auto','남한산성 안의 논쟁에서 두 신하가 모두 바란 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C11","difficulty":4,"kind":"mc","stem":"남한산성 안의 논쟁에서 두 신하가 모두 바란 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방법은 달랐지만 둘 다 나라를 지키려 했다","correct":true},{"t":"둘 다 청의 신하가 되고 싶었다","mis":"SO5-2-u2-X20"},{"t":"둘 다 백성을 버리자고 했다","mis":"SO5-2-u2-X20"},{"t":"둘 다 아무 생각이 없었다","mis":"SO5-2-u2-X20"}],"explanation":["가는 싸우자고 했어요.","나는 화해하자고 했어요.","목표는 나라를 지키는 것이에요."],"asset":{"type":"passage","lines":["신하 가 — 「싸우다 죽더라도 오랑캐에게 무릎 꿇을 수 없습니다.」","신하 나 — 「백성이 다 죽게 생겼습니다. 화해하고 나라를 지켜야 합니다.」","성 밖 — 청군이 둘러쌌고 추위와 배고픔이 이어졌다."],"title":"남한산성 안의 논쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#9','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C10',4,'mc','auto','조선이 두 번의 큰 전쟁을 겪은 뒤의 상황으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X21','SO5-2-u2-X39','SO5-2-u2-X20']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C10","difficulty":4,"kind":"mc","stem":"조선이 두 번의 큰 전쟁을 겪은 뒤의 상황으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"땅이 거칠어지고 백성의 삶이 어려워져 먹고사는 일이 가장 급해졌다","correct":true},{"t":"전쟁으로 땅이 더 기름지게 되었다","mis":"SO5-2-u2-X21"},{"t":"곧바로 개항해 근대 문물을 받아들였다","mis":"SO5-2-u2-X39"},{"t":"백성의 생활은 하나도 달라지지 않았다","mis":"SO5-2-u2-X20"}],"explanation":["전쟁은 큰 피해를 남겨요.","땅이 거칠어졌어요.","먹고사는 일이 급했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L04_challenge#10','soc',5,2,'u2','L04','g5_2_soc_u2_L04_challenge','lesson_challenge','SO5-2-u2-C11',4,'essay','teacher','남한산성 안의 논쟁을 보고, 내가 그때의 신하라면 어느 쪽을 주장할지 정하고 그 까닭을 쓰세요. 그리고 실제로는 어떻게 되었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C11","difficulty":4,"kind":"essay","stem":"남한산성 안의 논쟁을 보고, 내가 그때의 신하라면 어느 쪽을 주장할지 정하고 그 까닭을 쓰세요. 그리고 실제로는 어떻게 되었는지 쓰세요.","answer_guide":{"answer":"예: 나는 신하 나처럼 화해하자고 주장하겠다. 추위와 배고픔이 이어지고 성이 둘러싸여 더 버티면 백성이 크게 다치기 때문이다. 실제로 인조는 청에 항복해 임금과 신하의 관계를 맺었고 많은 백성이 청에 끌려갔다.","scoring_points":["한쪽 주장을 골랐는가","그때 상황과 이어 까닭을 썼는가","실제 결과(항복·끌려감)를 썼는가"]},"explanation":["한쪽을 골라요.","그때 상황을 근거로 써요.","실제 결과도 써요."],"asset":{"type":"passage","lines":["신하 가 — 「싸우다 죽더라도 오랑캐에게 무릎 꿇을 수 없습니다.」","신하 나 — 「백성이 다 죽게 생겼습니다. 화해하고 나라를 지켜야 합니다.」","성 밖 — 청군이 둘러쌌고 추위와 배고픔이 이어졌다."],"title":"남한산성 안의 논쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#1','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',1,'mc','auto','어린 모를 키워 논에 옮겨 심는 농사법은 어느 것인가요?',ARRAY['SO5-2-u2-X06','SO5-2-u2-X13','SO5-2-u2-X08']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C12","difficulty":1,"kind":"mc","stem":"어린 모를 키워 논에 옮겨 심는 농사법은 어느 것인가요?","options":[{"t":"모내기법","correct":true},{"t":"『농사직설』","mis":"SO5-2-u2-X06"},{"t":"측우기","mis":"SO5-2-u2-X13"},{"t":"관혼상제","mis":"SO5-2-u2-X08"}],"explanation":["모를 키워요.","논에 옮겨 심어요.","모내기법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#2','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C13',1,'sa','auto','조선 후기에 만들어져 전국에서 쓰인 돈은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C13","difficulty":1,"kind":"sa","stem":"조선 후기에 만들어져 전국에서 쓰인 돈은 무엇인가요? 네 글자로 쓰세요.","answer":["상평통보"],"explanation":["쇠로 만든 돈이에요.","전국에서 썼어요.","상평통보예요."],"mis":"SO5-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#3','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C13',1,'mc','auto','여러 장시를 돌아다니며 장사한 상인을 무엇이라고 하나요?',ARRAY['SO5-2-u2-X30','SO5-2-u2-X32','SO5-2-u2-X10']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C13","difficulty":1,"kind":"mc","stem":"여러 장시를 돌아다니며 장사한 상인을 무엇이라고 하나요?","options":[{"t":"보부상","correct":true},{"t":"전기수","mis":"SO5-2-u2-X30"},{"t":"소리꾼","mis":"SO5-2-u2-X32"},{"t":"중인","mis":"SO5-2-u2-X10"}],"explanation":["짐을 지고 다녔어요.","이 장 저 장을 다녔어요.","보부상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#4','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',1,'ox','auto','고구마와 감자는 거친 땅에서도 잘 자라 굶주린 백성의 배고픔을 덜어 주었어요.',ARRAY['SO5-2-u2-X22']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C12","difficulty":1,"kind":"ox","stem":"고구마와 감자는 거친 땅에서도 잘 자라 굶주린 백성의 배고픔을 덜어 주었어요.","answer":"O","reason_options":[{"t":"기르기 쉽고 거친 땅에서도 잘 자랐기 때문에","correct":true},{"t":"고구마와 감자는 팔기만 하고 먹지 않았기 때문에","mis":"SO5-2-u2-X22"}],"mis":"SO5-2-u2-X22","explanation":["외국에서 들어왔어요.","거친 땅에서도 잘 자라요.","배고픔을 덜었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#5','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',2,'mc','auto','모내기법 관찰 메모 ㉰로 보아 모내기법의 좋은 점은 어느 것인가요?',ARRAY['SO5-2-u2-X21']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"mc","stem":"모내기법 관찰 메모 ㉰로 보아 모내기법의 좋은 점은 어느 것인가요?","options":[{"t":"잡초를 뽑기 쉬워 일손이 줄었다","correct":true},{"t":"일손이 더 많이 들었다","mis":"SO5-2-u2-X21"},{"t":"쌀이 덜 나왔다","mis":"SO5-2-u2-X21"},{"t":"논에 물이 필요 없었다","mis":"SO5-2-u2-X21"}],"explanation":["줄이 반듯해요.","잡초를 뽑기 쉬워요.","일손이 줄었어요."],"asset":{"type":"passage","lines":["㉮ 모판에 씨를 뿌려 어린 모를 키운다.","㉯ 자란 모를 논에 줄 맞춰 옮겨 심는다.","㉰ 줄이 반듯해 잡초를 뽑기 쉽다.","㉱ 벼를 거둔 논에 보리를 심어 한 번 더 거둔다."],"title":"모내기법 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#6','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',2,'mc','auto','모내기법 관찰 메모 ㉱처럼 한 땅에서 두 번 거두게 되면서 생긴 변화는 어느 것인가요?',ARRAY['SO5-2-u2-X21']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"mc","stem":"모내기법 관찰 메모 ㉱처럼 한 땅에서 두 번 거두게 되면서 생긴 변화는 어느 것인가요?","options":[{"t":"곡식을 더 많이 거두어 먹을 것이 늘었다","correct":true},{"t":"한 해에 한 번도 거두지 못했다","mis":"SO5-2-u2-X21"},{"t":"보리를 더는 기르지 않았다","mis":"SO5-2-u2-X21"},{"t":"곡식이 줄어 굶주렸다","mis":"SO5-2-u2-X21"}],"explanation":["벼를 거둬요.","그 땅에 보리를 심어요.","두 번 거둬요."],"asset":{"type":"passage","lines":["㉮ 모판에 씨를 뿌려 어린 모를 키운다.","㉯ 자란 모를 논에 줄 맞춰 옮겨 심는다.","㉰ 줄이 반듯해 잡초를 뽑기 쉽다.","㉱ 벼를 거둔 논에 보리를 심어 한 번 더 거둔다."],"title":"모내기법 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#7','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',2,'mc','auto','조선 후기에 많이 기른 작물 나를 기른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X22']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"mc","stem":"조선 후기에 많이 기른 작물 나를 기른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장에 내다 팔아 이익을 얻으려고","correct":true},{"t":"거친 땅에서 배고픔을 덜려고","mis":"SO5-2-u2-X22"},{"t":"나라에 바치는 제사 음식이라서","mis":"SO5-2-u2-X22"},{"t":"먹을 것이 넘쳐 버리려고","mis":"SO5-2-u2-X22"}],"explanation":["고추·인삼·담배예요.","시장에서 값을 잘 받아요.","팔아 이익을 얻었어요."],"asset":{"type":"passage","lines":["가 — 고구마·감자 : 거친 땅에서도 잘 자란다.","나 — 고추·인삼·담배 : 시장에 내다 팔면 값을 잘 받는다."],"title":"조선 후기에 많이 기른 작물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#8','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C13',2,'mc','auto','조선 후기 장터 이야기 ③처럼 쇠돈이 쓰인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C13","difficulty":2,"kind":"mc","stem":"조선 후기 장터 이야기 ③처럼 쇠돈이 쓰인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"쌀과 옷감은 무겁고 상하기 쉬워 작고 썩지 않는 돈이 편리했다","correct":true},{"t":"쌀이 너무 가벼워서","mis":"SO5-2-u2-X23"},{"t":"쇠돈이 상하기 쉬워서","mis":"SO5-2-u2-X23"},{"t":"장사가 줄어서","mis":"SO5-2-u2-X23"}],"explanation":["쌀은 썩을 수 있어요.","옷감은 상할 수 있어요.","쇠돈이 편했어요."],"asset":{"type":"passage","lines":["① 닷새마다 사람이 많이 모이는 곳에 장이 섰다.","② 등에 짐을 지거나 봇짐을 든 상인이 이 장 저 장을 다녔다.","③ 쌀이나 옷감 대신 작고 썩지 않는 쇠돈으로 값을 치렀다."],"title":"조선 후기 장터 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#9','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C13',2,'ox','auto','조선 후기에는 사람이 많이 모이는 곳마다 장시가 들어섰어요.',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C13","difficulty":2,"kind":"ox","stem":"조선 후기에는 사람이 많이 모이는 곳마다 장시가 들어섰어요.","answer":"O","reason_options":[{"t":"농작물 등을 사고파는 일이 많아졌기 때문에","correct":true},{"t":"조선 후기에는 장사를 법으로 금지했기 때문에","mis":"SO5-2-u2-X23"}],"mis":"SO5-2-u2-X23","explanation":["사고파는 일이 늘었어요.","장이 섰어요.","장시가 늘었어요."],"asset":{"type":"passage","lines":["① 닷새마다 사람이 많이 모이는 곳에 장이 섰다.","② 등에 짐을 지거나 봇짐을 든 상인이 이 장 저 장을 다녔다.","③ 쌀이나 옷감 대신 작고 썩지 않는 쇠돈으로 값을 치렀다."],"title":"조선 후기 장터 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_basic#10','soc',5,2,'u2','L05','g5_2_soc_u2_L05_basic','lesson_basic','SO5-2-u2-C12',3,'error','auto','조선 후기 농업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X22','SO5-2-u2-X21']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C12","difficulty":3,"kind":"error","stem":"조선 후기 농업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하빈 — 「고추와 담배는 거친 땅에서 자라 배고픔을 덜어 주었어.」","correct":true,"mis_target":"SO5-2-u2-X22"},{"t":"서진 — 「모내기법이 전국으로 퍼졌어.」","mis":"SO5-2-u2-X21"},{"t":"아준 — 「적은 일손으로 넓은 땅을 지어 잘사는 농민도 나타났어.」","mis":"SO5-2-u2-X21"}],"explanation":["배고픔을 던 건 고구마·감자예요.","고추·담배는 팔았어요.","하빈이 바꾸어 말했어요."],"asset":{"type":"passage","lines":["가 — 고구마·감자 : 거친 땅에서도 잘 자란다.","나 — 고추·인삼·담배 : 시장에 내다 팔면 값을 잘 받는다."],"title":"조선 후기에 많이 기른 작물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#1','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C13',2,'match','auto','조선 후기 장터 이야기와 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C13","difficulty":2,"kind":"match","stem":"조선 후기 장터 이야기와 낱말을 알맞게 이으세요.","pairs":[{"l":"① 닷새마다 선 장","r":"장시"},{"l":"② 이 장 저 장 다닌 상인","r":"보부상"},{"l":"③ 작고 썩지 않는 쇠돈","r":"상평통보"}],"mis":"SO5-2-u2-X23","explanation":["장은 장시예요.","다닌 상인은 보부상이에요.","쇠돈은 상평통보예요."],"asset":{"type":"passage","lines":["① 닷새마다 사람이 많이 모이는 곳에 장이 섰다.","② 등에 짐을 지거나 봇짐을 든 상인이 이 장 저 장을 다녔다.","③ 쌀이나 옷감 대신 작고 썩지 않는 쇠돈으로 값을 치렀다."],"title":"조선 후기 장터 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#2','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C12',2,'mc','auto','조선 후기 농민들이 농업 생산량을 늘리려 애쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X21','SO5-2-u2-X39']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"mc","stem":"조선 후기 농민들이 농업 생산량을 늘리려 애쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 번의 전쟁으로 땅이 거칠어져 먹고사는 일이 급했기 때문에","correct":true},{"t":"나라에서 농사를 금지했기 때문에","mis":"SO5-2-u2-X21"},{"t":"곡식이 너무 많이 남았기 때문에","mis":"SO5-2-u2-X21"},{"t":"개항으로 쌀을 수입했기 때문에","mis":"SO5-2-u2-X39"}],"explanation":["전쟁 뒤였어요.","땅이 거칠어졌어요.","먹고살아야 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#3','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C12',3,'mc','auto','모내기법 관찰 메모 ㉮~㉱를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X21','SO5-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C12","difficulty":3,"kind":"mc","stem":"모내기법 관찰 메모 ㉮~㉱를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?","options":[{"t":"옮겨 심어 잡초 뽑기 쉬움 → 일손이 줄고 생산량이 늚 → 넓은 땅을 짓는 잘사는 농민이 나타남","correct":true},{"t":"모를 옮겨 심음 → 일손이 늚 → 쌀이 줄어듦","mis":"SO5-2-u2-X21"},{"t":"잡초가 많아짐 → 보리를 못 심음 → 굶주림","mis":"SO5-2-u2-X21"},{"t":"씨를 뿌림 → 상평통보가 생김 → 양반이 줄어듦","mis":"SO5-2-u2-X24"}],"explanation":["잡초 뽑기가 쉬워요.","일손이 줄어요.","넓은 땅을 지어요."],"asset":{"type":"passage","lines":["㉮ 모판에 씨를 뿌려 어린 모를 키운다.","㉯ 자란 모를 논에 줄 맞춰 옮겨 심는다.","㉰ 줄이 반듯해 잡초를 뽑기 쉽다.","㉱ 벼를 거둔 논에 보리를 심어 한 번 더 거둔다."],"title":"모내기법 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#4','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C13',3,'mc','auto','오늘날 여러 곳에서 열리는 오일장으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X23']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C13","difficulty":3,"kind":"mc","stem":"오늘날 여러 곳에서 열리는 오일장으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"조선 후기에 퍼진 장시가 오늘날까지 이어지고 있다","correct":true},{"t":"오일장은 개항 이후 서양에서 들어왔다","mis":"SO5-2-u2-X39"},{"t":"장시는 조선 전기에 모두 사라졌다","mis":"SO5-2-u2-X23"},{"t":"오일장은 세종 때 처음 생겼다","mis":"SO5-2-u2-X39"}],"explanation":["닷새마다 열려요.","장시와 같아요.","오늘까지 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#5','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C13',3,'ox','auto','상업이 발달하면서 상평통보 같은 돈이 전국에서 쓰인 것은 사고파는 일이 많아졌다는 증거예요.',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C13","difficulty":3,"kind":"ox","stem":"상업이 발달하면서 상평통보 같은 돈이 전국에서 쓰인 것은 사고파는 일이 많아졌다는 증거예요.","answer":"O","reason_options":[{"t":"사고파는 일이 많아야 편리한 돈이 전국에서 필요해지기 때문에","correct":true},{"t":"돈은 장사와 아무 관계가 없기 때문에","mis":"SO5-2-u2-X23"}],"mis":"SO5-2-u2-X23","explanation":["장사가 늘었어요.","편리한 돈이 필요했어요.","전국에서 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#6','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C13',3,'error','auto','조선 후기 상업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X23']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C13","difficulty":3,"kind":"error","stem":"조선 후기 상업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「상평통보는 세종 때 만들어 장시에서 썼어.」","correct":true,"mis_target":"SO5-2-u2-X39"},{"t":"수안 — 「보부상은 여러 장시를 돌아다녔어.」","mis":"SO5-2-u2-X23"},{"t":"유진 — 「상평통보는 작고 썩지 않아 편리했어.」","mis":"SO5-2-u2-X23"}],"explanation":["상평통보는 조선 후기예요.","세종은 조선 전기예요.","태경이 시대를 섞었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#7','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C12',3,'mc','auto','조선 후기에 많이 기른 작물 가와 나를 함께 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X22','SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C12","difficulty":3,"kind":"mc","stem":"조선 후기에 많이 기른 작물 가와 나를 함께 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가는 배고픔을 덜고, 나는 팔아서 이익을 얻는 데 쓰여 농민들은 두 길을 함께 걸었다","correct":true},{"t":"가와 나 모두 제사에만 썼다","mis":"SO5-2-u2-X22"},{"t":"가는 팔기만, 나는 먹기만 했다","mis":"SO5-2-u2-X22"},{"t":"두 작물 모두 조선 전기부터 길렀다","mis":"SO5-2-u2-X39"}],"explanation":["가는 먹을거리예요.","나는 팔 거리예요.","두 길을 함께 걸었어요."],"asset":{"type":"passage","lines":["가 — 고구마·감자 : 거친 땅에서도 잘 자란다.","나 — 고추·인삼·담배 : 시장에 내다 팔면 값을 잘 받는다."],"title":"조선 후기에 많이 기른 작물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#8','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C12',4,'mc','auto','조선 후기 경제 변화가 사람들에게 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X21','SO5-2-u2-X23','SO5-2-u2-X40']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C12","difficulty":4,"kind":"mc","stem":"조선 후기 경제 변화가 사람들에게 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"농업과 상업이 발달해 돈을 모아 부유해진 사람이 늘어났다","correct":true},{"t":"모두가 똑같이 가난해졌다","mis":"SO5-2-u2-X21"},{"t":"장사가 사라져 돈을 쓰지 않았다","mis":"SO5-2-u2-X23"},{"t":"사람들의 생활은 하나도 달라지지 않았다","mis":"SO5-2-u2-X40"}],"explanation":["생산이 늘었어요.","장사가 활발해졌어요.","부유해진 사람이 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#9','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C13',4,'mc','auto','조선 후기 장터 이야기 ①~③을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C13","difficulty":4,"kind":"mc","stem":"조선 후기 장터 이야기 ①~③을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"사고파는 일이 늘어 장시·보부상·상평통보가 함께 발달했다","correct":true},{"t":"장시만 늘고 돈은 쓰지 않았다","mis":"SO5-2-u2-X23"},{"t":"보부상은 장시와 관계없었다","mis":"SO5-2-u2-X23"},{"t":"상평통보 때문에 장사가 줄었다","mis":"SO5-2-u2-X23"}],"explanation":["장시가 늘었어요.","보부상이 다녔어요.","돈이 쓰였어요."],"asset":{"type":"passage","lines":["① 닷새마다 사람이 많이 모이는 곳에 장이 섰다.","② 등에 짐을 지거나 봇짐을 든 상인이 이 장 저 장을 다녔다.","③ 쌀이나 옷감 대신 작고 썩지 않는 쇠돈으로 값을 치렀다."],"title":"조선 후기 장터 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L05_challenge#10','soc',5,2,'u2','L05','g5_2_soc_u2_L05_challenge','lesson_challenge','SO5-2-u2-C12',4,'essay','teacher','모내기법 관찰 메모와 조선 후기에 많이 기른 작물을 보고, 조선 후기 농업이 어떻게 달라졌는지 쓰고 그 변화가 농민의 생활에 준 영향을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C12","difficulty":4,"kind":"essay","stem":"모내기법 관찰 메모와 조선 후기에 많이 기른 작물을 보고, 조선 후기 농업이 어떻게 달라졌는지 쓰고 그 변화가 농민의 생활에 준 영향을 두 가지 쓰세요.","answer_guide":{"answer":"예: 어린 모를 논에 옮겨 심는 모내기법이 전국으로 퍼지고, 고구마·감자·고추·인삼·담배 같은 새 작물을 많이 길렀다. 잡초 뽑기가 쉬워져 일손이 줄고 벼를 거둔 땅에 보리까지 심어 먹을 것이 늘었다. 또 고추·인삼을 시장에 팔아 이익을 얻어 부유해진 농민도 나타났다.","scoring_points":["모내기법을 썼는가","새 작물을 썼는가","생활에 준 영향을 두 가지 썼는가"]},"explanation":["모내기법이에요.","새 작물이에요.","먹을 것과 이익이 늘었어요."],"asset":{"type":"passage","lines":["㉮ 모판에 씨를 뿌려 어린 모를 키운다.","㉯ 자란 모를 논에 줄 맞춰 옮겨 심는다.","㉰ 줄이 반듯해 잡초를 뽑기 쉽다.","㉱ 벼를 거둔 논에 보리를 심어 한 번 더 거둔다."],"title":"모내기법 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#1','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C15',1,'mc','auto','백성의 삶과 이어진 현실의 사회 문제를 풀려고 한 조선 후기의 학문은 어느 것인가요?',ARRAY['SO5-2-u2-X27','SO5-2-u2-X28']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C15","difficulty":1,"kind":"mc","stem":"백성의 삶과 이어진 현실의 사회 문제를 풀려고 한 조선 후기의 학문은 어느 것인가요?","options":[{"t":"실학","correct":true},{"t":"유교 이론","mis":"SO5-2-u2-X27"},{"t":"천주교","mis":"SO5-2-u2-X28"},{"t":"불교","mis":"SO5-2-u2-X27"}],"explanation":["현실을 봤어요.","농업·상업을 연구했어요.","실학이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#2','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C16',1,'sa','auto','「사람이 곧 하늘」이라며 우리 것을 지키자고 한 종교는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C16","difficulty":1,"kind":"sa","stem":"「사람이 곧 하늘」이라며 우리 것을 지키자고 한 종교는 무엇인가요? 두 글자로 쓰세요.","answer":["동학"],"explanation":["우리 것을 지키자고 했어요.","평등을 말했어요.","동학이에요."],"mis":"SO5-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#3','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C14',1,'mc','auto','조선 후기에 돈을 주고 양반 신분을 사는 사람이 늘자 생긴 변화는 어느 것인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C14","difficulty":1,"kind":"mc","stem":"조선 후기에 돈을 주고 양반 신분을 사는 사람이 늘자 생긴 변화는 어느 것인가요?","options":[{"t":"양반은 늘고 상민과 천민은 줄었다","correct":true},{"t":"양반은 줄고 상민이 늘었다","mis":"SO5-2-u2-X24"},{"t":"신분제가 더 굳어졌다","mis":"SO5-2-u2-X24"},{"t":"모두 천민이 되었다","mis":"SO5-2-u2-X24"}],"explanation":["양반을 샀어요.","양반이 늘었어요.","신분제가 흔들렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#4','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C15',1,'ox','auto','자명종과 천리경 같은 서양 물건은 중국에 다녀온 사신들이 들여왔어요.',ARRAY['SO5-2-u2-X26']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C15","difficulty":1,"kind":"ox","stem":"자명종과 천리경 같은 서양 물건은 중국에 다녀온 사신들이 들여왔어요.","answer":"O","reason_options":[{"t":"사신들이 중국에서 서양 문물을 보고 가져왔기 때문에","correct":true},{"t":"서양 물건은 조선에서 처음 만들었기 때문에","mis":"SO5-2-u2-X26"}],"mis":"SO5-2-u2-X26","explanation":["사신이 중국에 갔어요.","서양 물건을 봤어요.","들여왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#5','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C14',2,'mc','auto','어느 마을 이야기 ③으로 보아 상민이 양반이 되고 싶었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C14","difficulty":2,"kind":"mc","stem":"어느 마을 이야기 ③으로 보아 상민이 양반이 되고 싶었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"양반은 세금을 거의 내지 않고 무시받지 않았기 때문에","correct":true},{"t":"양반은 세금을 더 많이 냈기 때문에","mis":"SO5-2-u2-X24"},{"t":"양반은 장사를 할 수 있었기 때문에","mis":"SO5-2-u2-X24"},{"t":"양반이 되면 천민이 되기 때문에","mis":"SO5-2-u2-X24"}],"explanation":["무시를 받았어요.","세금을 많이 냈어요.","양반은 둘 다 피했어요."],"asset":{"type":"passage","lines":["① 장사로 큰돈을 번 상민이 늘 양반에게 무시를 당했다.","② 그는 돈을 주고 가난한 양반 집안의 족보를 샀다.","③ 양반이 된 뒤로는 세금을 거의 내지 않게 되었다.","④ 마을의 세금은 남은 상민들이 더 많이 나누어 내게 되었다."],"title":"어느 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#6','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C14',2,'mc','auto','어느 마을 이야기 ④가 알려 주는 문제로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X25']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C14","difficulty":2,"kind":"mc","stem":"어느 마을 이야기 ④가 알려 주는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"세금을 낼 상민이 줄어 남은 상민의 짐이 무거워졌다","correct":true},{"t":"모든 사람의 세금이 줄었다","mis":"SO5-2-u2-X25"},{"t":"양반의 세금이 크게 늘었다","mis":"SO5-2-u2-X25"},{"t":"나라가 세금을 없앴다","mis":"SO5-2-u2-X25"}],"explanation":["양반이 늘었어요.","상민이 줄었어요.","남은 상민의 짐이 커졌어요."],"asset":{"type":"passage","lines":["① 장사로 큰돈을 번 상민이 늘 양반에게 무시를 당했다.","② 그는 돈을 주고 가난한 양반 집안의 족보를 샀다.","③ 양반이 된 뒤로는 세금을 거의 내지 않게 되었다.","④ 마을의 세금은 남은 상민들이 더 많이 나누어 내게 되었다."],"title":"어느 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#7','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C15',2,'mc','auto','사신이 들여온 서양 물건 카드 다를 본 조선 사람들의 생각이 달라진 까닭은 어느 것인가요?',ARRAY['SO5-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C15","difficulty":2,"kind":"mc","stem":"사신이 들여온 서양 물건 카드 다를 본 조선 사람들의 생각이 달라진 까닭은 어느 것인가요?","options":[{"t":"중국이 세계의 중심이라는 생각과 다른 모습을 보았기 때문에","correct":true},{"t":"지도에 조선이 가장 크게 그려져서","mis":"SO5-2-u2-X26"},{"t":"지도가 시각을 알려 주어서","mis":"SO5-2-u2-X26"},{"t":"지도에 중국이 없어서","mis":"SO5-2-u2-X26"}],"explanation":["둥근 세계 지도예요.","중국이 한쪽에 작아요.","세상을 보는 생각이 바뀌었어요."],"asset":{"type":"passage","lines":["가 — 정해진 시각이 되면 스스로 소리를 내는 시계","나 — 멀리 있는 것을 가까이 보게 하는 망원경","다 — 중국이 한쪽에 작게 그려진 둥근 세계 지도"],"title":"사신이 들여온 서양 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#8','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C15',2,'mc','auto','실학자들이 연구한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C15","difficulty":2,"kind":"mc","stem":"실학자들이 연구한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"농업·상업과 수공업, 우리 역사와 지리","correct":true},{"t":"부처의 가르침만","mis":"SO5-2-u2-X27"},{"t":"서양 종교의 제사","mis":"SO5-2-u2-X27"},{"t":"과거 시험 문제만","mis":"SO5-2-u2-X27"}],"explanation":["백성의 삶과 이어져요.","현실 문제를 풀려 했어요.","농업·상업·역사·지리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#9','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C16',2,'ox','auto','천주교와 동학은 모든 사람이 평등하다는 생각을 백성에게 전했어요.',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C16","difficulty":2,"kind":"ox","stem":"천주교와 동학은 모든 사람이 평등하다는 생각을 백성에게 전했어요.","answer":"O","reason_options":[{"t":"신분과 상관없이 사람은 평등하다고 가르쳤기 때문에","correct":true},{"t":"두 종교는 신분 차별을 더 굳히자고 했기 때문에","mis":"SO5-2-u2-X28"}],"mis":"SO5-2-u2-X28","explanation":["신분이 흔들리던 때예요.","평등을 말했어요.","백성에게 퍼졌어요."],"asset":{"type":"passage","lines":["㉮ 처음엔 서양 학문으로 들어왔다가 믿음으로 받아들여졌다.","㉯ 「사람이 곧 하늘」이라며 우리 것을 지키자고 했다.","㉰ 두 종교 모두 신분과 상관없이 사람은 평등하다고 했다.","㉱ 나라는 두 종교를 막았지만 ㉯는 백성 사이에 더 퍼졌다."],"title":"조선 후기 두 종교 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_basic#10','soc',5,2,'u2','L06','g5_2_soc_u2_L06_basic','lesson_basic','SO5-2-u2-C16',3,'error','auto','조선 후기 두 종교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C16","difficulty":3,"kind":"error","stem":"조선 후기 두 종교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가윤 — 「동학은 서양 학문으로 들어왔다가 믿음이 된 종교야.」","correct":true,"mis_target":"SO5-2-u2-X28"},{"t":"민재 — 「천주교는 처음에 서양 학문의 하나로 들어왔어.」","mis":"SO5-2-u2-X28"},{"t":"예서 — 「나라가 막았지만 동학은 백성 사이에 퍼졌어.」","mis":"SO5-2-u2-X28"}],"explanation":["서양 학문으로 들어온 건 천주교예요.","동학은 우리 것을 지키자고 했어요.","가윤이 바꾸어 말했어요."],"asset":{"type":"passage","lines":["㉮ 처음엔 서양 학문으로 들어왔다가 믿음으로 받아들여졌다.","㉯ 「사람이 곧 하늘」이라며 우리 것을 지키자고 했다.","㉰ 두 종교 모두 신분과 상관없이 사람은 평등하다고 했다.","㉱ 나라는 두 종교를 막았지만 ㉯는 백성 사이에 더 퍼졌다."],"title":"조선 후기 두 종교 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#1','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C16',2,'match','auto','조선 후기 두 종교 메모와 종교를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C16","difficulty":2,"kind":"match","stem":"조선 후기 두 종교 메모와 종교를 알맞게 이으세요.","pairs":[{"l":"㉮ 서양 학문으로 들어옴","r":"천주교"},{"l":"㉯ 사람이 곧 하늘","r":"동학"},{"l":"㉰ 사람은 평등함","r":"천주교와 동학 모두"}],"mis":"SO5-2-u2-X28","explanation":["㉮는 천주교예요.","㉯는 동학이에요.","㉰는 둘 다예요."],"asset":{"type":"passage","lines":["㉮ 처음엔 서양 학문으로 들어왔다가 믿음으로 받아들여졌다.","㉯ 「사람이 곧 하늘」이라며 우리 것을 지키자고 했다.","㉰ 두 종교 모두 신분과 상관없이 사람은 평등하다고 했다.","㉱ 나라는 두 종교를 막았지만 ㉯는 백성 사이에 더 퍼졌다."],"title":"조선 후기 두 종교 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#2','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C15',2,'mc','auto','사신이 들여온 서양 물건 카드 가는 오늘날 무엇과 같은 일을 하나요?',ARRAY['SO5-2-u2-X26','SO5-2-u2-X13']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C15","difficulty":2,"kind":"mc","stem":"사신이 들여온 서양 물건 카드 가는 오늘날 무엇과 같은 일을 하나요?","options":[{"t":"알람 시계","correct":true},{"t":"망원경","mis":"SO5-2-u2-X26"},{"t":"세계 지도","mis":"SO5-2-u2-X26"},{"t":"해시계","mis":"SO5-2-u2-X13"}],"explanation":["정해진 시각에 울려요.","스스로 소리를 내요.","알람 시계예요."],"asset":{"type":"passage","lines":["가 — 정해진 시각이 되면 스스로 소리를 내는 시계","나 — 멀리 있는 것을 가까이 보게 하는 망원경","다 — 중국이 한쪽에 작게 그려진 둥근 세계 지도"],"title":"사신이 들여온 서양 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#3','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C14',3,'mc','auto','어느 마을 이야기 ①~④를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C14","difficulty":3,"kind":"mc","stem":"어느 마을 이야기 ①~④를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?","options":[{"t":"돈을 번 상민이 양반 신분을 삼 → 양반이 늘고 상민이 줄어듦 → 남은 상민의 세금이 무거워짐","correct":true},{"t":"양반이 장사를 함 → 상민이 늘어남 → 세금이 사라짐","mis":"SO5-2-u2-X24"},{"t":"상민이 가난해짐 → 양반이 줄어듦 → 신분제가 굳어짐","mis":"SO5-2-u2-X24"},{"t":"나라가 족보를 나눠 줌 → 모두 양반이 됨 → 세금이 늘어남","mis":"SO5-2-u2-X24"}],"explanation":["돈으로 양반이 돼요.","양반이 늘어요.","남은 상민이 힘들어요."],"asset":{"type":"passage","lines":["① 장사로 큰돈을 번 상민이 늘 양반에게 무시를 당했다.","② 그는 돈을 주고 가난한 양반 집안의 족보를 샀다.","③ 양반이 된 뒤로는 세금을 거의 내지 않게 되었다.","④ 마을의 세금은 남은 상민들이 더 많이 나누어 내게 되었다."],"title":"어느 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#4','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C15',3,'mc','auto','실학이 나타난 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X27']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C15","difficulty":3,"kind":"mc","stem":"실학이 나타난 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이론에 치우친 유학이 백성의 어려움을 풀지 못했기 때문에","correct":true},{"t":"서양 종교를 믿으려고","mis":"SO5-2-u2-X27"},{"t":"과거 시험을 없애려고","mis":"SO5-2-u2-X27"},{"t":"불교를 다시 일으키려고","mis":"SO5-2-u2-X27"}],"explanation":["유학이 이론만 따졌어요.","백성은 어려웠어요.","현실을 푸는 학문이 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#5','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C16',3,'ox','auto','나라는 천주교와 동학을 막았지만 동학은 백성 사이에 더욱 퍼져 사회의 변화를 요구했어요.',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C16","difficulty":3,"kind":"ox","stem":"나라는 천주교와 동학을 막았지만 동학은 백성 사이에 더욱 퍼져 사회의 변화를 요구했어요.","answer":"O","reason_options":[{"t":"신분 차별 없는 세상을 바라는 백성이 동학을 따랐기 때문에","correct":true},{"t":"백성은 동학을 전혀 믿지 않았기 때문에","mis":"SO5-2-u2-X28"}],"mis":"SO5-2-u2-X28","explanation":["나라가 막았어요.","그래도 퍼졌어요.","변화를 요구했어요."],"asset":{"type":"passage","lines":["㉮ 처음엔 서양 학문으로 들어왔다가 믿음으로 받아들여졌다.","㉯ 「사람이 곧 하늘」이라며 우리 것을 지키자고 했다.","㉰ 두 종교 모두 신분과 상관없이 사람은 평등하다고 했다.","㉱ 나라는 두 종교를 막았지만 ㉯는 백성 사이에 더 퍼졌다."],"title":"조선 후기 두 종교 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#6','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C14',3,'error','auto','조선 후기 신분 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C14","difficulty":3,"kind":"error","stem":"조선 후기 신분 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도아 — 「조선 후기에는 양반이 크게 줄고 상민이 늘었어.」","correct":true,"mis_target":"SO5-2-u2-X24"},{"t":"준우 — 「돈으로 양반 신분을 사는 사람이 나타났어.」","mis":"SO5-2-u2-X24"},{"t":"이수 — 「그래서 신분제가 흔들렸어.」","mis":"SO5-2-u2-X24"}],"explanation":["양반이 늘었어요.","상민이 줄었어요.","도아가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#7','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C15',3,'mc','auto','서양 문물·실학·천주교·동학을 함께 볼 때 조선 후기 사람들의 생각 변화로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X26','SO5-2-u2-X28','SO5-2-u2-X40']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C15","difficulty":3,"kind":"mc","stem":"서양 문물·실학·천주교·동학을 함께 볼 때 조선 후기 사람들의 생각 변화로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세상과 사람을 보는 눈이 넓어지고 평등과 현실을 중히 여기는 생각이 퍼졌다","correct":true},{"t":"중국 중심의 생각이 더 굳어졌다","mis":"SO5-2-u2-X26"},{"t":"신분 차별이 더 당연해졌다","mis":"SO5-2-u2-X28"},{"t":"사람들의 생각은 하나도 바뀌지 않았다","mis":"SO5-2-u2-X40"}],"explanation":["세계를 새로 봤어요.","현실과 평등을 생각했어요.","생각이 넓어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#8','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C14',4,'mc','auto','조선 후기 경제 변화와 신분제의 흔들림을 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24','SO5-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C14","difficulty":4,"kind":"mc","stem":"조선 후기 경제 변화와 신분제의 흔들림을 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"농업과 상업으로 돈을 모은 사람이 늘어, 돈으로 신분을 사며 신분 질서가 흔들렸다","correct":true},{"t":"경제가 나빠져 모두 천민이 되었다","mis":"SO5-2-u2-X24"},{"t":"돈과 신분은 아무 관계가 없었다","mis":"SO5-2-u2-X24"},{"t":"개항으로 신분제가 처음 생겼다","mis":"SO5-2-u2-X39"}],"explanation":["돈을 모은 사람이 늘었어요.","양반을 샀어요.","신분 질서가 흔들렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#9','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C16',4,'mc','auto','동학이 「새로운 세상이 열린다」고 한 것이 백성에게 큰 호응을 얻은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C16","difficulty":4,"kind":"mc","stem":"동학이 「새로운 세상이 열린다」고 한 것이 백성에게 큰 호응을 얻은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분 차별과 무거운 세금에 힘들던 백성이 평등한 세상을 바랐기 때문에","correct":true},{"t":"백성이 지금 세상에 아주 만족했기 때문에","mis":"SO5-2-u2-X28"},{"t":"동학이 양반만 받아들였기 때문에","mis":"SO5-2-u2-X28"},{"t":"동학이 서양 물건을 팔았기 때문에","mis":"SO5-2-u2-X28"}],"explanation":["백성은 힘들었어요.","평등을 바랐어요.","그래서 동학이 퍼졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L06_challenge#10','soc',5,2,'u2','L06','g5_2_soc_u2_L06_challenge','lesson_challenge','SO5-2-u2-C15',4,'essay','teacher','사신이 들여온 서양 물건 카드와 실학을 함께 생각해, 조선 후기 사람들의 생각이 어떻게 달라졌는지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C15","difficulty":4,"kind":"essay","stem":"사신이 들여온 서양 물건 카드와 실학을 함께 생각해, 조선 후기 사람들의 생각이 어떻게 달라졌는지 두 가지 쓰세요.","answer_guide":{"answer":"예: 중국이 한쪽에 작게 그려진 둥근 세계 지도를 보고, 중국을 세계의 중심으로 여기던 생각이 점차 달라졌다. 또 이론에 치우친 유학 대신 농업·상업·우리 역사와 지리처럼 백성의 삶과 이어진 현실 문제를 풀려는 실학이 나타났다.","scoring_points":["서양 문물로 달라진 생각을 썼는가","실학의 뜻과 연구 내용을 썼는가","두 가지를 썼는가"]},"explanation":["세계 지도가 생각을 바꿨어요.","실학은 현실을 봤어요.","두 가지를 써요."],"asset":{"type":"passage","lines":["가 — 정해진 시각이 되면 스스로 소리를 내는 시계","나 — 멀리 있는 것을 가까이 보게 하는 망원경","다 — 중국이 한쪽에 작게 그려진 둥근 세계 지도"],"title":"사신이 들여온 서양 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#1','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C17',1,'mc','auto','돈을 받고 사람들 앞에서 한글 소설을 실감 나게 읽어 주던 사람을 무엇이라고 하나요?',ARRAY['SO5-2-u2-X30']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C17","difficulty":1,"kind":"mc","stem":"돈을 받고 사람들 앞에서 한글 소설을 실감 나게 읽어 주던 사람을 무엇이라고 하나요?","options":[{"t":"전기수","correct":true},{"t":"보부상","mis":"SO5-2-u2-X30"},{"t":"소리꾼","mis":"SO5-2-u2-X30"},{"t":"중인","mis":"SO5-2-u2-X30"}],"explanation":["이야기를 읽어 줘요.","돈을 받았어요.","전기수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#2','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',1,'mc','auto','탈을 쓰고 춤추며 양반을 비꼬거나 사회의 잘못을 꼬집은 공연은 어느 것인가요?',ARRAY['SO5-2-u2-X32']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C18","difficulty":1,"kind":"mc","stem":"탈을 쓰고 춤추며 양반을 비꼬거나 사회의 잘못을 꼬집은 공연은 어느 것인가요?","options":[{"t":"탈놀이","correct":true},{"t":"판소리","mis":"SO5-2-u2-X32"},{"t":"연등회","mis":"SO5-2-u2-X32"},{"t":"관혼상제","mis":"SO5-2-u2-X32"}],"explanation":["탈을 써요.","춤을 춰요.","탈놀이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#3','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',1,'sa','auto','백성의 생활 모습을 그린 그림을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u2-C18","difficulty":1,"kind":"sa","stem":"백성의 생활 모습을 그린 그림을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["풍속화"],"explanation":["생활 모습을 그렸어요.","서당·씨름 같은 장면이에요.","풍속화예요."],"mis":"SO5-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#4','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C17',1,'ox','auto','조선 후기에는 살림에 여유가 생긴 서민들이 문화와 예술에 관심을 두었어요.',ARRAY['SO5-2-u2-X29']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C17","difficulty":1,"kind":"ox","stem":"조선 후기에는 살림에 여유가 생긴 서민들이 문화와 예술에 관심을 두었어요.","answer":"O","reason_options":[{"t":"농사가 잘되고 장사가 활발해져 여유가 생겼기 때문에","correct":true},{"t":"서민들은 문화를 즐기는 것이 금지되었기 때문에","mis":"SO5-2-u2-X29"}],"mis":"SO5-2-u2-X29","explanation":["살림이 나아졌어요.","여유가 생겼어요.","서민 문화가 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#5','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',2,'mc','auto','서민 문화 카드 나에 해당하는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X31','SO5-2-u2-X32']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"mc","stem":"서민 문화 카드 나에 해당하는 것은 어느 것인가요?","options":[{"t":"민화","correct":true},{"t":"풍속화","mis":"SO5-2-u2-X31"},{"t":"판소리","mis":"SO5-2-u2-X32"},{"t":"탈놀이","mis":"SO5-2-u2-X32"}],"explanation":["호랑이와 까치예요.","방에 걸었어요.","민화예요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#6','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',2,'mc','auto','서민 문화 카드 다는 무엇인가요?',ARRAY['SO5-2-u2-X32','SO5-2-u2-X31']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"mc","stem":"서민 문화 카드 다는 무엇인가요?","options":[{"t":"판소리","correct":true},{"t":"탈놀이","mis":"SO5-2-u2-X32"},{"t":"민화","mis":"SO5-2-u2-X31"},{"t":"풍속화","mis":"SO5-2-u2-X31"}],"explanation":["소리꾼이 나와요.","북 장단에 맞춰요.","판소리예요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#7','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',2,'mc','auto','서민들이 민화에 담은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X31']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"mc","stem":"서민들이 민화에 담은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 살고 복을 받고 성공하기를 바라는 소망","correct":true},{"t":"나라의 법","mis":"SO5-2-u2-X31"},{"t":"전쟁의 기록","mis":"SO5-2-u2-X31"},{"t":"외국 지도","mis":"SO5-2-u2-X31"}],"explanation":["생활 공간을 꾸몄어요.","바라는 것을 그렸어요.","소망을 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#8','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C17',2,'mc','auto','장터 풍경에서 사람들이 돈을 던진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X30']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C17","difficulty":2,"kind":"mc","stem":"장터 풍경에서 사람들이 돈을 던진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다음 이야기가 궁금해 계속 듣고 싶어서","correct":true},{"t":"읽어 주는 사람을 쫓아내려고","mis":"SO5-2-u2-X30"},{"t":"물건을 사려고","mis":"SO5-2-u2-X30"},{"t":"세금을 내려고","mis":"SO5-2-u2-X30"}],"explanation":["가장 궁금한 대목이에요.","읽기를 멈췄어요.","계속 듣고 싶었어요."],"asset":{"type":"passage","lines":["장터 한쪽에 사람들이 빙 둘러앉았다.","한 사람이 한글 소설을 실감 나게 읽어 주었다.","가장 궁금한 대목에서 읽기를 멈추자 사람들이 돈을 던졌다."],"title":"장터 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#9','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C17',2,'ox','auto','한글 소설에는 여러 신분의 인물이 나와 서민의 감정과 소망을 나타냈어요.',ARRAY['SO5-2-u2-X30']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C17","difficulty":2,"kind":"ox","stem":"한글 소설에는 여러 신분의 인물이 나와 서민의 감정과 소망을 나타냈어요.","answer":"O","reason_options":[{"t":"서민들이 즐겨 읽으며 자기 마음을 이야기에서 찾았기 때문에","correct":true},{"t":"한글 소설에는 양반 인물만 나왔기 때문에","mis":"SO5-2-u2-X30"}],"mis":"SO5-2-u2-X30","explanation":["여러 신분이 나와요.","감정과 소망이 담겼어요.","사회 문제도 꼬집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_basic#10','soc',5,2,'u2','L07','g5_2_soc_u2_L07_basic','lesson_basic','SO5-2-u2-C18',3,'error','auto','서민 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X32']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C18","difficulty":3,"kind":"error","stem":"서민 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라임 — 「판소리는 탈을 쓰고 춤추며 양반을 놀리는 공연이야.」","correct":true,"mis_target":"SO5-2-u2-X32"},{"t":"도해 — 「판소리는 소리꾼이 북 장단에 맞춰 이야기를 풀어 가.」","mis":"SO5-2-u2-X32"},{"t":"소은 — 「탈놀이는 구경꾼이 함께 어울려 인기가 많았어.」","mis":"SO5-2-u2-X32"}],"explanation":["탈을 쓰는 건 탈놀이예요.","판소리는 소리꾼이에요.","라임이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#1','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',2,'match','auto','서민 문화 카드와 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"match","stem":"서민 문화 카드와 이름을 알맞게 이으세요.","pairs":[{"l":"가 서당 장면 그림","r":"풍속화"},{"l":"나 호랑이와 까치","r":"민화"},{"l":"다 소리꾼과 북","r":"판소리"},{"l":"라 탈 쓰고 춤","r":"탈놀이"}],"mis":"SO5-2-u2-X31","explanation":["생활 장면은 풍속화예요.","소망 그림은 민화예요.","판소리와 탈놀이를 갈라요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#2','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C17',2,'mc','auto','전기수가 많은 사람에게 인기를 끈 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X30','SO5-2-u2-X29']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C17","difficulty":2,"kind":"mc","stem":"전기수가 많은 사람에게 인기를 끈 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 모르거나 책이 없어도 이야기를 즐길 수 있어서","correct":true},{"t":"전기수가 세금을 걷어서","mis":"SO5-2-u2-X30"},{"t":"양반만 들을 수 있어서","mis":"SO5-2-u2-X29"},{"t":"전기수가 그림을 그려서","mis":"SO5-2-u2-X30"}],"explanation":["글을 모르는 사람이 많았어요.","책도 귀했어요.","들으면 즐길 수 있었어요."],"asset":{"type":"passage","lines":["장터 한쪽에 사람들이 빙 둘러앉았다.","한 사람이 한글 소설을 실감 나게 읽어 주었다.","가장 궁금한 대목에서 읽기를 멈추자 사람들이 돈을 던졌다."],"title":"장터 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#3','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',3,'mc','auto','탈놀이에서 양반을 비꼬는 대목이 인기를 끈 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X32']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C18","difficulty":3,"kind":"mc","stem":"탈놀이에서 양반을 비꼬는 대목이 인기를 끈 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"백성이 하고 싶던 말을 탈 쓴 사람이 대신 해 주었기 때문에","correct":true},{"t":"양반이 탈놀이를 금지했기 때문에","mis":"SO5-2-u2-X32"},{"t":"백성이 양반을 무척 존경했기 때문에","mis":"SO5-2-u2-X32"},{"t":"탈놀이가 나라의 법을 가르쳤기 때문에","mis":"SO5-2-u2-X32"}],"explanation":["신분 차별이 있었어요.","하고 싶은 말이 있었어요.","탈이 대신 말해 줬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#4','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C17',3,'mc','auto','조선 후기 경제 변화와 서민 문화의 발달을 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X29','SO5-2-u2-X39']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C17","difficulty":3,"kind":"mc","stem":"조선 후기 경제 변화와 서민 문화의 발달을 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"농업과 상업이 발달해 여유가 생긴 서민들이 문화와 예술을 즐기게 되었다","correct":true},{"t":"경제가 나빠져 서민 문화가 생겼다","mis":"SO5-2-u2-X29"},{"t":"서민 문화는 양반만 즐기려고 만들었다","mis":"SO5-2-u2-X29"},{"t":"서민 문화는 개항 뒤 서양에서 들어왔다","mis":"SO5-2-u2-X39"}],"explanation":["경제가 나아졌어요.","여유가 생겼어요.","문화를 즐겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#5','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',3,'ox','auto','판소리는 처음에 서민이 즐겼지만 시간이 지나며 양반들도 즐기게 되었어요.',ARRAY['SO5-2-u2-X29']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C18","difficulty":3,"kind":"ox","stem":"판소리는 처음에 서민이 즐겼지만 시간이 지나며 양반들도 즐기게 되었어요.","answer":"O","reason_options":[{"t":"이야기와 노래가 재미있어 신분을 넘어 사랑받았기 때문에","correct":true},{"t":"판소리는 처음부터 양반만 즐길 수 있었기 때문에","mis":"SO5-2-u2-X29"}],"mis":"SO5-2-u2-X29","explanation":["서민이 먼저 즐겼어요.","재미있었어요.","양반도 즐겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#6','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',3,'error','auto','민화와 풍속화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X31']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C18","difficulty":3,"kind":"error","stem":"민화와 풍속화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「민화는 백성의 생활 장면을 그대로 그린 그림이고, 풍속화는 소망을 담아 방에 걸었어.」","correct":true,"mis_target":"SO5-2-u2-X31"},{"t":"이찬 — 「책가도에는 공부해 훌륭한 사람이 되기를 바라는 마음이 담겼어.」","mis":"SO5-2-u2-X31"},{"t":"보라 — 「민화는 주로 이름이 알려지지 않은 화가가 그렸어.」","mis":"SO5-2-u2-X31"}],"explanation":["생활 장면은 풍속화예요.","소망은 민화예요.","하온이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#7','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',3,'mc','auto','서민 문화 카드 가처럼 서당 장면을 그린 그림으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X31','SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C18","difficulty":3,"kind":"mc","stem":"서민 문화 카드 가처럼 서당 장면을 그린 그림으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"조선 후기 아이들이 서당에서 공부하던 생활 모습","correct":true},{"t":"조선 후기 아이들은 공부를 하지 않았다","mis":"SO5-2-u2-X31"},{"t":"서당은 개항 뒤에 생겼다","mis":"SO5-2-u2-X39"},{"t":"그림은 소망만 담아 생활과 관계없다","mis":"SO5-2-u2-X31"}],"explanation":["풍속화예요.","생활 모습을 그렸어요.","서당 공부를 짐작해요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#8','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',4,'mc','auto','서민 문화 카드 가~라를 함께 볼 때 조선 후기 서민 문화의 특징으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X29','SO5-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C18","difficulty":4,"kind":"mc","stem":"서민 문화 카드 가~라를 함께 볼 때 조선 후기 서민 문화의 특징으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서민의 생활과 소망, 사회에 대한 생각이 드러나고 사람들이 함께 즐겼다","correct":true},{"t":"양반의 생활만 그렸다","mis":"SO5-2-u2-X29"},{"t":"서민은 구경만 하고 즐기지 못했다","mis":"SO5-2-u2-X29"},{"t":"불교 행사만 이어졌다","mis":"SO5-2-u2-X02"}],"explanation":["생활 모습이 나와요.","소망과 비꼼이 있어요.","함께 즐겼어요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#9','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C17',4,'mc','auto','오늘날 오디오북으로 이야기를 듣는 모습과 가장 비슷한 조선 후기의 모습은 어느 것인가요?',ARRAY['SO5-2-u2-X30']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C17","difficulty":4,"kind":"mc","stem":"오늘날 오디오북으로 이야기를 듣는 모습과 가장 비슷한 조선 후기의 모습은 어느 것인가요?","options":[{"t":"전기수가 장터에서 한글 소설을 읽어 주던 모습","correct":true},{"t":"보부상이 장시를 돌아다니던 모습","mis":"SO5-2-u2-X30"},{"t":"양반이 과거를 보던 모습","mis":"SO5-2-u2-X30"},{"t":"측우기로 비의 양을 재던 모습","mis":"SO5-2-u2-X30"}],"explanation":["목소리로 이야기를 들어요.","전기수도 그랬어요.","글을 몰라도 즐겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L07_challenge#10','soc',5,2,'u2','L07','g5_2_soc_u2_L07_challenge','lesson_challenge','SO5-2-u2-C18',4,'essay','teacher','서민 문화 카드 가운데 둘을 골라 각각 무엇인지 쓰고, 그 문화에 서민들의 어떤 생활이나 마음이 담겼는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C18","difficulty":4,"kind":"essay","stem":"서민 문화 카드 가운데 둘을 골라 각각 무엇인지 쓰고, 그 문화에 서민들의 어떤 생활이나 마음이 담겼는지 쓰세요.","answer_guide":{"answer":"예: 나는 호랑이와 까치를 그린 민화로, 서민들은 나쁜 기운이 물러가고 복이 오기를 바라며 방에 걸어 두었다. 라는 탈놀이로, 탈을 쓰고 춤추며 양반을 비꼬아 신분 차별에 대한 백성의 불만과 하고 싶던 말을 시원하게 드러냈다.","scoring_points":["둘을 골라 이름을 썼는가","각각에 담긴 생활이나 마음을 썼는가","서민의 입장과 이었는가"]},"explanation":["둘을 골라요.","이름을 써요.","담긴 마음을 써요."],"asset":{"type":"passage","lines":["가 — 서당에서 훈장님께 혼나는 아이와 웃는 친구들을 그린 그림","나 — 호랑이와 까치를 그려 방에 걸어 둔 그림","다 — 소리꾼이 북 장단에 맞추어 노래하고 말하며 이야기를 풀어 가는 공연","라 — 탈을 쓰고 춤추며 양반을 놀리는 공연"],"title":"서민 문화 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#1','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C19',1,'mc','auto','외국과 서로 물건을 사고파는 것을 무엇이라고 하나요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C19","difficulty":1,"kind":"mc","stem":"외국과 서로 물건을 사고파는 것을 무엇이라고 하나요?","options":[{"t":"통상","correct":true},{"t":"개항","mis":"SO5-2-u2-X33"},{"t":"관혼상제","mis":"SO5-2-u2-X33"},{"t":"실학","mis":"SO5-2-u2-X33"}],"explanation":["물건을 사고팔아요.","외국과 해요.","통상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#2','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C19',1,'sa','auto','조선이 일본과 강화도에서 맺은 조약을 무엇이라고 하나요? (○○○ 조약)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C19","difficulty":1,"kind":"sa","stem":"조선이 일본과 강화도에서 맺은 조약을 무엇이라고 하나요? (○○○ 조약)","answer":["강화도 조약","강화도조약"],"explanation":["강화도에서 맺었어요.","항구를 열었어요.","강화도 조약이에요."],"mis":"SO5-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#3','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',1,'mc','auto','개항 이후 세워진 학교로 오늘날 초등학교에 해당하는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C20","difficulty":1,"kind":"mc","stem":"개항 이후 세워진 학교로 오늘날 초등학교에 해당하는 것은 어느 것인가요?","options":[{"t":"소학교","correct":true},{"t":"성균관","mis":"SO5-2-u2-X39"},{"t":"향교","mis":"SO5-2-u2-X39"},{"t":"서원","mis":"SO5-2-u2-X39"}],"explanation":["개항 이후 생겼어요.","어린이가 다녔어요.","소학교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#4','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',1,'ox','auto','개항 이후 전등을 쓰면서 사람들이 활동할 수 있는 시간이 늘어났어요.',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C20","difficulty":1,"kind":"ox","stem":"개항 이후 전등을 쓰면서 사람들이 활동할 수 있는 시간이 늘어났어요.","answer":"O","reason_options":[{"t":"밤에도 방과 길을 밝힐 수 있었기 때문에","correct":true},{"t":"전등은 소식을 주고받는 기계였기 때문에","mis":"SO5-2-u2-X35"}],"mis":"SO5-2-u2-X35","explanation":["전등은 빛을 내요.","밤이 밝아졌어요.","활동 시간이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#5','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C19',2,'mc','auto','개항 과정 메모를 차례로 볼 때 조선이 처음 조약을 맺은 나라는 어디인가요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C19","difficulty":2,"kind":"mc","stem":"개항 과정 메모를 차례로 볼 때 조선이 처음 조약을 맺은 나라는 어디인가요?","options":[{"t":"일본","correct":true},{"t":"영국","mis":"SO5-2-u2-X33"},{"t":"미국","mis":"SO5-2-u2-X33"},{"t":"청","mis":"SO5-2-u2-X33"}],"explanation":["③에 일본이 나와요.","④에서 조약을 맺어요.","서양과는 그 뒤예요."],"asset":{"type":"passage","lines":["① 서양 여러 나라의 배가 바닷가에 나타나 통상을 요구했다.","② 조선은 처음에 이 요구를 거부했다.","③ 일본이 무력을 앞세워 조약을 맺자고 했다.","④ 강화도에서 조약을 맺고 항구를 열었다.","⑤ 그 뒤 서양 여러 나라와도 조약을 맺었다."],"title":"개항 과정 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#6','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',2,'mc','auto','근대 문물 쓰임 카드 ㉯에 해당하는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"mc","stem":"근대 문물 쓰임 카드 ㉯에 해당하는 것은 어느 것인가요?","options":[{"t":"전신과 전화","correct":true},{"t":"전등","mis":"SO5-2-u2-X35"},{"t":"전차","mis":"SO5-2-u2-X35"},{"t":"신문","mis":"SO5-2-u2-X35"}],"explanation":["멀리 소식을 보내요.","빠르게 주고받아요.","전신과 전화예요."],"asset":{"type":"passage","lines":["㉮ 밤에도 방과 길을 오래 밝힌다.","㉯ 멀리 있는 사람과 소식을 빠르게 주고받는다.","㉰ 큰길을 달려 먼 곳까지 사람을 실어 나른다.","㉱ 나라 안팎의 소식과 물건 광고가 실린다."],"title":"근대 문물 쓰임 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#7','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',2,'mc','auto','전차가 다니면서 달라진 거리의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X35','SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"mc","stem":"전차가 다니면서 달라진 거리의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"길이 넓어지고 전봇대와 전선이 세워졌다","correct":true},{"t":"길이 좁아지고 장시가 사라졌다","mis":"SO5-2-u2-X35"},{"t":"성벽이 새로 쌓였다","mis":"SO5-2-u2-X35"},{"t":"거리에 해시계가 놓였다","mis":"SO5-2-u2-X39"}],"explanation":["전차는 커요.","전기가 필요해요.","길과 전봇대가 생겼어요."],"asset":{"type":"passage","lines":["전차를 놓으려고 길을 넓히고 전봇대를 세웠다.","자리는 신분이 아니라 낸 돈에 따라 나뉘었다.","남자와 여자가 같은 전차를 타고 다녔다."],"title":"전차 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#8','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C19',2,'mc','auto','강화도 조약에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X34','SO5-2-u2-X33','SO5-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C19","difficulty":2,"kind":"mc","stem":"강화도 조약에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"외국과 맺은 첫 근대적 조약이지만 조선에 불리한 불평등 조약이었다","correct":true},{"t":"두 나라에 똑같이 공평한 조약이었다","mis":"SO5-2-u2-X34"},{"t":"조선이 서양과 맺은 첫 조약이었다","mis":"SO5-2-u2-X33"},{"t":"임진왜란을 끝낸 조약이었다","mis":"SO5-2-u2-X39"}],"explanation":["첫 근대적 조약이에요.","무력을 앞세워 맺었어요.","불평등했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#9','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',2,'ox','auto','개항 이후 신문이 만들어져 사람들이 나라 안팎의 새 소식을 접할 수 있게 되었어요.',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"ox","stem":"개항 이후 신문이 만들어져 사람들이 나라 안팎의 새 소식을 접할 수 있게 되었어요.","answer":"O","reason_options":[{"t":"신문에 여러 소식과 다양한 생각, 물건 광고가 실렸기 때문에","correct":true},{"t":"신문은 조선 전기에 이미 날마다 나왔기 때문에","mis":"SO5-2-u2-X35"}],"mis":"SO5-2-u2-X35","explanation":["신문이 생겼어요.","소식이 실렸어요.","많은 사람이 알게 됐어요."],"asset":{"type":"passage","lines":["㉮ 밤에도 방과 길을 오래 밝힌다.","㉯ 멀리 있는 사람과 소식을 빠르게 주고받는다.","㉰ 큰길을 달려 먼 곳까지 사람을 실어 나른다.","㉱ 나라 안팎의 소식과 물건 광고가 실린다."],"title":"근대 문물 쓰임 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_basic#10','soc',5,2,'u2','L08','g5_2_soc_u2_L08_basic','lesson_basic','SO5-2-u2-C20',3,'error','auto','근대 문물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"error","stem":"근대 문물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태라 — 「전화로 밤길을 밝히고, 전등으로 멀리 소식을 전했어.」","correct":true,"mis_target":"SO5-2-u2-X35"},{"t":"윤아 — 「전화 교환수라는 새 직업이 생겼어.」","mis":"SO5-2-u2-X35"},{"t":"라현 — 「전차로 생활 범위가 넓어졌어.」","mis":"SO5-2-u2-X35"}],"explanation":["밤을 밝힌 건 전등이에요.","소식은 전화예요.","태라가 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#1','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',2,'match','auto','근대 문물 쓰임 카드와 근대 문물을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"match","stem":"근대 문물 쓰임 카드와 근대 문물을 알맞게 이으세요.","pairs":[{"l":"㉮ 밤을 밝힘","r":"전등"},{"l":"㉯ 소식을 빠르게","r":"전신·전화"},{"l":"㉰ 사람을 실어 나름","r":"전차"},{"l":"㉱ 소식과 광고","r":"신문"}],"mis":"SO5-2-u2-X35","explanation":["빛은 전등이에요.","소식은 전신·전화예요.","전차와 신문을 갈라요."],"asset":{"type":"passage","lines":["㉮ 밤에도 방과 길을 오래 밝힌다.","㉯ 멀리 있는 사람과 소식을 빠르게 주고받는다.","㉰ 큰길을 달려 먼 곳까지 사람을 실어 나른다.","㉱ 나라 안팎의 소식과 물건 광고가 실린다."],"title":"근대 문물 쓰임 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#2','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C19',2,'mc','auto','외국과의 교류에 관한 두 의견에서 반대하는 쪽의 걱정으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C19","difficulty":2,"kind":"mc","stem":"외국과의 교류에 관한 두 의견에서 반대하는 쪽의 걱정으로 알맞은 것은 어느 것인가요?","options":[{"t":"백성에게 중요한 농산물이 빠져나가 나라가 위태로워질 것","correct":true},{"t":"새 문물이 너무 적게 들어올 것","mis":"SO5-2-u2-X33"},{"t":"조선이 너무 빨리 발전할 것","mis":"SO5-2-u2-X33"},{"t":"외국 배가 오지 않을 것","mis":"SO5-2-u2-X33"}],"explanation":["반대 의견을 읽어요.","농산물이 걱정이에요.","나라가 위태롭다고 했어요."],"asset":{"type":"passage","lines":["찬성 — 「여러 나라와 통상하고 새 문물을 받아들여야 나라가 발전한다.」","반대 — 「저들이 바라는 건 백성에게 중요한 농산물이니 나라가 위태롭다.」"],"title":"외국과의 교류에 관한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#3','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',3,'mc','auto','전차 이야기로 보아 전차가 유교 질서에 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X36']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"mc","stem":"전차 이야기로 보아 전차가 유교 질서에 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분과 남녀의 구별을 엄격히 하던 생각이 점차 달라졌다","correct":true},{"t":"신분 구별이 더 엄격해졌다","mis":"SO5-2-u2-X36"},{"t":"여자는 전차를 탈 수 없었다","mis":"SO5-2-u2-X36"},{"t":"전차 자리는 양반만 앉았다","mis":"SO5-2-u2-X36"}],"explanation":["자리를 돈으로 나눴어요.","남녀가 함께 탔어요.","생각이 달라졌어요."],"asset":{"type":"passage","lines":["전차를 놓으려고 길을 넓히고 전봇대를 세웠다.","자리는 신분이 아니라 낸 돈에 따라 나뉘었다.","남자와 여자가 같은 전차를 타고 다녔다."],"title":"전차 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#4','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C19',3,'mc','auto','개항 과정 메모 ①~⑤를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C19","difficulty":3,"kind":"mc","stem":"개항 과정 메모 ①~⑤를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"처음엔 통상을 거부했지만 일본의 무력에 강화도 조약을 맺고 개항한 뒤 서양과도 교류했다","correct":true},{"t":"처음부터 서양과 먼저 조약을 맺었다","mis":"SO5-2-u2-X33"},{"t":"일본과 조약 없이 항구를 열었다","mis":"SO5-2-u2-X33"},{"t":"통상 요구를 끝까지 거부해 개항하지 않았다","mis":"SO5-2-u2-X33"}],"explanation":["처음엔 거부했어요.","일본과 조약을 맺었어요.","서양과는 그 뒤예요."],"asset":{"type":"passage","lines":["① 서양 여러 나라의 배가 바닷가에 나타나 통상을 요구했다.","② 조선은 처음에 이 요구를 거부했다.","③ 일본이 무력을 앞세워 조약을 맺자고 했다.","④ 강화도에서 조약을 맺고 항구를 열었다.","⑤ 그 뒤 서양 여러 나라와도 조약을 맺었다."],"title":"개항 과정 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#5','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',3,'ox','auto','개항 이후 서양식 옷을 입은 사람과 한복을 입은 사람이 함께 어울려 지냈어요.',ARRAY['SO5-2-u2-X37']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"ox","stem":"개항 이후 서양식 옷을 입은 사람과 한복을 입은 사람이 함께 어울려 지냈어요.","answer":"O","reason_options":[{"t":"새 문물이 들어와도 생활은 도시부터 조금씩 바뀌었기 때문에","correct":true},{"t":"개항하자마자 모든 사람이 양복만 입었기 때문에","mis":"SO5-2-u2-X37"}],"mis":"SO5-2-u2-X37","explanation":["양복이 들어왔어요.","한복도 입었어요.","조금씩 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#6','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C19',3,'error','auto','개항을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X34','SO5-2-u2-X33']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C19","difficulty":3,"kind":"error","stem":"개항을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"찬희 — 「강화도 조약은 두 나라가 똑같이 이익을 나눈 공평한 조약이었어.」","correct":true,"mis_target":"SO5-2-u2-X34"},{"t":"소담 — 「서양 배들의 통상 요구를 처음에는 거부했어.」","mis":"SO5-2-u2-X33"},{"t":"태린 — 「교류를 두고 찬성과 반대 의견이 맞섰어.」","mis":"SO5-2-u2-X33"}],"explanation":["강화도 조약은 불평등했어요.","조선에 불리했어요.","찬희의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["찬성 — 「여러 나라와 통상하고 새 문물을 받아들여야 나라가 발전한다.」","반대 — 「저들이 바라는 건 백성에게 중요한 농산물이니 나라가 위태롭다.」"],"title":"외국과의 교류에 관한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#7','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',3,'mc','auto','「양말·양복·양옥」처럼 앞에 「양」이 붙은 말이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X37']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"mc","stem":"「양말·양복·양옥」처럼 앞에 「양」이 붙은 말이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"개항 이후 서양에서 들어온 물건과 생활이 오늘날까지 이어졌기 때문에","correct":true},{"t":"조선 전기에 만든 말이기 때문에","mis":"SO5-2-u2-X39"},{"t":"「양」이 양반을 뜻하기 때문에","mis":"SO5-2-u2-X37"},{"t":"불교에서 온 말이기 때문에","mis":"SO5-2-u2-X37"}],"explanation":["「양」은 서양이에요.","개항 뒤 들어왔어요.","오늘까지 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#8','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',4,'mc','auto','개항 이후의 변화를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X37','SO5-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C20","difficulty":4,"kind":"mc","stem":"개항 이후의 변화를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"서양식 의식주·학교·전기 시설·신문이 들어와 생활 범위와 생각까지 달라지기 시작했다","correct":true},{"t":"개항 뒤에도 생활은 하나도 달라지지 않았다","mis":"SO5-2-u2-X37"},{"t":"모든 사람이 하루아침에 서양식으로만 살았다","mis":"SO5-2-u2-X37"},{"t":"개항 뒤 장시와 판소리가 처음 생겼다","mis":"SO5-2-u2-X39"}],"explanation":["새 문물이 들어왔어요.","생활이 바뀌었어요.","생각도 바뀌기 시작했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#9','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C19',4,'mc','auto','외국과의 교류에 관한 두 의견을 보고 그때 사람들의 처지를 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C19","difficulty":4,"kind":"mc","stem":"외국과의 교류에 관한 두 의견을 보고 그때 사람들의 처지를 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"서양을 잘 아는 사람은 찬성하고, 농산물이 걱정인 사람은 반대했을 것처럼 처지에 따라 생각이 달랐다","correct":true},{"t":"모든 사람이 같은 의견이었다","mis":"SO5-2-u2-X33"},{"t":"농민들은 모두 통상을 반겼다","mis":"SO5-2-u2-X33"},{"t":"찬반 의견은 아무 까닭이 없었다","mis":"SO5-2-u2-X33"}],"explanation":["찬성은 발전을 말해요.","반대는 농산물을 걱정해요.","처지에 따라 달라요."],"asset":{"type":"passage","lines":["찬성 — 「여러 나라와 통상하고 새 문물을 받아들여야 나라가 발전한다.」","반대 — 「저들이 바라는 건 백성에게 중요한 농산물이니 나라가 위태롭다.」"],"title":"외국과의 교류에 관한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L08_challenge#10','soc',5,2,'u2','L08','g5_2_soc_u2_L08_challenge','lesson_challenge','SO5-2-u2-C20',4,'essay','teacher','근대 문물 쓰임 카드 가운데 둘을 골라, 개항 이전과 견주어 사람들의 생활이 어떻게 달라졌는지 「전에는 ~했는데 이제는 ~하게 되었다」 꼴로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C20","difficulty":4,"kind":"essay","stem":"근대 문물 쓰임 카드 가운데 둘을 골라, 개항 이전과 견주어 사람들의 생활이 어떻게 달라졌는지 「전에는 ~했는데 이제는 ~하게 되었다」 꼴로 쓰세요.","answer_guide":{"answer":"예: 전에는 밤이 되면 등잔불에 기대 일찍 쉬었는데, 이제는 전등으로 방과 길을 밝혀 활동할 수 있는 시간이 늘었다. 전에는 먼 곳에 소식을 전하려면 편지를 들고 사람이 오가야 했는데, 이제는 전신과 전화로 빠르게 주고받게 되었다.","scoring_points":["근대 문물 둘을 골랐는가","개항 이전과 견주었는가","달라진 생활을 바르게 썼는가"]},"explanation":["둘을 골라요.","전과 견주어요.","달라진 생활을 써요."],"asset":{"type":"passage","lines":["㉮ 밤에도 방과 길을 오래 밝힌다.","㉯ 멀리 있는 사람과 소식을 빠르게 주고받는다.","㉰ 큰길을 달려 먼 곳까지 사람을 실어 나른다.","㉱ 나라 안팎의 소식과 물건 광고가 실린다."],"title":"근대 문물 쓰임 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#1','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',1,'mc','auto','역사 만화를 그릴 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C21","difficulty":1,"kind":"mc","stem":"역사 만화를 그릴 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"단원에서 공부한 생활 모습 가운데 그리고 싶은 주제를 고른다","correct":true},{"t":"제목부터 쓰고 끝낸다","mis":"SO5-2-u2-X38"},{"t":"친구 작품부터 감상한다","mis":"SO5-2-u2-X38"},{"t":"색칠부터 한다","mis":"SO5-2-u2-X38"}],"explanation":["주제를 골라요.","내용을 정리해요.","그다음 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#2','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',1,'mc','auto','역사 만화에서 반드시 지켜야 할 것은 어느 것인가요?',ARRAY['SO5-2-u2-X38','SO5-2-u2-X40']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C21","difficulty":1,"kind":"mc","stem":"역사 만화에서 반드시 지켜야 할 것은 어느 것인가요?","options":[{"t":"핵심 내용이 역사적 사실에서 벗어나지 않게 한다","correct":true},{"t":"사실보다 재미만 생각한다","mis":"SO5-2-u2-X38"},{"t":"다른 시대 물건을 섞어 넣는다","mis":"SO5-2-u2-X38"},{"t":"인물 이름만 크게 쓴다","mis":"SO5-2-u2-X40"}],"explanation":["표현은 자유로워요.","내용은 사실이어야 해요.","사실을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#3','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',1,'sa','auto','만화를 다 그린 뒤 내용에 어울리게 붙이는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u2-C21","difficulty":1,"kind":"sa","stem":"만화를 다 그린 뒤 내용에 어울리게 붙이는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["제목"],"explanation":["만화 위에 써요.","내용을 한마디로 나타내요.","제목이에요."],"mis":"SO5-2-u2-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#4','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',1,'ox','auto','역사 만화는 그때 사람들의 생각과 생활 모습이 잘 드러나게 그려야 해요.',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C21","difficulty":1,"kind":"ox","stem":"역사 만화는 그때 사람들의 생각과 생활 모습이 잘 드러나게 그려야 해요.","answer":"O","reason_options":[{"t":"공부한 내용을 다른 사람에게 알기 쉽게 전하는 것이 목적이기 때문에","correct":true},{"t":"역사 만화는 오늘날 모습만 그려야 하기 때문에","mis":"SO5-2-u2-X38"}],"mis":"SO5-2-u2-X38","explanation":["생각이 드러나요.","생활이 드러나요.","알기 쉽게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#5','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',2,'mc','auto','우리 반 역사 만화 계획 가운데 사실과 어긋나는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"mc","stem":"우리 반 역사 만화 계획 가운데 사실과 어긋나는 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SO5-2-u2-X38"},{"t":"㉯","mis":"SO5-2-u2-X38"},{"t":"㉱","mis":"SO5-2-u2-X38"}],"explanation":["상평통보는 조선 후기 돈이에요.","세종은 조선 전기예요.","㉰가 시대를 섞었어요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#6','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',2,'mc','auto','우리 반 역사 만화 계획 ㉱의 제목에 어울리는 장면으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"mc","stem":"우리 반 역사 만화 계획 ㉱의 제목에 어울리는 장면으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음 양복을 입은 사람이 한복 입은 친구를 만나 서로 놀라는 장면","correct":true},{"t":"서당에서 훈장님께 혼나는 장면","mis":"SO5-2-u2-X38"},{"t":"남한산성에서 신하들이 다투는 장면","mis":"SO5-2-u2-X38"},{"t":"모내기를 하는 장면","mis":"SO5-2-u2-X38"}],"explanation":["개항 이후예요.","옷차림이 달라졌어요.","생각도 달라졌어요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#7','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',2,'mc','auto','「부자 상민, 양반을 꿈꾸다」 만화에 넣기 알맞은 대사는 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"mc","stem":"「부자 상민, 양반을 꿈꾸다」 만화에 넣기 알맞은 대사는 어느 것인가요?","options":[{"t":"「인삼을 길러 큰돈을 벌었으니 이제 양반 족보를 사야겠네.」","correct":true},{"t":"「전차를 타고 양반 시험을 보러 가세.」","mis":"SO5-2-u2-X38"},{"t":"「고려청자를 팔아 과거에 붙었네.」","mis":"SO5-2-u2-X38"},{"t":"「훈민정음이 없어 편지를 못 쓰겠네.」","mis":"SO5-2-u2-X38"}],"explanation":["조선 후기예요.","인삼으로 돈을 벌었어요.","돈으로 양반이 되려 해요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#8','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',2,'mc','auto','「서당 가는 날」 만화에 담기 알맞은 내용은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"mc","stem":"「서당 가는 날」 만화에 담기 알맞은 내용은 어느 것인가요?","options":[{"t":"마을 아이들이 훈장님께 글을 배우며 유교의 가르침을 익히는 모습","correct":true},{"t":"아이들이 소학교에서 체육을 배우는 모습","mis":"SO5-2-u2-X38"},{"t":"아이들이 성균관에서 과거를 보는 모습","mis":"SO5-2-u2-X38"},{"t":"아이들이 신문 광고를 읽는 모습","mis":"SO5-2-u2-X38"}],"explanation":["서당은 마을 글방이에요.","훈장님이 가르쳐요.","유교를 익혀요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#9','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',2,'ox','auto','친구의 역사 만화를 감상할 때 주제와 표현이 잘 어울리는지 살펴보면 좋아요.',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"ox","stem":"친구의 역사 만화를 감상할 때 주제와 표현이 잘 어울리는지 살펴보면 좋아요.","answer":"O","reason_options":[{"t":"주제가 잘 드러나야 공부한 내용이 바르게 전해지기 때문에","correct":true},{"t":"감상할 때는 그림 솜씨만 보면 되기 때문에","mis":"SO5-2-u2-X38"}],"mis":"SO5-2-u2-X38","explanation":["주제를 봐요.","표현을 봐요.","어울리는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_basic#10','soc',5,2,'u2','L09','g5_2_soc_u2_L09_basic','lesson_basic','SO5-2-u2-C21',3,'error','auto','역사 만화를 그리며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X38']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"error","stem":"역사 만화를 그리며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「임진왜란 만화에 전차를 타고 싸우러 가는 장면을 넣자.」","correct":true,"mis_target":"SO5-2-u2-X39"},{"t":"도하 — 「의병이 스스로 모여 싸우는 장면을 넣자.」","mis":"SO5-2-u2-X38"},{"t":"유찬 — 「이순신의 수군이 바다에서 싸우는 장면도 좋아.」","mis":"SO5-2-u2-X38"}],"explanation":["전차는 개항 이후예요.","임진왜란과 맞지 않아요.","서윤의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#1','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',2,'mc','auto','역사 만화를 그리는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"mc","stem":"역사 만화를 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 고르기 → 나타낼 내용 정리하기 → 그리고 제목 쓰기 → 함께 감상하기","correct":true},{"t":"제목 쓰기 → 감상하기 → 주제 고르기 → 그리기","mis":"SO5-2-u2-X38"},{"t":"그리기 → 주제 고르기 → 감상하기 → 정리하기","mis":"SO5-2-u2-X38"},{"t":"감상하기 → 제목 쓰기 → 정리하기 → 그리기","mis":"SO5-2-u2-X38"}],"explanation":["주제가 먼저예요.","내용을 정리해요.","그리고 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#2','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',2,'match','auto','우리 반 역사 만화 계획과 공부한 주제를 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C21","difficulty":2,"kind":"match","stem":"우리 반 역사 만화 계획과 공부한 주제를 알맞게 이으세요.","pairs":[{"l":"㉮ 부자 상민","r":"조선 후기 달라진 사회"},{"l":"㉯ 서당 가는 날","r":"유교를 바탕으로 한 조선"},{"l":"㉱ 달라진 옷차림","r":"개항 이후 달라진 생활"}],"mis":"SO5-2-u2-X38","explanation":["㉮는 신분 변화예요.","㉯는 유교 교육이에요.","㉱는 개항이에요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#3','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',3,'mc','auto','우리 반 역사 만화 계획 ㉰를 사실에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"mc","stem":"우리 반 역사 만화 계획 ㉰를 사실에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 후기 장터에서 상평통보로 떡을 사는 아이","correct":true},{"t":"세종 때 장터에서 전차를 타는 아이","mis":"SO5-2-u2-X39"},{"t":"세종 때 장터에서 신문을 읽는 아이","mis":"SO5-2-u2-X39"},{"t":"고려 때 장터에서 상평통보를 쓰는 아이","mis":"SO5-2-u2-X39"}],"explanation":["상평통보는 조선 후기예요.","시대를 맞춰요.","조선 후기로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#4','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',3,'mc','auto','「유교 질서에 따른 조선 사회」를 만화로 그릴 때 가장 알맞은 장면은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"mc","stem":"「유교 질서에 따른 조선 사회」를 만화로 그릴 때 가장 알맞은 장면은 어느 것인가요?","options":[{"t":"집안 어른의 제사를 유교 예절에 맞추어 지내는 가족","correct":true},{"t":"탈을 쓰고 양반을 놀리는 마당","mis":"SO5-2-u2-X38"},{"t":"전등 아래에서 신문을 읽는 사람","mis":"SO5-2-u2-X38"},{"t":"장터에서 돈을 던지는 사람들","mis":"SO5-2-u2-X38"}],"explanation":["유교 예절이에요.","제사는 관혼상제예요.","알맞은 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#5','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',3,'ox','auto','역사 만화의 말풍선 대사는 내가 지어도 되지만 그 시대 사람들이 할 만한 내용이어야 해요.',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"ox","stem":"역사 만화의 말풍선 대사는 내가 지어도 되지만 그 시대 사람들이 할 만한 내용이어야 해요.","answer":"O","reason_options":[{"t":"표현은 상상할 수 있어도 내용은 그 시대의 사실과 생활에 맞아야 하기 때문에","correct":true},{"t":"대사는 오늘날 유행어로만 써야 하기 때문에","mis":"SO5-2-u2-X38"}],"mis":"SO5-2-u2-X38","explanation":["대사는 지을 수 있어요.","그 시대에 맞아야 해요.","사실을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#6','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',3,'error','auto','「조선의 발전」 만화 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SO5-2-u2-X13','SO5-2-u2-X14','SO5-2-u2-X15']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"error","stem":"「조선의 발전」 만화 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"은솔 — 「세종이 앙부일구로 비의 양을 재는 장면을 그리자.」","correct":true,"mis_target":"SO5-2-u2-X13"},{"t":"현우 — 「한양 거리에서 백성이 앙부일구로 시각을 보는 장면을 그리자.」","mis":"SO5-2-u2-X14"},{"t":"소이 — 「백성이 훈민정음으로 편지를 쓰는 장면을 그리자.」","mis":"SO5-2-u2-X15"}],"explanation":["비의 양은 측우기예요.","앙부일구는 시각이에요.","은솔의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#7','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',3,'mc','auto','「조선 후기의 경제적 변화」를 네 칸 만화로 그릴 때 차례로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"mc","stem":"「조선 후기의 경제적 변화」를 네 칸 만화로 그릴 때 차례로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모내기하는 농부 → 늘어난 곡식 → 장시에서 파는 모습 → 상평통보로 값을 치르는 모습","correct":true},{"t":"상평통보 → 고인돌 → 모내기 → 전차","mis":"SO5-2-u2-X39"},{"t":"전차 → 모내기 → 신문 → 장시","mis":"SO5-2-u2-X39"},{"t":"측우기 → 남한산성 → 탈놀이 → 상평통보","mis":"SO5-2-u2-X39"}],"explanation":["농사가 바뀌어요.","곡식을 팔아요.","돈으로 값을 치러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#8','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',4,'mc','auto','「달라진 옷차림, 달라진 생각」이라는 제목이 잘 어울리는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X40','SO5-2-u2-X39','SO5-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C21","difficulty":4,"kind":"mc","stem":"「달라진 옷차림, 달라진 생각」이라는 제목이 잘 어울리는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"개항 이후 겉모습뿐 아니라 사람들의 생각도 달라진 것을 한 줄로 담았기 때문에","correct":true},{"t":"옷 이름을 외우기 쉽게 해서","mis":"SO5-2-u2-X40"},{"t":"조선 전기의 모습을 담아서","mis":"SO5-2-u2-X39"},{"t":"주제와 상관없이 재미있어서","mis":"SO5-2-u2-X38"}],"explanation":["옷차림이 달라졌어요.","생각도 달라졌어요.","둘을 함께 담았어요."],"asset":{"type":"passage","lines":["㉮ 주제 — 「부자 상민, 양반을 꿈꾸다」(조선 후기 신분 변화)","㉯ 주제 — 「서당 가는 날」(유교 교육)","㉰ 칸 그림 — 세종 때 장터에서 상평통보로 떡을 사는 아이","㉱ 제목 — 「달라진 옷차림, 달라진 생각」(개항 이후)"],"title":"우리 반 역사 만화 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#9','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',4,'mc','auto','역사 만화를 그리는 활동의 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X38','SO5-2-u2-X40','SO5-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C21","difficulty":4,"kind":"mc","stem":"역사 만화를 그리는 활동의 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공부한 사실을 골라 정리하고 그때 사람들의 생각을 상상하며 재미있게 전할 수 있다","correct":true},{"t":"사실을 몰라도 그릴 수 있다","mis":"SO5-2-u2-X38"},{"t":"인물 이름과 연도만 외우게 된다","mis":"SO5-2-u2-X40"},{"t":"다른 시대 물건을 섞는 연습을 한다","mis":"SO5-2-u2-X39"}],"explanation":["사실을 골라요.","생각을 상상해요.","재미있게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_L09_challenge#10','soc',5,2,'u2','L09','g5_2_soc_u2_L09_challenge','lesson_challenge','SO5-2-u2-C21',4,'essay','teacher','이 단원에서 공부한 생활 모습 가운데 하나를 골라 역사 만화의 주제와 제목, 네 칸의 내용을 한 줄씩 쓰고, 그 내용이 사실에 맞는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u2-C21","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 생활 모습 가운데 하나를 골라 역사 만화의 주제와 제목, 네 칸의 내용을 한 줄씩 쓰고, 그 내용이 사실에 맞는 까닭을 쓰세요.","answer_guide":{"answer":"예: 주제 — 서민 문화에 나타난 생활 모습. 제목 — 「장터의 이야기꾼」. ① 장터에 사람들이 모인다. ② 전기수가 한글 소설을 실감 나게 읽는다. ③ 가장 궁금한 대목에서 멈추자 사람들이 돈을 던진다. ④ 글을 모르는 할머니도 웃으며 이야기를 즐긴다. 조선 후기 살림에 여유가 생긴 서민들이 한글 소설을 즐겼고 전기수가 있었다는 사실에 맞다.","scoring_points":["주제와 제목을 썼는가","네 칸의 내용을 썼는가","사실에 맞는 까닭을 썼는가"]},"explanation":["주제와 제목을 정해요.","네 칸을 써요.","사실에 맞는지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#1','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C1',1,'mc','auto','한결이네 이야기 ①의 「새 나라」를 세운 사람은 누구인가요?',ARRAY['SO5-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C1","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ①의 「새 나라」를 세운 사람은 누구인가요?","options":[{"t":"이성계","correct":true},{"t":"왕건","mis":"SO5-2-u2-X01"},{"t":"세종","mis":"SO5-2-u2-X01"},{"t":"대조영","mis":"SO5-2-u2-X01"}],"explanation":["한양이 수도예요.","조선이에요.","이성계가 세웠어요."],"asset":{"type":"passage","lines":["① 새 나라가 서고 한양이 수도가 되던 무렵, 조상 할아버지는 마을 서당 훈장이었다.","아이들에게 부모께 효도하고 웃어른을 공경하라고 가르쳤다.","한양에 다녀와서는 「숭례문 이름에 예절이 담겼더라」고 일기에 썼다."],"title":"한결이네 집안 이야기 책 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#2','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C4',1,'mc','auto','한결이네 이야기 ②의 「그림이 많은 책」은 어느 것인가요?',ARRAY['SO5-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C4","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ②의 「그림이 많은 책」은 어느 것인가요?","options":[{"t":"『삼강행실도』","correct":true},{"t":"『경국대전』","mis":"SO5-2-u2-X06"},{"t":"『농사직설』","mis":"SO5-2-u2-X06"},{"t":"신문","mis":"SO5-2-u2-X06"}],"explanation":["효자 이야기예요.","그림이 많아요.","『삼강행실도』예요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#3','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C7',1,'mc','auto','한결이네 이야기 ③의 「솥 모양 해시계」는 무엇인가요?',ARRAY['SO5-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ③의 「솥 모양 해시계」는 무엇인가요?","options":[{"t":"앙부일구","correct":true},{"t":"측우기","mis":"SO5-2-u2-X13"},{"t":"자격루","mis":"SO5-2-u2-X13"},{"t":"혼천의","mis":"SO5-2-u2-X13"}],"explanation":["솥 모양이에요.","그림자로 시각을 알아요.","앙부일구예요."],"asset":{"type":"passage","lines":["③ 한양 거리의 솥 모양 해시계 앞에서 일꾼이 그림을 보고 시각을 알았다.","집안 어른은 우리 땅에 맞는 농사책대로 씨를 뿌렸다.","어머니는 새로 생긴 우리 글자로 처음 편지를 쓰셨다."],"title":"한결이네 집안 이야기 책 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#4','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C10',1,'mc','auto','한결이네 이야기 ④에서 「바다 건너 적이 쳐들어온」 전쟁은 어느 것인가요?',ARRAY['SO5-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C10","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ④에서 「바다 건너 적이 쳐들어온」 전쟁은 어느 것인가요?","options":[{"t":"임진왜란","correct":true},{"t":"병자호란","mis":"SO5-2-u2-X19"},{"t":"몽골의 침입","mis":"SO5-2-u2-X19"},{"t":"개항","mis":"SO5-2-u2-X19"}],"explanation":["바다 건너 일본이에요.","스스로 군대를 꾸렸어요.","임진왜란이에요."],"asset":{"type":"passage","lines":["④ 바다 건너 적이 쳐들어오자 집안 어른들이 마을 사람과 스스로 군대를 꾸렸다.","몇십 년 뒤 북쪽 나라가 쳐들어와 임금이 산성으로 피하셨다는 소식을 들었다.","전쟁이 끝나자 논밭이 거칠어져 먹고사는 일이 가장 급했다."],"title":"한결이네 집안 이야기 책 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#5','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C12',1,'mc','auto','한결이네 이야기 ⑤에서 「어린 모를 옮겨 심는」 농사법은 무엇인가요?',ARRAY['SO5-2-u2-X21']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C12","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑤에서 「어린 모를 옮겨 심는」 농사법은 무엇인가요?","options":[{"t":"모내기법","correct":true},{"t":"『농사직설』","mis":"SO5-2-u2-X21"},{"t":"측우기","mis":"SO5-2-u2-X21"},{"t":"관혼상제","mis":"SO5-2-u2-X21"}],"explanation":["모를 키워요.","옮겨 심어요.","모내기법이에요."],"asset":{"type":"passage","lines":["⑤ 어린 모를 옮겨 심자 일손이 줄고 벼를 거둔 논에 보리도 심었다.","거친 밭에는 고구마를 심어 배고픈 겨울을 넘겼다.","인삼을 길러 닷새마다 서는 장에 내다 팔고 쇠돈을 받았다."],"title":"한결이네 집안 이야기 책 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#6','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C14',1,'mc','auto','한결이네 이야기 ⑥에서 이웃이 족보를 산 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C14","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑥에서 이웃이 족보를 산 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"양반이 되려고","correct":true},{"t":"천민이 되려고","mis":"SO5-2-u2-X24"},{"t":"세금을 더 내려고","mis":"SO5-2-u2-X24"},{"t":"과거를 없애려고","mis":"SO5-2-u2-X24"}],"explanation":["부자가 되었어요.","족보를 샀어요.","양반이 되려 했어요."],"asset":{"type":"passage","lines":["⑥ 장사로 부자가 된 이웃이 돈을 주고 양반 족보를 샀다.","중국에 다녀온 친척이 둥근 세계 지도를 보여 주어 모두 놀랐다.","머슴 돌쇠는 「사람이 곧 하늘」이라는 가르침을 몰래 따랐다."],"title":"한결이네 집안 이야기 책 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#7','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C17',1,'mc','auto','한결이네 이야기 ⑦의 「이야기꾼」을 무엇이라고 부르나요?',ARRAY['SO5-2-u2-X30']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C17","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑦의 「이야기꾼」을 무엇이라고 부르나요?","options":[{"t":"전기수","correct":true},{"t":"보부상","mis":"SO5-2-u2-X30"},{"t":"소리꾼","mis":"SO5-2-u2-X30"},{"t":"훈장","mis":"SO5-2-u2-X30"}],"explanation":["한글 소설을 읽었어요.","돈을 받았어요.","전기수예요."],"asset":{"type":"passage","lines":["⑦ 장터에서 이야기꾼이 한글 소설을 읽다 멈추자 사람들이 돈을 던졌다.","마당에서는 탈 쓴 광대가 양반을 흉내 내어 모두 배를 잡고 웃었다.","할머니는 호랑이와 까치 그림을 사서 방에 걸어 두셨다."],"title":"한결이네 집안 이야기 책 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#8','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C19',1,'mc','auto','한결이네 이야기 ⑧의 「항구가 열린」 일을 무엇이라고 하나요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C19","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑧의 「항구가 열린」 일을 무엇이라고 하나요?","options":[{"t":"개항","correct":true},{"t":"통일","mis":"SO5-2-u2-X33"},{"t":"건국","mis":"SO5-2-u2-X33"},{"t":"정착","mis":"SO5-2-u2-X33"}],"explanation":["항구를 열었어요.","외국과 오갔어요.","개항이에요."],"asset":{"type":"passage","lines":["⑧ 항구가 열린 뒤 큰아버지는 양복을 입고 한복 입은 친구와 다녔다.","한결이 증조할아버지는 전차를 타고 소학교에 다니셨다.","집에서는 신문을 받아 보며 나라 밖 소식과 물건 광고를 읽었다."],"title":"한결이네 집안 이야기 책 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#9','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C2',2,'mc','auto','한결이네 이야기 ①에서 숭례문 이름에 담긴 덕목은 어느 것인가요?',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ①에서 숭례문 이름에 담긴 덕목은 어느 것인가요?","options":[{"t":"예(예절)","correct":true},{"t":"인(어진 마음)","mis":"SO5-2-u2-X03"},{"t":"의(옳은 마음)","mis":"SO5-2-u2-X03"},{"t":"신(믿음)","mis":"SO5-2-u2-X03"}],"explanation":["숭례문이에요.","「례」가 들어가요.","예절이에요."],"asset":{"type":"passage","lines":["① 새 나라가 서고 한양이 수도가 되던 무렵, 조상 할아버지는 마을 서당 훈장이었다.","아이들에게 부모께 효도하고 웃어른을 공경하라고 가르쳤다.","한양에 다녀와서는 「숭례문 이름에 예절이 담겼더라」고 일기에 썼다."],"title":"한결이네 집안 이야기 책 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#10','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C5',2,'mc','auto','한결이네 이야기 ②에서 혼례와 제사를 유교 예절대로 치른 것과 관계있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C5","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ②에서 혼례와 제사를 유교 예절대로 치른 것과 관계있는 것은 어느 것인가요?","options":[{"t":"관혼상제","correct":true},{"t":"과거제","mis":"SO5-2-u2-X08"},{"t":"통상","mis":"SO5-2-u2-X08"},{"t":"실학","mis":"SO5-2-u2-X08"}],"explanation":["혼례와 제사예요.","집안 행사예요.","관혼상제예요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#11','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C6',2,'mc','auto','한결이네 이야기 ②에서 누이가 오라비와 똑같이 재산을 받은 것은 조선의 어느 무렵 모습인가요?',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ②에서 누이가 오라비와 똑같이 재산을 받은 것은 조선의 어느 무렵 모습인가요?","options":[{"t":"조선 전기","correct":true},{"t":"조선 후기","mis":"SO5-2-u2-X11"},{"t":"개항 이후","mis":"SO5-2-u2-X11"},{"t":"고조선","mis":"SO5-2-u2-X11"}],"explanation":["똑같이 받았어요.","고려의 풍습이 남았어요.","조선 전기예요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#12','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C9',2,'mc','auto','조선이 사신을 보내 필요한 문물을 받아들인 나라는 어디인가요?',ARRAY['SO5-2-u2-X16']::text[],false,'{"seq":12,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"mc","stem":"조선이 사신을 보내 필요한 문물을 받아들인 나라는 어디인가요?","options":[{"t":"명","correct":true},{"t":"일본","mis":"SO5-2-u2-X16"},{"t":"여진","mis":"SO5-2-u2-X16"},{"t":"청","mis":"SO5-2-u2-X16"}],"explanation":["좋은 관계였어요.","사신을 보냈어요.","명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#13','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C12',2,'mc','auto','한결이네 이야기 ⑤에서 고구마를 거친 밭에 심은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X22']::text[],false,'{"seq":13,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ⑤에서 고구마를 거친 밭에 심은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"거친 땅에서도 잘 자라 배고픔을 덜 수 있어서","correct":true},{"t":"비싸게 팔기만 하려고","mis":"SO5-2-u2-X22"},{"t":"제사에만 쓰려고","mis":"SO5-2-u2-X22"},{"t":"비가 오지 않게 하려고","mis":"SO5-2-u2-X22"}],"explanation":["거친 땅이에요.","잘 자라요.","배고픔을 덜었어요."],"asset":{"type":"passage","lines":["⑤ 어린 모를 옮겨 심자 일손이 줄고 벼를 거둔 논에 보리도 심었다.","거친 밭에는 고구마를 심어 배고픈 겨울을 넘겼다.","인삼을 길러 닷새마다 서는 장에 내다 팔고 쇠돈을 받았다."],"title":"한결이네 집안 이야기 책 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#14','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C16',2,'mc','auto','처음에 서양 학문의 하나로 들어왔다가 믿음으로 받아들여진 종교는 어느 것인가요?',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":14,"concept":"SO5-2-u2-C16","difficulty":2,"kind":"mc","stem":"처음에 서양 학문의 하나로 들어왔다가 믿음으로 받아들여진 종교는 어느 것인가요?","options":[{"t":"천주교","correct":true},{"t":"동학","mis":"SO5-2-u2-X28"},{"t":"불교","mis":"SO5-2-u2-X28"},{"t":"유교","mis":"SO5-2-u2-X28"}],"explanation":["서양에서 왔어요.","학문으로 들어왔어요.","천주교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#15','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C18',2,'mc','auto','한결이네 이야기 ⑦의 「탈 쓴 광대가 양반을 흉내 낸」 공연은 어느 것인가요?',ARRAY['SO5-2-u2-X32']::text[],false,'{"seq":15,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ⑦의 「탈 쓴 광대가 양반을 흉내 낸」 공연은 어느 것인가요?","options":[{"t":"탈놀이","correct":true},{"t":"판소리","mis":"SO5-2-u2-X32"},{"t":"연등회","mis":"SO5-2-u2-X32"},{"t":"관혼상제","mis":"SO5-2-u2-X32"}],"explanation":["탈을 썼어요.","양반을 흉내 냈어요.","탈놀이예요."],"asset":{"type":"passage","lines":["⑦ 장터에서 이야기꾼이 한글 소설을 읽다 멈추자 사람들이 돈을 던졌다.","마당에서는 탈 쓴 광대가 양반을 흉내 내어 모두 배를 잡고 웃었다.","할머니는 호랑이와 까치 그림을 사서 방에 걸어 두셨다."],"title":"한결이네 집안 이야기 책 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#16','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C20',2,'mc','auto','한결이네 이야기 ⑧에서 신문을 받아 보며 달라진 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":16,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"mc","stem":"한결이네 이야기 ⑧에서 신문을 받아 보며 달라진 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"나라 안팎의 새 소식과 물건 광고를 알게 되었다","correct":true},{"t":"밤을 밝힐 수 있게 되었다","mis":"SO5-2-u2-X35"},{"t":"먼 길을 빨리 오가게 되었다","mis":"SO5-2-u2-X35"},{"t":"비의 양을 알게 되었다","mis":"SO5-2-u2-X35"}],"explanation":["신문을 받아 봐요.","소식이 실려요.","광고도 있어요."],"asset":{"type":"passage","lines":["⑧ 항구가 열린 뒤 큰아버지는 양복을 입고 한복 입은 친구와 다녔다.","한결이 증조할아버지는 전차를 타고 소학교에 다니셨다.","집에서는 신문을 받아 보며 나라 밖 소식과 물건 광고를 읽었다."],"title":"한결이네 집안 이야기 책 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#17','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C3',3,'mc','auto','한결이네 이야기 ①·②를 함께 볼 때 유교가 조선 사람들의 생활에 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X08','SO5-2-u2-X05','SO5-2-u2-X02']::text[],false,'{"seq":17,"concept":"SO5-2-u2-C3","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ①·②를 함께 볼 때 유교가 조선 사람들의 생활에 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서당 교육과 집안 행사까지 효도·공경·예절을 따르는 생활이 자리 잡았다","correct":true},{"t":"유교는 나라 행사에만 쓰였다","mis":"SO5-2-u2-X08"},{"t":"유교 때문에 아이들이 공부를 그만두었다","mis":"SO5-2-u2-X05"},{"t":"유교는 불교 행사를 늘렸다","mis":"SO5-2-u2-X02"}],"explanation":["서당에서 효도를 가르쳤어요.","혼례·제사도 유교였어요.","생활 전체에 퍼졌어요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#18','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C7',3,'mc','auto','한결이네 이야기 ③에서 일꾼이 해시계로 시각을 알 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X14','SO5-2-u2-X13']::text[],false,'{"seq":18,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ③에서 일꾼이 해시계로 시각을 알 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그림을 새기고 거리에 두어 글을 몰라도 누구나 볼 수 있었기 때문에","correct":true},{"t":"일꾼이 한자를 잘 읽었기 때문에","mis":"SO5-2-u2-X14"},{"t":"해시계가 집집마다 있었기 때문에","mis":"SO5-2-u2-X14"},{"t":"해시계가 종을 쳤기 때문에","mis":"SO5-2-u2-X13"}],"explanation":["거리에 있었어요.","그림이 있었어요.","누구나 봤어요."],"asset":{"type":"passage","lines":["③ 한양 거리의 솥 모양 해시계 앞에서 일꾼이 그림을 보고 시각을 알았다.","집안 어른은 우리 땅에 맞는 농사책대로 씨를 뿌렸다.","어머니는 새로 생긴 우리 글자로 처음 편지를 쓰셨다."],"title":"한결이네 집안 이야기 책 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#19','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C12',3,'mc','auto','한결이네 이야기 ④의 끝 문장과 ⑤를 이어 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X21']::text[],false,'{"seq":19,"concept":"SO5-2-u2-C12","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ④의 끝 문장과 ⑤를 이어 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁으로 거칠어진 땅에서 먹고살려고 새 농사법과 새 작물을 받아들였다","correct":true},{"t":"전쟁 뒤 농사를 그만두었다","mis":"SO5-2-u2-X21"},{"t":"전쟁으로 땅이 기름져 농사가 쉬워졌다","mis":"SO5-2-u2-X21"},{"t":"전쟁과 농사는 관계가 없었다","mis":"SO5-2-u2-X21"}],"explanation":["땅이 거칠어졌어요.","먹고살아야 했어요.","농사가 바뀌었어요."],"asset":{"type":"passage","lines":["⑤ 어린 모를 옮겨 심자 일손이 줄고 벼를 거둔 논에 보리도 심었다.","거친 밭에는 고구마를 심어 배고픈 겨울을 넘겼다.","인삼을 길러 닷새마다 서는 장에 내다 팔고 쇠돈을 받았다."],"title":"한결이네 집안 이야기 책 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#20','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C14',3,'mc','auto','한결이네 이야기 ⑤·⑥을 이어 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":20,"concept":"SO5-2-u2-C14","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ⑤·⑥을 이어 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"농업과 상업으로 부자가 된 사람이 늘어 돈으로 양반이 되며 신분제가 흔들렸다","correct":true},{"t":"부자가 줄어 모두 천민이 되었다","mis":"SO5-2-u2-X24"},{"t":"돈과 신분은 관계가 없었다","mis":"SO5-2-u2-X24"},{"t":"양반이 모두 장사꾼이 되었다","mis":"SO5-2-u2-X24"}],"explanation":["부자가 늘었어요.","양반을 샀어요.","신분제가 흔들렸어요."],"asset":{"type":"passage","lines":["⑥ 장사로 부자가 된 이웃이 돈을 주고 양반 족보를 샀다.","중국에 다녀온 친척이 둥근 세계 지도를 보여 주어 모두 놀랐다.","머슴 돌쇠는 「사람이 곧 하늘」이라는 가르침을 몰래 따랐다."],"title":"한결이네 집안 이야기 책 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#21','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C20',3,'mc','auto','한결이네 이야기 ⑧에서 큰아버지가 양복을 입고 한복 입은 친구와 다닌 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u2-X37','SO5-2-u2-X39']::text[],false,'{"seq":21,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ⑧에서 큰아버지가 양복을 입고 한복 입은 친구와 다닌 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"새 문물이 들어와도 옛 생활과 새 생활이 함께 있었다","correct":true},{"t":"모두가 하루아침에 양복만 입었다","mis":"SO5-2-u2-X37"},{"t":"양복은 법으로 금지되었다","mis":"SO5-2-u2-X37"},{"t":"한복은 개항 뒤에 생겼다","mis":"SO5-2-u2-X39"}],"explanation":["양복이 들어왔어요.","한복도 입었어요.","함께 있었어요."],"asset":{"type":"passage","lines":["⑧ 항구가 열린 뒤 큰아버지는 양복을 입고 한복 입은 친구와 다녔다.","한결이 증조할아버지는 전차를 타고 소학교에 다니셨다.","집에서는 신문을 받아 보며 나라 밖 소식과 물건 광고를 읽었다."],"title":"한결이네 집안 이야기 책 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#22','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C21',3,'mc','auto','한결이네 이야기 가운데 하나로 역사 만화를 그릴 때 사실과 어긋나는 장면은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":22,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"mc","stem":"한결이네 이야기 가운데 하나로 역사 만화를 그릴 때 사실과 어긋나는 장면은 어느 것인가요?","options":[{"t":"조상 할아버지가 서당에서 전등을 켜고 신문을 읽는 장면","correct":true},{"t":"어머니가 우리 글자로 편지를 쓰는 장면","mis":"SO5-2-u2-X38"},{"t":"장터에서 전기수에게 돈을 던지는 장면","mis":"SO5-2-u2-X38"},{"t":"증조할아버지가 전차를 타는 장면","mis":"SO5-2-u2-X38"}],"explanation":["서당 훈장은 조선 초예요.","전등·신문은 개항 뒤예요.","시대가 섞였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#23','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C3',4,'mc','auto','「달라지는 시대, 변화하는 생활 모습」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u2-X40','SO5-2-u2-X02']::text[],false,'{"seq":23,"concept":"SO5-2-u2-C3","difficulty":4,"kind":"mc","stem":"「달라지는 시대, 변화하는 생활 모습」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"유교로 세운 조선은 유교 질서에 따라 살다가, 조선 후기 경제·사회·문화가 달라지고 개항 뒤 근대 문물로 생활과 생각이 바뀌었다","correct":true},{"t":"조선은 처음부터 끝까지 생활이 같았다","mis":"SO5-2-u2-X40"},{"t":"조선은 불교로 세워져 개항 뒤 유교를 받아들였다","mis":"SO5-2-u2-X02"},{"t":"왕 이름과 연도만 외우면 조선 생활을 다 안다","mis":"SO5-2-u2-X40"}],"explanation":["유교로 시작했어요.","후기에 달라졌어요.","개항 뒤 또 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#24','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C3',4,'essay','teacher','한결이네 이야기 ①·②를 보고 유교가 조선 사람들의 생각과 생활에 준 영향을 교육·집안 행사·책 가운데 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u2-C3","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ①·②를 보고 유교가 조선 사람들의 생각과 생활에 준 영향을 교육·집안 행사·책 가운데 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 교육 — 서당 훈장이 아이들에게 효도와 공경을 가르쳐 유교의 가르침이 어릴 때부터 몸에 배었다. 집안 행사 — 혼례와 제사를 유교 예절대로 치러 관혼상제가 생활 속에 자리 잡았다. 책 — 글을 모르는 일꾼도 그림이 많은 『삼강행실도』로 효자 이야기를 익혔다.","scoring_points":["두 가지를 골랐는가","이야기 책을 근거로 들었는가","유교의 영향(효도·예절 등)을 썼는가"]},"explanation":["교육이 있어요.","집안 행사가 있어요.","책도 있어요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_a#25','soc',5,2,'u2','','g5_2_soc_u2_review_a','unit_review','SO5-2-u2-C16',4,'essay','teacher','한결이네 이야기 ⑥을 보고 조선 후기 사회가 달라진 모습을 신분·생각·종교로 나누어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u2-C16","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ⑥을 보고 조선 후기 사회가 달라진 모습을 신분·생각·종교로 나누어 쓰세요.","answer_guide":{"answer":"예: 신분 — 장사로 부자가 된 이웃이 양반 족보를 사서 양반은 늘고 상민은 줄어 신분제가 흔들렸다. 생각 — 둥근 세계 지도를 보고 중국이 세계의 중심이라는 생각이 달라졌다. 종교 — 머슴 돌쇠처럼 「사람이 곧 하늘」이라며 평등을 말한 동학을 따르는 백성이 늘었다.","scoring_points":["신분 변화를 썼는가","생각의 변화를 썼는가","종교의 변화를 썼는가"]},"explanation":["족보를 샀어요.","세계 지도를 봤어요.","동학이 퍼졌어요."],"asset":{"type":"passage","lines":["⑥ 장사로 부자가 된 이웃이 돈을 주고 양반 족보를 샀다.","중국에 다녀온 친척이 둥근 세계 지도를 보여 주어 모두 놀랐다.","머슴 돌쇠는 「사람이 곧 하늘」이라는 가르침을 몰래 따랐다."],"title":"한결이네 집안 이야기 책 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#1','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C3',1,'mc','auto','조선이 나라의 바탕으로 삼은 생각을 고르세요.',ARRAY['SO5-2-u2-X02','SO5-2-u2-X28']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C3","difficulty":1,"kind":"mc","stem":"조선이 나라의 바탕으로 삼은 생각을 고르세요.","options":[{"t":"유교","correct":true},{"t":"불교","mis":"SO5-2-u2-X02"},{"t":"동학","mis":"SO5-2-u2-X28"},{"t":"천주교","mis":"SO5-2-u2-X28"}],"explanation":["효도와 공경을 가르쳤어요.","질서를 중히 여겼어요.","유교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#2','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C6',1,'mc','auto','조선에서 공부하고 과거를 보아 관리가 된 신분은 어느 것인가요?',ARRAY['SO5-2-u2-X10']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C6","difficulty":1,"kind":"mc","stem":"조선에서 공부하고 과거를 보아 관리가 된 신분은 어느 것인가요?","options":[{"t":"양반","correct":true},{"t":"중인","mis":"SO5-2-u2-X10"},{"t":"상민","mis":"SO5-2-u2-X10"},{"t":"천민","mis":"SO5-2-u2-X10"}],"explanation":["과거를 봤어요.","관리가 되었어요.","양반이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#3','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C8',1,'mc','auto','한결이네 이야기 ③에서 어머니가 편지를 쓴 「우리 글자」는 무엇인가요?',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C8","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ③에서 어머니가 편지를 쓴 「우리 글자」는 무엇인가요?","options":[{"t":"훈민정음","correct":true},{"t":"한자","mis":"SO5-2-u2-X15"},{"t":"영어","mis":"SO5-2-u2-X15"},{"t":"상평통보","mis":"SO5-2-u2-X15"}],"explanation":["세종이 만들었어요.","쉽게 쓸 수 있어요.","훈민정음이에요."],"asset":{"type":"passage","lines":["③ 한양 거리의 솥 모양 해시계 앞에서 일꾼이 그림을 보고 시각을 알았다.","집안 어른은 우리 땅에 맞는 농사책대로 씨를 뿌렸다.","어머니는 새로 생긴 우리 글자로 처음 편지를 쓰셨다."],"title":"한결이네 집안 이야기 책 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#4','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C11',1,'mc','auto','병자호란 때 조선에 쳐들어온 나라는 어디인가요?',ARRAY['SO5-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C11","difficulty":1,"kind":"mc","stem":"병자호란 때 조선에 쳐들어온 나라는 어디인가요?","options":[{"t":"청","correct":true},{"t":"일본","mis":"SO5-2-u2-X19"},{"t":"명","mis":"SO5-2-u2-X19"},{"t":"송","mis":"SO5-2-u2-X19"}],"explanation":["여진이 세운 나라예요.","북쪽에서 왔어요.","청이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#5','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C13',1,'mc','auto','한결이네 이야기 ⑤의 「쇠돈」은 무엇인가요?',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C13","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑤의 「쇠돈」은 무엇인가요?","options":[{"t":"상평통보","correct":true},{"t":"덩이쇠","mis":"SO5-2-u2-X23"},{"t":"홍패","mis":"SO5-2-u2-X23"},{"t":"족보","mis":"SO5-2-u2-X23"}],"explanation":["조선 후기 돈이에요.","전국에서 썼어요.","상평통보예요."],"asset":{"type":"passage","lines":["⑤ 어린 모를 옮겨 심자 일손이 줄고 벼를 거둔 논에 보리도 심었다.","거친 밭에는 고구마를 심어 배고픈 겨울을 넘겼다.","인삼을 길러 닷새마다 서는 장에 내다 팔고 쇠돈을 받았다."],"title":"한결이네 집안 이야기 책 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#6','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C16',1,'mc','auto','한결이네 이야기 ⑥의 「사람이 곧 하늘」이라는 가르침을 편 종교는 어느 것인가요?',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C16","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑥의 「사람이 곧 하늘」이라는 가르침을 편 종교는 어느 것인가요?","options":[{"t":"동학","correct":true},{"t":"천주교","mis":"SO5-2-u2-X28"},{"t":"불교","mis":"SO5-2-u2-X28"},{"t":"유교","mis":"SO5-2-u2-X28"}],"explanation":["우리 것을 지키자고 했어요.","평등을 말했어요.","동학이에요."],"asset":{"type":"passage","lines":["⑥ 장사로 부자가 된 이웃이 돈을 주고 양반 족보를 샀다.","중국에 다녀온 친척이 둥근 세계 지도를 보여 주어 모두 놀랐다.","머슴 돌쇠는 「사람이 곧 하늘」이라는 가르침을 몰래 따랐다."],"title":"한결이네 집안 이야기 책 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#7','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C18',1,'mc','auto','한결이네 이야기 ⑦에서 할머니가 산 그림은 어느 것인가요?',ARRAY['SO5-2-u2-X31']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C18","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑦에서 할머니가 산 그림은 어느 것인가요?","options":[{"t":"민화","correct":true},{"t":"풍속화","mis":"SO5-2-u2-X31"},{"t":"고려청자","mis":"SO5-2-u2-X31"},{"t":"세계 지도","mis":"SO5-2-u2-X31"}],"explanation":["호랑이와 까치예요.","방에 걸었어요.","민화예요."],"asset":{"type":"passage","lines":["⑦ 장터에서 이야기꾼이 한글 소설을 읽다 멈추자 사람들이 돈을 던졌다.","마당에서는 탈 쓴 광대가 양반을 흉내 내어 모두 배를 잡고 웃었다.","할머니는 호랑이와 까치 그림을 사서 방에 걸어 두셨다."],"title":"한결이네 집안 이야기 책 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#8','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C20',1,'mc','auto','한결이네 이야기 ⑧에서 증조할아버지가 다닌, 오늘날 초등학교에 해당하는 학교는 어느 것인가요?',ARRAY['SO5-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C20","difficulty":1,"kind":"mc","stem":"한결이네 이야기 ⑧에서 증조할아버지가 다닌, 오늘날 초등학교에 해당하는 학교는 어느 것인가요?","options":[{"t":"소학교","correct":true},{"t":"성균관","mis":"SO5-2-u2-X39"},{"t":"서당","mis":"SO5-2-u2-X39"},{"t":"향교","mis":"SO5-2-u2-X39"}],"explanation":["개항 뒤 세워졌어요.","초등학교 같아요.","소학교예요."],"asset":{"type":"passage","lines":["⑧ 항구가 열린 뒤 큰아버지는 양복을 입고 한복 입은 친구와 다녔다.","한결이 증조할아버지는 전차를 타고 소학교에 다니셨다.","집에서는 신문을 받아 보며 나라 밖 소식과 물건 광고를 읽었다."],"title":"한결이네 집안 이야기 책 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#9','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C2',2,'mc','auto','한양의 문과 건물에 유교 덕목을 담은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X03','SO5-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"mc","stem":"한양의 문과 건물에 유교 덕목을 담은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"백성에게 유교의 가르침을 널리 알리려고","correct":true},{"t":"외적을 막으려고","mis":"SO5-2-u2-X03"},{"t":"이름을 아름답게만 하려고","mis":"SO5-2-u2-X03"},{"t":"불교를 알리려고","mis":"SO5-2-u2-X02"}],"explanation":["날마다 지나가요.","이름을 보고 익혀요.","가르침을 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
