INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#11','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C6',2,'mc','auto','조선 후기로 갈수록 여성의 생활이 어떻게 달라졌나요?',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"mc","stem":"조선 후기로 갈수록 여성의 생활이 어떻게 달라졌나요?","options":[{"t":"아버지·남편·아들의 뜻을 따르게 되며 지위가 낮아졌다","correct":true},{"t":"관리가 되어 나라 일을 했다","mis":"SO5-2-u2-X11"},{"t":"재산을 모두 차지했다","mis":"SO5-2-u2-X11"},{"t":"달라진 것이 없었다","mis":"SO5-2-u2-X11"}],"explanation":["유교 질서가 깊어졌어요.","삼종지도예요.","지위가 낮아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
