INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#15','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C18',2,'mc','auto','백성의 생활 모습을 있는 그대로 그린 그림은 어느 것인가요?',ARRAY['SO5-2-u2-X31']::text[],false,'{"seq":15,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"mc","stem":"백성의 생활 모습을 있는 그대로 그린 그림은 어느 것인가요?","options":[{"t":"풍속화","correct":true},{"t":"민화","mis":"SO5-2-u2-X31"},{"t":"세계 지도","mis":"SO5-2-u2-X31"},{"t":"족보","mis":"SO5-2-u2-X31"}],"explanation":["생활 장면이에요.","씨름·서당 같은 장면이에요.","풍속화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#16','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C20',2,'mc','auto','전차를 놓으면서 달라진 거리의 모습은 어느 것인가요?',ARRAY['SO5-2-u2-X35','SO5-2-u2-X39']::text[],false,'{"seq":16,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"mc","stem":"전차를 놓으면서 달라진 거리의 모습은 어느 것인가요?","options":[{"t":"길이 넓어지고 전봇대가 세워졌다","correct":true},{"t":"장시가 모두 사라졌다","mis":"SO5-2-u2-X35"},{"t":"성벽이 새로 생겼다","mis":"SO5-2-u2-X35"},{"t":"거리에 해시계가 놓였다","mis":"SO5-2-u2-X39"}],"explanation":["전차는 커요.","길을 넓혔어요.","전봇대를 세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#17','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C4',3,'mc','auto','한결이네 이야기 ②에서 글을 모르는 일꾼들도 효자 이야기를 익힐 수 있었던 까닭은 어느 것인가요?',ARRAY['SO5-2-u2-X07','SO5-2-u2-X06','SO5-2-u2-X39']::text[],false,'{"seq":17,"concept":"SO5-2-u2-C4","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ②에서 글을 모르는 일꾼들도 효자 이야기를 익힐 수 있었던 까닭은 어느 것인가요?","options":[{"t":"나라가 그림을 넣은 책을 펴내 누구나 알 수 있게 했기 때문에","correct":true},{"t":"일꾼들이 모두 한자를 잘 읽었기 때문에","mis":"SO5-2-u2-X07"},{"t":"책에 법만 적혀 있었기 때문에","mis":"SO5-2-u2-X06"},{"t":"신문에 실렸기 때문에","mis":"SO5-2-u2-X39"}],"explanation":["글을 몰랐어요.","그림이 있었어요.","누구나 익혔어요."],"asset":{"type":"passage","lines":["② 집안의 혼례와 제사는 모두 유교 예절대로 치렀다.","글을 모르는 일꾼들은 그림이 많은 책으로 효자 이야기를 익혔다.","이때 누이도 오라비와 똑같이 재산을 나누어 받았다."],"title":"한결이네 집안 이야기 책 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#18','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C8',3,'mc','auto','한결이네 이야기 ③에서 어머니가 처음 편지를 쓸 수 있었던 까닭과 이어지는 세종의 뜻은 어느 것인가요?',ARRAY['SO5-2-u2-X15']::text[],false,'{"seq":18,"concept":"SO5-2-u2-C8","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ③에서 어머니가 처음 편지를 쓸 수 있었던 까닭과 이어지는 세종의 뜻은 어느 것인가요?","options":[{"t":"백성이 쉽게 읽고 쓰게 하려는 뜻","correct":true},{"t":"양반만 글을 쓰게 하려는 뜻","mis":"SO5-2-u2-X15"},{"t":"한자를 더 어렵게 하려는 뜻","mis":"SO5-2-u2-X15"},{"t":"서양 글자를 따라 하려는 뜻","mis":"SO5-2-u2-X15"}],"explanation":["새 글자가 생겼어요.","배우기 쉬웠어요.","백성을 위했어요."],"asset":{"type":"passage","lines":["③ 한양 거리의 솥 모양 해시계 앞에서 일꾼이 그림을 보고 시각을 알았다.","집안 어른은 우리 땅에 맞는 농사책대로 씨를 뿌렸다.","어머니는 새로 생긴 우리 글자로 처음 편지를 쓰셨다."],"title":"한결이네 집안 이야기 책 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#19','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C10',3,'mc','auto','한결이네 이야기 ④에서 집안 어른들이 스스로 군대를 꾸린 마음과 이어지는 유교 정신은 어느 것인가요?',ARRAY['SO5-2-u2-X18']::text[],false,'{"seq":19,"concept":"SO5-2-u2-C10","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ④에서 집안 어른들이 스스로 군대를 꾸린 마음과 이어지는 유교 정신은 어느 것인가요?","options":[{"t":"나라와 임금에 대한 충성","correct":true},{"t":"장사로 돈을 벌려는 마음","mis":"SO5-2-u2-X18"},{"t":"서양 문물을 좋아하는 마음","mis":"SO5-2-u2-X18"},{"t":"신분을 사려는 마음","mis":"SO5-2-u2-X18"}],"explanation":["스스로 나섰어요.","나라를 지키려 했어요.","충성이에요."],"asset":{"type":"passage","lines":["④ 바다 건너 적이 쳐들어오자 집안 어른들이 마을 사람과 스스로 군대를 꾸렸다.","몇십 년 뒤 북쪽 나라가 쳐들어와 임금이 산성으로 피하셨다는 소식을 들었다.","전쟁이 끝나자 논밭이 거칠어져 먹고사는 일이 가장 급했다."],"title":"한결이네 집안 이야기 책 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#20','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C17',3,'mc','auto','한결이네 이야기 ⑤와 ⑦을 이어 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X29','SO5-2-u2-X39']::text[],false,'{"seq":20,"concept":"SO5-2-u2-C17","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ⑤와 ⑦을 이어 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"살림에 여유가 생긴 서민들이 돈을 내고 문화와 예술을 즐겼다","correct":true},{"t":"서민은 여유가 없어 문화를 즐기지 못했다","mis":"SO5-2-u2-X29"},{"t":"서민 문화는 양반만 즐겼다","mis":"SO5-2-u2-X29"},{"t":"서민 문화는 개항 뒤에 생겼다","mis":"SO5-2-u2-X39"}],"explanation":["장사로 돈을 벌었어요.","여유가 생겼어요.","문화를 즐겼어요."],"asset":{"type":"passage","lines":["⑦ 장터에서 이야기꾼이 한글 소설을 읽다 멈추자 사람들이 돈을 던졌다.","마당에서는 탈 쓴 광대가 양반을 흉내 내어 모두 배를 잡고 웃었다.","할머니는 호랑이와 까치 그림을 사서 방에 걸어 두셨다."],"title":"한결이네 집안 이야기 책 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#21','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C20',3,'mc','auto','전차가 자리를 신분이 아니라 낸 돈으로 나누고 남녀가 함께 탄 것이 가져온 변화로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X36']::text[],false,'{"seq":21,"concept":"SO5-2-u2-C20","difficulty":3,"kind":"mc","stem":"전차가 자리를 신분이 아니라 낸 돈으로 나누고 남녀가 함께 탄 것이 가져온 변화로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분과 남녀를 엄격히 구별하던 유교 질서에 대한 생각이 점차 달라졌다","correct":true},{"t":"신분 구별이 더 엄격해졌다","mis":"SO5-2-u2-X36"},{"t":"여성은 집 밖에 나갈 수 없게 되었다","mis":"SO5-2-u2-X36"},{"t":"전차는 양반만 탔다","mis":"SO5-2-u2-X36"}],"explanation":["돈으로 자리를 나눴어요.","남녀가 함께 탔어요.","생각이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#22','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C21',3,'mc','auto','한결이네 이야기 ⑥으로 만화를 그릴 때 가장 어울리는 제목은 어느 것인가요?',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":22,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"mc","stem":"한결이네 이야기 ⑥으로 만화를 그릴 때 가장 어울리는 제목은 어느 것인가요?","options":[{"t":"「족보를 산 이웃, 흔들리는 신분」","correct":true},{"t":"「서당 훈장의 하루」","mis":"SO5-2-u2-X38"},{"t":"「전차 타고 학교 가기」","mis":"SO5-2-u2-X38"},{"t":"「우리 글자로 쓴 첫 편지」","mis":"SO5-2-u2-X38"}],"explanation":["⑥은 족보 이야기예요.","신분이 흔들렸어요.","주제에 맞는 제목이에요."],"asset":{"type":"passage","lines":["⑥ 장사로 부자가 된 이웃이 돈을 주고 양반 족보를 샀다.","중국에 다녀온 친척이 둥근 세계 지도를 보여 주어 모두 놀랐다.","머슴 돌쇠는 「사람이 곧 하늘」이라는 가르침을 몰래 따랐다."],"title":"한결이네 집안 이야기 책 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#23','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C14',4,'mc','auto','한결이네 이야기 ①~⑧을 차례로 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u2-X40','SO5-2-u2-X39']::text[],false,'{"seq":23,"concept":"SO5-2-u2-C14","difficulty":4,"kind":"mc","stem":"한결이네 이야기 ①~⑧을 차례로 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"한 집안의 생활도 나라의 변화에 따라 유교 생활 → 후기의 새 경제·문화 → 근대 생활로 바뀌어 왔다","correct":true},{"t":"한결이네는 몇백 년 동안 똑같이 살았다","mis":"SO5-2-u2-X40"},{"t":"개항 뒤 조선 전기 생활로 돌아갔다","mis":"SO5-2-u2-X39"},{"t":"집안 생활은 나라 변화와 관계없다","mis":"SO5-2-u2-X40"}],"explanation":["①~③은 유교 생활이에요.","⑤~⑦은 후기예요.","⑧은 근대 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#24','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C7',4,'essay','teacher','한결이네 이야기 ③을 보고 세종 때 만든 것 두 가지가 백성의 생활을 어떻게 바꾸었는지 쓰고, 세종이 무엇을 중히 여겼는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u2-C7","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ③을 보고 세종 때 만든 것 두 가지가 백성의 생활을 어떻게 바꾸었는지 쓰고, 세종이 무엇을 중히 여겼는지 쓰세요.","answer_guide":{"answer":"예: 거리의 앙부일구는 그림을 새겨 글을 모르는 일꾼도 시각을 알게 했다. 훈민정음은 어머니처럼 한자를 모르는 사람도 편지를 쓰게 했다. 세종은 백성의 생활을 편하게 하고 안정시키는 것을 중히 여겼다.","scoring_points":["두 가지를 들었는가","바뀐 생활을 썼는가","세종이 중히 여긴 것(백성)을 썼는가"]},"explanation":["앙부일구예요.","훈민정음이에요.","백성을 중히 여겼어요."],"asset":{"type":"passage","lines":["③ 한양 거리의 솥 모양 해시계 앞에서 일꾼이 그림을 보고 시각을 알았다.","집안 어른은 우리 땅에 맞는 농사책대로 씨를 뿌렸다.","어머니는 새로 생긴 우리 글자로 처음 편지를 쓰셨다."],"title":"한결이네 집안 이야기 책 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_b#25','soc',5,2,'u2','','g5_2_soc_u2_review_b','unit_review','SO5-2-u2-C18',4,'essay','teacher','한결이네 이야기 ⑦을 보고 서민 문화 두 가지를 골라 무엇인지 쓰고, 서민 문화가 발달한 까닭과 그 문화에 담긴 서민의 마음을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u2-C18","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ⑦을 보고 서민 문화 두 가지를 골라 무엇인지 쓰고, 서민 문화가 발달한 까닭과 그 문화에 담긴 서민의 마음을 쓰세요.","answer_guide":{"answer":"예: 전기수가 한글 소설을 읽어 준 것과 탈 쓴 광대가 양반을 흉내 낸 탈놀이를 골랐다. 농사와 장사로 살림에 여유가 생긴 서민들이 문화와 예술에 관심을 두었기 때문에 발달했다. 탈놀이에는 신분 차별에 대한 불만과 하고 싶던 말을 시원하게 하고 싶은 마음이 담겼다.","scoring_points":["서민 문화 두 가지를 골랐는가","발달한 까닭을 썼는가","담긴 마음을 썼는가"]},"explanation":["둘을 골라요.","여유가 생겼어요.","마음을 써요."],"asset":{"type":"passage","lines":["⑦ 장터에서 이야기꾼이 한글 소설을 읽다 멈추자 사람들이 돈을 던졌다.","마당에서는 탈 쓴 광대가 양반을 흉내 내어 모두 배를 잡고 웃었다.","할머니는 호랑이와 까치 그림을 사서 방에 걸어 두셨다."],"title":"한결이네 집안 이야기 책 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#1','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C3',1,'sa','auto','조선에서 마을 아이들이 처음 글을 배우던 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u2-C3","difficulty":1,"kind":"sa","stem":"조선에서 마을 아이들이 처음 글을 배우던 곳은 어디인가요? 두 글자로 쓰세요.","answer":["서당"],"explanation":["훈장님이 가르쳤어요.","마을에 있었어요.","서당이에요."],"mis":"SO5-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#2','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C4',1,'sa','auto','유교 중심으로 나라를 다스리려고 만든 조선의 기본 법전을 쓰세요. (경○○○)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u2-C4","difficulty":1,"kind":"sa","stem":"유교 중심으로 나라를 다스리려고 만든 조선의 기본 법전을 쓰세요. (경○○○)","answer":["경국대전","『경국대전』"],"explanation":["법을 모았어요.","나라를 다스려요.","『경국대전』이에요."],"mis":"SO5-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#3','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C7',1,'sa','auto','비가 온 양을 재는 기구를 쓰세요. 세 글자예요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"sa","stem":"비가 온 양을 재는 기구를 쓰세요. 세 글자예요.","answer":["측우기"],"explanation":["비를 받아요.","양을 재요.","측우기예요."],"mis":"SO5-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#4','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C10',1,'sa','auto','임진왜란 때 백성이 스스로 만든 군대를 무엇이라 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO5-2-u2-C10","difficulty":1,"kind":"sa","stem":"임진왜란 때 백성이 스스로 만든 군대를 무엇이라 하나요? 두 글자로 쓰세요.","answer":["의병"],"explanation":["백성이 나섰어요.","스스로 만들었어요.","의병이에요."],"mis":"SO5-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#5','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C13',1,'sa','auto','여러 장시를 돌아다니며 장사한 상인을 쓰세요. 세 글자예요.','{}'::text[],false,'{"seq":5,"concept":"SO5-2-u2-C13","difficulty":1,"kind":"sa","stem":"여러 장시를 돌아다니며 장사한 상인을 쓰세요. 세 글자예요.","answer":["보부상"],"explanation":["짐을 지고 다녔어요.","장마다 갔어요.","보부상이에요."],"mis":"SO5-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#6','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C15',1,'sa','auto','현실의 사회 문제를 풀려는 조선 후기 학문을 쓰세요. 두 글자예요.','{}'::text[],false,'{"seq":6,"concept":"SO5-2-u2-C15","difficulty":1,"kind":"sa","stem":"현실의 사회 문제를 풀려는 조선 후기 학문을 쓰세요. 두 글자예요.","answer":["실학"],"explanation":["백성의 삶을 봤어요.","현실을 풀려 했어요.","실학이에요."],"mis":"SO5-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#7','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C18',1,'sa','auto','소리꾼이 북 장단에 맞추어 노래·말·몸짓으로 이야기를 풀어 가는 공연을 쓰세요. 세 글자예요.','{}'::text[],false,'{"seq":7,"concept":"SO5-2-u2-C18","difficulty":1,"kind":"sa","stem":"소리꾼이 북 장단에 맞추어 노래·말·몸짓으로 이야기를 풀어 가는 공연을 쓰세요. 세 글자예요.","answer":["판소리"],"explanation":["소리꾼이 나와요.","북 장단이 있어요.","판소리예요."],"mis":"SO5-2-u2-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#8','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C19',1,'sa','auto','조선이 일본과 맺어 항구를 연 조약을 쓰세요. (○○○ 조약)','{}'::text[],false,'{"seq":8,"concept":"SO5-2-u2-C19","difficulty":1,"kind":"sa","stem":"조선이 일본과 맺어 항구를 연 조약을 쓰세요. (○○○ 조약)","answer":["강화도 조약","강화도조약"],"explanation":["강화도에서 맺었어요.","불평등 조약이에요.","강화도 조약이에요."],"mis":"SO5-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#9','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C2',2,'ox','auto','흥인지문의 「인」은 어진 마음을 뜻하는 유교 덕목이에요.',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"ox","stem":"흥인지문의 「인」은 어진 마음을 뜻하는 유교 덕목이에요.","answer":"O","reason_options":[{"t":"도성의 동쪽 문에 어진 마음을 담았기 때문에","correct":true},{"t":"「인」은 사람 수를 뜻하기 때문에","mis":"SO5-2-u2-X03"}],"mis":"SO5-2-u2-X03","explanation":["흥인지문이에요.","「인」이 들어 있어요.","어진 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#10','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C5',2,'ox','auto','조선에서는 나라 행사뿐 아니라 집안 행사도 유교 예절을 따랐어요.',ARRAY['SO5-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C5","difficulty":2,"kind":"ox","stem":"조선에서는 나라 행사뿐 아니라 집안 행사도 유교 예절을 따랐어요.","answer":"O","reason_options":[{"t":"나라가 관혼상제를 중히 여겨 백성에게도 따르게 했기 때문에","correct":true},{"t":"집안 행사는 아무렇게나 해도 되었기 때문에","mis":"SO5-2-u2-X08"}],"mis":"SO5-2-u2-X08","explanation":["나라가 중히 여겼어요.","백성도 따랐어요.","집안 행사도 유교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#11','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C6',2,'ox','auto','조선의 여성 지위는 처음부터 끝까지 같았어요.',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"ox","stem":"조선의 여성 지위는 처음부터 끝까지 같았어요.","answer":"X","reason_options":[{"t":"전기에는 고려처럼 재산을 똑같이 받다가 후기로 갈수록 낮아졌기 때문에","correct":true},{"t":"조선 여성은 늘 관리가 될 수 있었기 때문에","mis":"SO5-2-u2-X11"}],"mis":"SO5-2-u2-X11","explanation":["전기는 똑같았어요.","후기는 달라졌어요.","변화가 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#12','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C9',2,'ox','auto','4군과 6진은 여진을 몰아내고 북쪽 영토를 넓히며 둔 것이에요.',ARRAY['SO5-2-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"ox","stem":"4군과 6진은 여진을 몰아내고 북쪽 영토를 넓히며 둔 것이에요.","answer":"O","reason_options":[{"t":"압록강과 두만강 쪽에 군과 진을 두었기 때문에","correct":true},{"t":"4군과 6진은 일본과 맺은 조약이기 때문에","mis":"SO5-2-u2-X17"}],"mis":"SO5-2-u2-X17","explanation":["여진을 몰아냈어요.","북쪽이에요.","영토를 넓혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#13','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C12',2,'ox','auto','모내기법으로 벼를 거둔 논에 보리를 심어 한 번 더 거둘 수 있었어요.',ARRAY['SO5-2-u2-X21']::text[],false,'{"seq":13,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"ox","stem":"모내기법으로 벼를 거둔 논에 보리를 심어 한 번 더 거둘 수 있었어요.","answer":"O","reason_options":[{"t":"벼를 옮겨 심는 시기가 늦어 그 앞뒤로 보리를 기를 수 있었기 때문에","correct":true},{"t":"모내기법을 하면 한 해에 한 번도 못 거두기 때문에","mis":"SO5-2-u2-X21"}],"mis":"SO5-2-u2-X21","explanation":["벼를 거둬요.","보리를 심어요.","두 번 거둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#14','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C16',2,'ox','auto','나라는 동학을 막았지만 동학은 백성 사이에 더욱 퍼졌어요.',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":14,"concept":"SO5-2-u2-C16","difficulty":2,"kind":"ox","stem":"나라는 동학을 막았지만 동학은 백성 사이에 더욱 퍼졌어요.","answer":"O","reason_options":[{"t":"평등한 세상을 바라는 백성이 많았기 때문에","correct":true},{"t":"백성은 동학을 싫어했기 때문에","mis":"SO5-2-u2-X28"}],"mis":"SO5-2-u2-X28","explanation":["나라가 막았어요.","백성이 따랐어요.","더 퍼졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#15','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C18',2,'ox','auto','민화는 주로 생활 공간을 꾸미는 데 쓰였고 서민의 소망이 담겼어요.',ARRAY['SO5-2-u2-X31']::text[],false,'{"seq":15,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"ox","stem":"민화는 주로 생활 공간을 꾸미는 데 쓰였고 서민의 소망이 담겼어요.","answer":"O","reason_options":[{"t":"복과 장수, 성공을 바라는 마음을 그려 방에 두었기 때문에","correct":true},{"t":"민화는 나라의 법을 적은 그림이기 때문에","mis":"SO5-2-u2-X31"}],"mis":"SO5-2-u2-X31","explanation":["방에 걸었어요.","꾸미는 데 썼어요.","소망이 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#16','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C20',2,'ox','auto','개항 이후 서양식 옷과 음식, 건물이 도시를 중심으로 들어왔어요.',ARRAY['SO5-2-u2-X37']::text[],false,'{"seq":16,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"ox","stem":"개항 이후 서양식 옷과 음식, 건물이 도시를 중심으로 들어왔어요.","answer":"O","reason_options":[{"t":"외국 상인과 외교관이 오가며 새 문물이 알려졌기 때문에","correct":true},{"t":"서양 문물은 시골에만 들어왔기 때문에","mis":"SO5-2-u2-X37"}],"mis":"SO5-2-u2-X37","explanation":["외국 사람이 왔어요.","문물이 알려졌어요.","도시부터 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#17','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C3',3,'ox','auto','조선이 성균관·향교를 세우고 『삼강행실도』를 펴낸 것은 모두 유교를 널리 퍼뜨리려는 노력이에요.',ARRAY['SO5-2-u2-X04']::text[],false,'{"seq":17,"concept":"SO5-2-u2-C3","difficulty":3,"kind":"ox","stem":"조선이 성균관·향교를 세우고 『삼강행실도』를 펴낸 것은 모두 유교를 널리 퍼뜨리려는 노력이에요.","answer":"O","reason_options":[{"t":"교육과 책으로 백성이 유교의 가르침을 배우고 실천하게 했기 때문에","correct":true},{"t":"두 가지 모두 불교를 퍼뜨리려는 일이었기 때문에","mis":"SO5-2-u2-X04"}],"mis":"SO5-2-u2-X04","explanation":["교육 기관을 세웠어요.","책을 펴냈어요.","유교를 퍼뜨렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#18','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C7',3,'ox','auto','세종 때 만든 농사책·과학 기구·새 글자는 모두 백성의 생활을 돕는 데 쓰였어요.',ARRAY['SO5-2-u2-X14']::text[],false,'{"seq":18,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"ox","stem":"세종 때 만든 농사책·과학 기구·새 글자는 모두 백성의 생활을 돕는 데 쓰였어요.","answer":"O","reason_options":[{"t":"농사를 돕고 시각을 알리고 글을 쉽게 쓰게 했기 때문에","correct":true},{"t":"모두 임금 혼자만 쓰려고 만들었기 때문에","mis":"SO5-2-u2-X14"}],"mis":"SO5-2-u2-X14","explanation":["농사를 도왔어요.","시각을 알렸어요.","글을 쉽게 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#19','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C11',3,'ox','auto','두 번의 큰 전쟁은 조선 사람들의 삶을 크게 어렵게 만들었어요.',ARRAY['SO5-2-u2-X20']::text[],false,'{"seq":19,"concept":"SO5-2-u2-C11","difficulty":3,"kind":"ox","stem":"두 번의 큰 전쟁은 조선 사람들의 삶을 크게 어렵게 만들었어요.","answer":"O","reason_options":[{"t":"땅이 거칠어지고 많은 백성이 다치거나 끌려갔기 때문에","correct":true},{"t":"전쟁 뒤 백성의 삶이 곧바로 넉넉해졌기 때문에","mis":"SO5-2-u2-X20"}],"mis":"SO5-2-u2-X20","explanation":["땅이 거칠어졌어요.","백성이 끌려갔어요.","삶이 어려워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#20','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C14',3,'ox','auto','돈으로 양반이 된 사람이 늘수록 남은 상민의 세금 부담이 무거워졌어요.',ARRAY['SO5-2-u2-X25']::text[],false,'{"seq":20,"concept":"SO5-2-u2-C14","difficulty":3,"kind":"ox","stem":"돈으로 양반이 된 사람이 늘수록 남은 상민의 세금 부담이 무거워졌어요.","answer":"O","reason_options":[{"t":"세금을 거의 내지 않는 양반이 늘어 세금 낼 사람이 줄었기 때문에","correct":true},{"t":"양반이 늘면 모든 세금이 없어졌기 때문에","mis":"SO5-2-u2-X25"}],"mis":"SO5-2-u2-X25","explanation":["양반은 세금을 거의 안 내요.","상민이 줄어요.","짐이 무거워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#21','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C19',3,'ox','auto','강화도 조약은 외국과 맺은 첫 근대적 조약이지만 조선에 불리한 불평등 조약이었어요.',ARRAY['SO5-2-u2-X34']::text[],false,'{"seq":21,"concept":"SO5-2-u2-C19","difficulty":3,"kind":"ox","stem":"강화도 조약은 외국과 맺은 첫 근대적 조약이지만 조선에 불리한 불평등 조약이었어요.","answer":"O","reason_options":[{"t":"일본이 무력을 앞세워 조선에 불리한 내용으로 맺었기 때문에","correct":true},{"t":"두 나라가 똑같이 이익을 나눈 조약이었기 때문에","mis":"SO5-2-u2-X34"}],"mis":"SO5-2-u2-X34","explanation":["첫 근대적 조약이에요.","무력을 앞세웠어요.","불평등했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#22','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C21',3,'ox','auto','역사 만화의 대사는 지어도 되지만 그 시대에 맞는 내용이어야 해요.',ARRAY['SO5-2-u2-X38']::text[],false,'{"seq":22,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"ox","stem":"역사 만화의 대사는 지어도 되지만 그 시대에 맞는 내용이어야 해요.","answer":"O","reason_options":[{"t":"표현은 상상해도 내용은 사실에 맞아야 하기 때문에","correct":true},{"t":"대사는 오늘날 유행어로만 써야 하기 때문에","mis":"SO5-2-u2-X38"}],"mis":"SO5-2-u2-X38","explanation":["대사는 지어요.","시대에 맞춰요.","사실을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#23','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C20',4,'mc','auto','조선 전기·후기·개항 이후를 차례로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X39']::text[],false,'{"seq":23,"concept":"SO5-2-u2-C20","difficulty":4,"kind":"mc","stem":"조선 전기·후기·개항 이후를 차례로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"앙부일구·훈민정음 → 상평통보·탈놀이 → 전차·신문","correct":true},{"t":"전차·신문 → 앙부일구 → 상평통보","mis":"SO5-2-u2-X39"},{"t":"상평통보 → 훈민정음 → 전차","mis":"SO5-2-u2-X39"},{"t":"탈놀이 → 전차 → 앙부일구","mis":"SO5-2-u2-X39"}],"explanation":["전기는 세종 때예요.","후기는 장시와 서민 문화예요.","개항 뒤는 근대 문물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#24','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C10',4,'essay','teacher','한결이네 이야기 ④를 보고 두 전쟁을 각각 쓰고(쳐들어온 나라와 결과), 전쟁 뒤 백성의 생활이 어떻게 되었는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u2-C10","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ④를 보고 두 전쟁을 각각 쓰고(쳐들어온 나라와 결과), 전쟁 뒤 백성의 생활이 어떻게 되었는지 쓰세요.","answer_guide":{"answer":"예: 임진왜란은 일본이 쳐들어온 전쟁으로, 수군·의병·명군의 힘으로 위기를 이겨 냈다. 병자호란은 청이 쳐들어온 전쟁으로, 임금이 남한산성으로 피했지만 결국 청에 항복했다. 전쟁 뒤 논밭이 거칠어지고 많은 백성이 다치거나 끌려가 먹고사는 일이 가장 급해졌다.","scoring_points":["임진왜란을 바르게 썼는가","병자호란을 바르게 썼는가","전쟁 뒤 생활을 썼는가"]},"explanation":["일본은 임진왜란이에요.","청은 병자호란이에요.","전쟁 뒤 삶이 어려웠어요."],"asset":{"type":"passage","lines":["④ 바다 건너 적이 쳐들어오자 집안 어른들이 마을 사람과 스스로 군대를 꾸렸다.","몇십 년 뒤 북쪽 나라가 쳐들어와 임금이 산성으로 피하셨다는 소식을 들었다.","전쟁이 끝나자 논밭이 거칠어져 먹고사는 일이 가장 급했다."],"title":"한결이네 집안 이야기 책 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_c#25','soc',5,2,'u2','','g5_2_soc_u2_review_c','unit_review','SO5-2-u2-C20',4,'essay','teacher','한결이네 이야기 ⑧을 보고 개항 이후 달라진 생활을 세 가지 쓰고, 그 가운데 하나가 사람들의 생각을 어떻게 바꾸었는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u2-C20","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ⑧을 보고 개항 이후 달라진 생활을 세 가지 쓰고, 그 가운데 하나가 사람들의 생각을 어떻게 바꾸었는지 쓰세요.","answer_guide":{"answer":"예: 큰아버지는 양복을 입었고, 증조할아버지는 전차를 타고 소학교에 다녔으며, 집에서는 신문으로 나라 밖 소식과 물건 광고를 읽었다. 전차는 자리를 신분이 아니라 낸 돈으로 나누고 남녀가 함께 타서, 신분과 남녀를 엄격히 나누던 유교 질서에 대한 생각을 점차 바꾸었다.","scoring_points":["달라진 생활 세 가지를 썼는가","하나를 골랐는가","생각의 변화를 썼는가"]},"explanation":["양복·전차·신문이에요.","하나를 골라요.","생각이 바뀌었어요."],"asset":{"type":"passage","lines":["⑧ 항구가 열린 뒤 큰아버지는 양복을 입고 한복 입은 친구와 다녔다.","한결이 증조할아버지는 전차를 타고 소학교에 다니셨다.","집에서는 신문을 받아 보며 나라 밖 소식과 물건 광고를 읽었다."],"title":"한결이네 집안 이야기 책 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#1','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C1',1,'ox','auto','조선은 한양을 새 수도로 정했어요.',ARRAY['SO5-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-2-u2-C1","difficulty":1,"kind":"ox","stem":"조선은 한양을 새 수도로 정했어요.","answer":"O","reason_options":[{"t":"오늘날 서울의 한강 북쪽을 수도로 삼았기 때문에","correct":true},{"t":"조선은 수도를 정하지 않았기 때문에","mis":"SO5-2-u2-X01"}],"mis":"SO5-2-u2-X01","explanation":["새 수도가 필요했어요.","한양이에요.","오늘의 서울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#2','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C6',1,'ox','auto','조선의 신분은 실제로 양반·중인·상민·천민으로 나뉘었어요.',ARRAY['SO5-2-u2-X09']::text[],false,'{"seq":2,"concept":"SO5-2-u2-C6","difficulty":1,"kind":"ox","stem":"조선의 신분은 실제로 양반·중인·상민·천민으로 나뉘었어요.","answer":"O","reason_options":[{"t":"법은 양인·천인이었지만 실제 생활에서는 넷으로 나뉘었기 때문에","correct":true},{"t":"조선에는 신분이 없었기 때문에","mis":"SO5-2-u2-X09"}],"mis":"SO5-2-u2-X09","explanation":["법은 둘이에요.","실제는 넷이에요.","신분에 맞게 살았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#3','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C7',1,'ox','auto','『농사직설』은 우리 땅에 맞는 농사법을 담은 책이에요.',ARRAY['SO5-2-u2-X12']::text[],false,'{"seq":3,"concept":"SO5-2-u2-C7","difficulty":1,"kind":"ox","stem":"『농사직설』은 우리 땅에 맞는 농사법을 담은 책이에요.","answer":"O","reason_options":[{"t":"지방 농부들의 경험을 모아 만들었기 때문에","correct":true},{"t":"중국 농사책을 그대로 옮긴 책이기 때문에","mis":"SO5-2-u2-X12"}],"mis":"SO5-2-u2-X12","explanation":["농부의 경험을 모았어요.","우리 땅에 맞아요.","농사책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#4','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C11',1,'ox','auto','병자호란 때 임금은 남한산성으로 피했어요.',ARRAY['SO5-2-u2-X20']::text[],false,'{"seq":4,"concept":"SO5-2-u2-C11","difficulty":1,"kind":"ox","stem":"병자호란 때 임금은 남한산성으로 피했어요.","answer":"O","reason_options":[{"t":"청군을 피해 산성에 들어갔지만 곧 둘러싸였기 때문에","correct":true},{"t":"임금은 강화도에서 몽골과 싸웠기 때문에","mis":"SO5-2-u2-X20"}],"mis":"SO5-2-u2-X20","explanation":["청이 쳐들어왔어요.","산성으로 피했어요.","남한산성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#5','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C13',1,'ox','auto','한결이네 이야기 ⑤처럼 조선 후기에는 닷새마다 서는 장이 곳곳에 생겼어요.',ARRAY['SO5-2-u2-X23']::text[],false,'{"seq":5,"concept":"SO5-2-u2-C13","difficulty":1,"kind":"ox","stem":"한결이네 이야기 ⑤처럼 조선 후기에는 닷새마다 서는 장이 곳곳에 생겼어요.","answer":"O","reason_options":[{"t":"사고파는 일이 많아졌기 때문에","correct":true},{"t":"조선 후기에는 장사가 사라졌기 때문에","mis":"SO5-2-u2-X23"}],"mis":"SO5-2-u2-X23","explanation":["장사가 늘었어요.","장이 섰어요.","장시가 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#6','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C14',1,'ox','auto','조선 후기에는 양반이 늘고 상민과 천민이 줄어 신분제가 흔들렸어요.',ARRAY['SO5-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO5-2-u2-C14","difficulty":1,"kind":"ox","stem":"조선 후기에는 양반이 늘고 상민과 천민이 줄어 신분제가 흔들렸어요.","answer":"O","reason_options":[{"t":"돈으로 양반 신분을 사는 사람이 늘었기 때문에","correct":true},{"t":"양반이 크게 줄었기 때문에","mis":"SO5-2-u2-X24"}],"mis":"SO5-2-u2-X24","explanation":["양반을 샀어요.","양반이 늘었어요.","신분제가 흔들렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#7','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C18',1,'ox','auto','탈놀이에서는 탈을 쓰고 춤추며 양반을 비꼬기도 했어요.',ARRAY['SO5-2-u2-X32']::text[],false,'{"seq":7,"concept":"SO5-2-u2-C18","difficulty":1,"kind":"ox","stem":"탈놀이에서는 탈을 쓰고 춤추며 양반을 비꼬기도 했어요.","answer":"O","reason_options":[{"t":"백성이 하고 싶은 말을 탈 쓴 광대가 대신 했기 때문에","correct":true},{"t":"탈놀이는 양반을 칭찬만 하는 공연이었기 때문에","mis":"SO5-2-u2-X32"}],"mis":"SO5-2-u2-X32","explanation":["탈을 써요.","양반을 흉내 내요.","비꼬았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#8','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C20',1,'ox','auto','개항 이후 전신과 전화로 소식을 빠르게 주고받게 되었어요.',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":8,"concept":"SO5-2-u2-C20","difficulty":1,"kind":"ox","stem":"개항 이후 전신과 전화로 소식을 빠르게 주고받게 되었어요.","answer":"O","reason_options":[{"t":"전기 신호로 멀리 소식을 보냈기 때문에","correct":true},{"t":"전신과 전화는 밤을 밝히는 기구였기 때문에","mis":"SO5-2-u2-X35"}],"mis":"SO5-2-u2-X35","explanation":["전기 신호예요.","소식을 보내요.","빨라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#9','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C2',2,'error','auto','한양의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-2-u2-C2","difficulty":2,"kind":"error","stem":"한양의 이름을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수인 — 「돈의문의 「의」는 예절을 뜻해.」","correct":true,"mis_target":"SO5-2-u2-X03"},{"t":"태하 — 「보신각의 「신」은 믿음이야.」","mis":"SO5-2-u2-X03"},{"t":"민서 — 「숭례문의 「례」는 예절이야.」","mis":"SO5-2-u2-X03"}],"explanation":["「의」는 옳은 마음이에요.","예절은 「례」예요.","수인이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#10','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C5',2,'error','auto','관혼상제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO5-2-u2-C5","difficulty":2,"kind":"error","stem":"관혼상제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하빈 — 「관혼상제는 나라 큰 잔치만 뜻하고 집안과는 관계없어.」","correct":true,"mis_target":"SO5-2-u2-X08"},{"t":"서진 — 「혼례는 결혼이야.」","mis":"SO5-2-u2-X08"},{"t":"아준 — 「오늘날 제사도 그 전통이 이어진 거야.」","mis":"SO5-2-u2-X08"}],"explanation":["집안 행사도 포함해요.","결혼·장례·제사예요.","하빈의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#11','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C6',2,'error','auto','조선 여성을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO5-2-u2-C6","difficulty":2,"kind":"error","stem":"조선 여성을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「조선 여성은 처음부터 재산을 하나도 받지 못했어.」","correct":true,"mis_target":"SO5-2-u2-X11"},{"t":"주원 — 「전기에는 제사를 돌아가며 지냈어.」","mis":"SO5-2-u2-X11"},{"t":"세빈 — 「후기로 갈수록 맏아들이 제사를 맡았어.」","mis":"SO5-2-u2-X11"}],"explanation":["전기엔 똑같이 받았어요.","나중에 달라졌어요.","하린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#12','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C9',2,'error','auto','조선 전기 주변 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X16']::text[],false,'{"seq":12,"concept":"SO5-2-u2-C9","difficulty":2,"kind":"error","stem":"조선 전기 주변 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예온 — 「조선은 명과 늘 전쟁만 했어.」","correct":true,"mis_target":"SO5-2-u2-X16"},{"t":"서하 — 「일본·여진과는 무역도 했어.」","mis":"SO5-2-u2-X16"},{"t":"지오 — 「국경을 넘어오면 무력도 썼어.」","mis":"SO5-2-u2-X16"}],"explanation":["명과는 좋은 관계였어요.","사신을 보냈어요.","예온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#13','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C12',2,'error','auto','조선 후기 작물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X22']::text[],false,'{"seq":13,"concept":"SO5-2-u2-C12","difficulty":2,"kind":"error","stem":"조선 후기 작물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"마루 — 「감자는 팔기만 하고 아무도 먹지 않았어.」","correct":true,"mis_target":"SO5-2-u2-X22"},{"t":"아린 — 「감자는 배고픔을 덜어 주었어.」","mis":"SO5-2-u2-X22"},{"t":"주노 — 「담배는 팔아서 이익을 얻었어.」","mis":"SO5-2-u2-X22"}],"explanation":["감자는 먹을거리예요.","배고픔을 덜었어요.","마루의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#14','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C16',2,'error','auto','조선 후기 종교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X28']::text[],false,'{"seq":14,"concept":"SO5-2-u2-C16","difficulty":2,"kind":"error","stem":"조선 후기 종교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「천주교와 동학은 신분 차별을 더 굳히자고 했어.」","correct":true,"mis_target":"SO5-2-u2-X28"},{"t":"나연 — 「두 종교 모두 평등을 말했어.」","mis":"SO5-2-u2-X28"},{"t":"은결 — 「동학은 우리 것을 지키자고 했어.」","mis":"SO5-2-u2-X28"}],"explanation":["두 종교는 평등을 말했어요.","차별을 굳히자고 하지 않았어요.","지환의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#15','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C18',2,'error','auto','민화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X31','SO5-2-u2-X32']::text[],false,'{"seq":15,"concept":"SO5-2-u2-C18","difficulty":2,"kind":"error","stem":"민화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예솔 — 「민화는 유명한 궁궐 화가만 그린 그림이야.」","correct":true,"mis_target":"SO5-2-u2-X31"},{"t":"한결 — 「민화는 주로 이름이 알려지지 않은 화가가 그렸어.」","mis":"SO5-2-u2-X31"},{"t":"도유 — 「판소리는 북 장단에 맞춰 해.」","mis":"SO5-2-u2-X32"}],"explanation":["민화 화가는 이름이 알려지지 않았어요.","서민이 즐겼어요.","예솔의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#16','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C20',2,'error','auto','개항 이후의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X35']::text[],false,'{"seq":16,"concept":"SO5-2-u2-C20","difficulty":2,"kind":"error","stem":"개항 이후의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「전등이 생기면서 사람들이 소식을 빨리 주고받았어.」","correct":true,"mis_target":"SO5-2-u2-X35"},{"t":"채아 — 「전등으로 활동 시간이 늘었어.」","mis":"SO5-2-u2-X35"},{"t":"무진 — 「전화 교환수라는 새 직업이 생겼어.」","mis":"SO5-2-u2-X35"}],"explanation":["소식은 전신·전화예요.","전등은 빛이에요.","이든이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#17','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C4',3,'error','auto','유교가 조선 생활에 준 영향을 두고 친구들이 말했어요. 가장 알맞지 않은 친구는 누구인가요?',ARRAY['SO5-2-u2-X40','SO5-2-u2-X08','SO5-2-u2-X06']::text[],false,'{"seq":17,"concept":"SO5-2-u2-C4","difficulty":3,"kind":"error","stem":"유교가 조선 생활에 준 영향을 두고 친구들이 말했어요. 가장 알맞지 않은 친구는 누구인가요?","options":[{"t":"세온 — 「유교는 관리들만 알았고 백성 생활과는 관계없었어.」","correct":true,"mis_target":"SO5-2-u2-X40"},{"t":"하경 — 「집안 혼례와 제사도 유교 예절을 따랐어.」","mis":"SO5-2-u2-X08"},{"t":"준성 — 「『경국대전』은 백성의 일상에도 영향을 줬어.」","mis":"SO5-2-u2-X06"}],"explanation":["백성 생활에도 퍼졌어요.","집안 행사까지요.","세온의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#18','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C7',3,'error','auto','세종 때 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X12']::text[],false,'{"seq":18,"concept":"SO5-2-u2-C7","difficulty":3,"kind":"error","stem":"세종 때 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태라 — 「『농사직설』은 중국 농사책을 그대로 베낀 책이야.」","correct":true,"mis_target":"SO5-2-u2-X12"},{"t":"윤아 — 「지방 농부들의 경험을 모았어.」","mis":"SO5-2-u2-X12"},{"t":"라현 — 「우리 땅에 맞는 농사법이 담겼어.」","mis":"SO5-2-u2-X12"}],"explanation":["중국 책은 맞지 않았어요.","농부들의 경험을 모았어요.","태라의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#19','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C10',3,'error','auto','임진왜란을 이겨 낸 힘을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X18']::text[],false,'{"seq":19,"concept":"SO5-2-u2-C10","difficulty":3,"kind":"error","stem":"임진왜란을 이겨 낸 힘을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"루아 — 「임진왜란은 명군 혼자 이겨 냈고 조선은 한 일이 없어.」","correct":true,"mis_target":"SO5-2-u2-X18"},{"t":"정후 — 「이순신의 수군이 바다에서 활약했어.」","mis":"SO5-2-u2-X18"},{"t":"해나 — 「의병도 스스로 나서 싸웠어.」","mis":"SO5-2-u2-X18"}],"explanation":["수군과 의병도 싸웠어요.","여러 힘이 모였어요.","루아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#20','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C17',3,'error','auto','조선 후기 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X29','SO5-2-u2-X30']::text[],false,'{"seq":20,"concept":"SO5-2-u2-C17","difficulty":3,"kind":"error","stem":"조선 후기 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「조선 후기 경제가 나빠져서 서민 문화가 생겨났어.」","correct":true,"mis_target":"SO5-2-u2-X29"},{"t":"우진 — 「살림에 여유가 생겨 서민 문화가 발달했어.」","mis":"SO5-2-u2-X29"},{"t":"다솔 — 「전기수가 한글 소설을 읽어 줬어.」","mis":"SO5-2-u2-X30"}],"explanation":["경제가 나아졌어요.","여유가 생겼어요.","하늘의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#21','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C19',3,'error','auto','개항 무렵 조선의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u2-X33']::text[],false,'{"seq":21,"concept":"SO5-2-u2-C19","difficulty":3,"kind":"error","stem":"개항 무렵 조선의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「조선은 서양 배가 오자마자 기뻐하며 항구를 열었어.」","correct":true,"mis_target":"SO5-2-u2-X33"},{"t":"현우 — 「처음엔 통상 요구를 거부했어.」","mis":"SO5-2-u2-X33"},{"t":"소이 — 「교류를 두고 찬반 의견이 맞섰어.」","mis":"SO5-2-u2-X33"}],"explanation":["처음엔 거부했어요.","찬반이 있었어요.","은솔의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#22','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C21',3,'error','auto','한결이네 만화 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SO5-2-u2-X39','SO5-2-u2-X38']::text[],false,'{"seq":22,"concept":"SO5-2-u2-C21","difficulty":3,"kind":"error","stem":"한결이네 만화 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"로운 — 「⑦ 장터 장면에 고려청자를 파는 보부상을 그리자.」","correct":true,"mis_target":"SO5-2-u2-X39"},{"t":"다인 — 「⑦ 장면에 탈놀이를 보며 웃는 사람들을 그리자.」","mis":"SO5-2-u2-X38"},{"t":"수호 — 「⑧ 장면에 양복과 한복을 함께 그리자.」","mis":"SO5-2-u2-X38"}],"explanation":["고려청자는 고려 때 물건이에요.","조선 후기 장터와 맞지 않아요.","로운의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#23','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C16',4,'mc','auto','조선 후기와 개항 이후를 함께 볼 때 사람들의 생각에 나타난 공통된 흐름으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u2-X24','SO5-2-u2-X40','SO5-2-u2-X28']::text[],false,'{"seq":23,"concept":"SO5-2-u2-C16","difficulty":4,"kind":"mc","stem":"조선 후기와 개항 이후를 함께 볼 때 사람들의 생각에 나타난 공통된 흐름으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분과 남녀를 엄격히 나누던 생각이 점차 흔들리며 평등을 바라는 생각이 커졌다","correct":true},{"t":"신분 구별이 시간이 갈수록 더 엄격해졌다","mis":"SO5-2-u2-X24"},{"t":"사람들의 생각은 하나도 바뀌지 않았다","mis":"SO5-2-u2-X40"},{"t":"평등이라는 생각은 고조선 때 사라졌다","mis":"SO5-2-u2-X28"}],"explanation":["양반이 늘어 흔들렸어요.","동학이 평등을 말했어요.","전차도 생각을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#24','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C12',4,'essay','teacher','한결이네 이야기 ⑤를 보고 조선 후기 농업과 상업의 변화를 각각 쓰고, 그 변화가 신분이나 문화에 준 영향을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u2-C12","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ⑤를 보고 조선 후기 농업과 상업의 변화를 각각 쓰고, 그 변화가 신분이나 문화에 준 영향을 하나 쓰세요.","answer_guide":{"answer":"예: 농업 — 모내기법으로 일손이 줄고 벼 뒤에 보리까지 거두었으며, 고구마로 배고픔을 덜고 인삼을 길러 팔았다. 상업 — 닷새마다 서는 장시가 늘고 상평통보로 값을 치렀다. 그래서 부자가 된 사람이 돈으로 양반 족보를 사 신분제가 흔들렸다.","scoring_points":["농업의 변화를 썼는가","상업의 변화를 썼는가","신분이나 문화에 준 영향을 썼는가"]},"explanation":["모내기법과 새 작물이에요.","장시와 상평통보예요.","신분이 흔들렸어요."],"asset":{"type":"passage","lines":["⑤ 어린 모를 옮겨 심자 일손이 줄고 벼를 거둔 논에 보리도 심었다.","거친 밭에는 고구마를 심어 배고픈 겨울을 넘겼다.","인삼을 길러 닷새마다 서는 장에 내다 팔고 쇠돈을 받았다."],"title":"한결이네 집안 이야기 책 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u2_review_d#25','soc',5,2,'u2','','g5_2_soc_u2_review_d','unit_review','SO5-2-u2-C21',4,'essay','teacher','한결이네 이야기 ①~⑧ 가운데 하나를 골라 역사 만화의 제목과 네 칸 내용을 쓰고, 그 내용이 사실에 맞는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u2-C21","difficulty":4,"kind":"essay","stem":"한결이네 이야기 ①~⑧ 가운데 하나를 골라 역사 만화의 제목과 네 칸 내용을 쓰고, 그 내용이 사실에 맞는 까닭을 쓰세요.","answer_guide":{"answer":"예: ⑤를 골랐다. 제목 — 「인삼 한 뿌리, 쇠돈 한 꾸러미」. ① 어린 모를 옮겨 심는 가족. ② 거친 밭에 고구마를 심는 모습. ③ 기른 인삼을 닷새장에 내다 파는 모습. ④ 상평통보를 받아 웃는 모습. 조선 후기 모내기법과 새 작물, 장시와 상평통보가 퍼졌다는 사실에 맞다.","scoring_points":["이야기 하나를 골라 제목을 썼는가","네 칸 내용을 썼는가","사실에 맞는 까닭을 썼는가"]},"explanation":["하나를 골라요.","네 칸을 써요.","사실에 맞는지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
